window.__D("text/hemshech-ayin-beis/c005",{"p":[[3601330547,"(היינו עצמי' ההמשכה שמבחי' א\"א וחו\"ב בז\"א שזהו בחי' עצמי' המוחין ממש כו'), א\"א לבא בהתגלו' בבחי' טעם גם לא ע\"פ סוד, רק מבחי' שערות דז\"א בא ההתגלו' דבחי' היכלות דז\"א (י\"ל דזהו במדרי' אצי', והיינו שגם נשמו' דאצי' מה שמשיגים טעמי תו' זהו רק מבחי' שערות דז\"א כו', ועמ\"ש בסש\"ב פל\"ט דנשמו' עומדים בהיכלות ומדורין דברי' או יצירה ונהנין מזיו השכינה כו', הוא זיו תורתן ועבודתן כו', וי\"ל דכמו\"כ הוא ג\"כ בנשמו' דאצי' כו', ועמ\"ש באגה\"ק ד\"ה איהו וחיוהי חד). וזהו קווצותיו תלתלים שהן שערות דז\"א שבהם תליין דכיין ומסאבן היינו שזהו הגילוי דבחי' טעמי תו' המתגלה בהיכלות דז\"א כו', וכמו\"כ מבחי' מוחין חב\"ד דנוק' ששרשם משערות דז\"א אינו יכול לבא בעולמו' בי\"ע רק בחי' שערות לבד, וזהו דלת ראשך כארגמן כו'. ולכן בפנימי' התו' יש נגלה ונסתר וכן בחיצוני' התו', והוא דבחי' ודלת ראשך כארגמן זהו טעם הנגלה ממש כמו אוקי ממונא כו' והממע\"ה כו', והן רק בחי' שערות דנוק' כו', אבל מוחין עצמן דנוק' הן למע' מהשגה בבי\"ע, וזהו הנסתר של זה\nהטעם שלא בא לידי גילוי כו'. וכן בז\"א בחי' קווצותיו תלתלים זהו הנגלה שע\"פ הסוד, ועצם המוחין דז\"א זהו הנסתר שע\"פ הסוד כו', דבד\"כ בחי' מל' היא בחי' חיצוני' התו' וכמו מל' פה תושבע\"פ קרינן לה דהיינו בחי' הנגלה כו', וז\"א בחי' פנימי' התו' כו', ובשניהם יש נגלה ונסתר, דבחי' הנגלה הוא ע\"י השערות ובחי' הנסתר זהו מעצם המוחין כו', והיינו דבנגלה דתו' דבד\"כ הוא בחי' המל' הנה הטעם הנגלה הוא מבחי' שערות דנוק' כו', וע\"ז הוא שא' בת\"ז דודלת ראשך כארגמן הן טעמי תו' היינו הטעם הנגלה דחיצוני' התו' כו', והטעם הנסתר בזה הוא מהמוחין עצמן דנוק' כו', ופנימי' התו' שהיא בחי' ז\"א דאצי' הסוד הנגלה בזה הוא מבחי' שערות דז\"א, וז\"ע קווצותיו תלתלים המבו' באד\"ר, והנסתר היינו שאינו בא גם בבחי' סוד נגלה זהו מהמוחין עצמן דז\"א כו'. ולפ\"ז י\"ל דהנגלה שע\"פ הסוד זהו התו' כמו שהיא ברוחני', וכמו העסק בתו' דנשמו' בג\"ע וכמו תו' דאצי' דהגם שמדבר בענין ההשתל' ה\"ז בחי' סתום דתו' רק שזהו הנגלה שע\"פ הסוד כו', והנסתר הוא בחי' העונג וזהו עצם\nהמוחין כו', וכמ\"ש במ\"א דהמוחין בעצם מהותם הם בחי' תענוג כו', וכמשי\"ת, ובד\"כ הוא בחי' חיצוני' החכ' ופנימי' החכ' דפנימי' אבא פנימי' עתיק כו', ועפמ\"ש במ\"א (בד\"ה ביום ההוא יגלח כו') ההפרש בין שערות הראש לשערות הזקן דע\"ה שניהם מבחי' מותרי מוחין, הנה שערות הזקן הם ממותרי מוחין דגדלות, משא\"כ שערות הראש הן ממותרי מוחין דקטנות כו', ומבו' שם דג' מיני שערות דודלת ראשך וקווצותיו תלתלים ושער רישי' כו', כ\"ז הוא בחי' שערות הראש והן הלכות דתו' כו' יעו\"ש. ולפ\"ז י\"ל דבחי' הנגלה גם מבחי' פנימי' התו' והיינו התו' כמו שהיא למע' זהו מבחי' שערות הראש דבד\"כ זהו בחי' קטנות כו', והן בחי' מותרות ונובלות שיוצאין בבחי' פירוד כו', ועז\"א דאורייתא מתקשראה בקוב\"ה כו', ובחי' הסתום זהו מבחי' שערות הזקן וכמ\"ש כשמן הטוב על הראש יורד על הזקן כו', והוא ההמשכה מבחי' פנימי' הכתר כו', ועז\"א אורייתא וקוב\"ה כולא חד כו'.\nוע\"פ הנ\"ל יובן מ\"ש צדק צדק תרדוף כו'.\n<span data-k=\"ks\"><b>קיצור.</b> אך צ\"ל שהרי גם סתים דתורה היא בהתלת קשרין, אך הענין דגם בסתים יש נגלה ונסתר וכן בגליא דתו', דגלי' דתורה היא בחי' מל', והנגלה שבזה</span>"],[3601330548,"<b>הוא</b> מבחי' שערות דמל', והנסתר מעצם המוחין, וסתים בז\"א, והנגלה משערות דז\"א, והנסתר מעצם המוחין דז\"א, וי\"ל שזהו שערות הראש קטנות ושערות הזקן גדלות, וי\"ל דהנגלה שבסתים זהו התו' שברוחניות, והנסתר הוא בחי' העונג, ובבחי' זו הוא כולא חד."],[3601330549,"<h3>בס\"ד. ש\"פ תצא, תער\"ג</h3>\n<b>כי</b> תצא למלחמה על אויביך ונתנו ה' אלקיך בידיך ושבית שביו כו', וצ\"ל דמתחלה אומר כי תצא למלחמה ה\"ז בכח עצמו ואח\"כ ונתנו ה' אלקיך הרי שנותנים מלמע' כו'. וגם מ\"ש אח\"כ ושבית שביו אחרי שנתנו ה' אלקיך כו' מהו\"ע השבי' שהרי שבי' זהו שבא בדרך הכרח ומאחר דונתנו ה' אלקיך מהו\"ע השבי' כו'. גם צ\"ל אומרו ושבית שביו דהול\"ל שבי' וכמ\"ש אח\"כ וראית בשבי' כו', דשביו משמע שביו של אויב, וצ\"ל מהו\"ע ושבית שביו של אויב כו'. גם מהו\"ע וראית בשבי' אשת יפת תואר כו'. ולהבין כ\"ז ילה\"ק משנת\"ל לתווך ב' מאה\"ז דלפעמים אי' תלת קשרין מתקשראין דא בדא קוב\"ה אורייתא וישראל, דהתקשרות שייך בדבר הנבדל דוקא דבדבר א' כמו אור ומאור אינו שייך התקשרות כ\"א בדבר הנבדל כו', הרי דתו' היא בבחי' נבדל והיא בבחי' התקשרות כו', ופעמים אי' אורייתא וקוב\"ה כו\"ח ה\"ה בבחי' חד ממש לא רק בבחי' התקשרות כו'. דזהו ההפרש בין תו' למצות דהיחוד שע\"י המצות הוא ע\"ד איהו וגרמוהי חד שהן ב' דברים המתייחדים כו', והיחוד דתו' הוא כמו איהו וחיוהי שזהו בבחי'\nיחוד ממש כו'. ונת' שזהו ההפרש בכלל בין בחי' חיצוני' התו' ופנימי' התו', דחיצוני' התו' ה\"ה אותי' התו' שהאותי' ה\"ה דבר בפ\"ע כו', ועוד שהרי כל התו' נתלבשה בענינים גשמי' שהן דברים נפרדים וממילא גם חכ' התו' שבזה הוא דבר נבדל כו', וגם התו' כמו שהיא ברוחני' בג\"ע הרי מדברת בעניני הנבראים כו', וגם התו' כמו שהיא באצי' הרי מדברת בעניני השתל' כו', ובכל מקום התו' היא בבחי' השגה דגם תו' דאצי' ה\"ה בהשגה באצי' כו', וע\"כ כ\"ז בכלל בחי' חיצוני' התו' שהיא רק נובלות חכ' שלמע' כו', וע\"כ שייך בזה ענין ההתקשרות כו'. ועיקר פנימי' התו' הוא בחי' העונג שבתו' ובמדרי' זו שבתו' אמרו אורייתא וקוב\"ה כולא חד כו'. ובזה מיושב ג\"כ מה שבמא' דתלת קשרין אמרו וכולהו כו' סתים וגליא, הרי גם סתים דתו' היא בבחי' התקשרות כו'. הענין הוא דהן בחיצוני' התו' והן בפנימי' התו' יש סתים וגליא כו', ופנימי' התו' שבאה בהשגה בג\"ע ובאצי' ה\"ז בחי' הנגלה שע\"פ הסוד (והיא בכלל בחי' חיצוני' התו' והיינו בחי' החיצוני' שבפנימי' כו'), ובזה שייך ג\"כ\nהתקשרות לפי שכ\"ז מבחי' נובלות חשמ\"ע כו', ועיקר הפנימי' הוא בחי' הסתים שלמע' מהשגה והיינו בחי' העונג שבתורה כו', ובמדרי' זו התורה היא בבחי' חד ממש כו'."],[3601330550,"קפג) <b>אמנם</b> באמת גם על חיצוני' התו' אמרו אורייתא וקוב\"ה כולא חד, דהרי בסש\"ב פכ\"ג אומר על האדם העוסק בתו' שנעשה בבחי' יחוד ע\"ד אורייתא וקוב\"ה כו\"ח, והכוונה היא גם על העסק בחיצוני' התו' כו', דאא\"ל דהכוונה היא על העוסק בפנימי' התו' דוקא שהרי מחלק שם רק בין המצות לתו' שע\"י עסק המצות היחוד הוא כמו יחוד האברים כו', וע\"י התו' היחוד הוא בבחי' חד ממש כו', הרי שהכוונה על עסק התו' בכלל גם בחי' חיצוני' התורה כו'. ויותר מובן כן בפ' דו\"ה דמבו' שם איך שע\"י השגת התו' ה\"ה מתייחד ותופס בבחי' עצמות א\"ס דלית מתב\"כ כ\"א כאשר איהו תפיסא באורייתא ומצותי' כו', ושם הכוונה בבחי' השגה דוקא שעי\"ז נעשה מקיף ומוקף כו', וכ' שם בפ\"ד דאורייתא היא חכמתו כו' וקוב\"ה בכבודו ובעצמו כו\"ח כו', הרי שמש\"כ בזהר אורייתא וקוב\"ה כו\"ח הוא גם בתו' כמו שבאה בבחי' חכ' והשגה דהיינו בד\"כ בחי' חיצוני' התו' כו'. וא\"ז סותר למש\"א דאורייתא מתקשראה בקוב\"ה שנת\"ל פקע\"ה דהיינו כמו דבר הנבדל שמתקשר כו', דהתו' גם כמו שהיא בבחי' דבר הנבדל\nהרי היא כו\"ח ממש כו'. וזהו משום ב' דברים, הא' להיות שהתו' כמו שהיא בבחי' שעשועים העצמי' נמשך הארת בחי' התענוג בכל המדרי' דתורה גם כמו שירדה למטה כו' וכמשי\"ת, והארה זו היא ג\"כ בחי' עצמי' כו' (ולא כמו הארה שבעולמות שאינה העצם כידוע, והארת התענוג שבתו' גם ההארה היא עצמי' כו'), ומתייחדת היא עם הידיעת והשגת התו' כו'. והב' שגם עצם החכמה דתו' שהיא הידיעה וההשגה ה\"ה ג\"כ בחי' עצמות א\"ס ב\"ה כו'. והענין הוא דהנה כתי' ואהי' אצלו אמון כו', וחשיב בפסוק זה ה' ענינים בתורה, א' ואהי' אצלו אמון, ב' ואהי' שעשועים יום יום, ג' משחקת לפניו בכל עת, ד' משחקת בתבל ארצו, ה' ושעשועי את בנ\"א, וכל הה' מדרי' הכל הוא בבחי' העונג כו', ומדבר בה' מדרי' שהתורה ירדה ונמשכה כו', והיינו התו' כמו שהיא בשרשה ומקורה בחי' הכתר כו', ואח\"כ כמו שירדה בחו\"ב ואח\"כ בז\"א ובמל' ובעולמות בי\"ע כו', והכל הוא בהמשכת העונג בכל המדרי' האלו, ובחי' הכתר הכוונה הוא על בחי' פנימי' הכתר שהרי העונג הוא בחי' פנימי' הכתר כידוע. ונודע דבכלל כתר נכלל\nכל המדרי' שלמע' מאצי' גם בחי' א\"ק (הגם שנת\"ל פקס\"ה וקס\"ו דא\"ק מובדל מכל המדרי' בזה שהוא בחי' כלל על הכל בשוה כו', מ\"מ ה\"ז נכלל בכלל כתר שהרי או' במ\"ח שהוא כדוגמת אריך כו', ומכ\"ש דבחי' פנימי' א\"ק נכלל בכלל בחי' הכתר כו'), והתו' כמו שהיא בכתר זהו התו' כמו שהיא בבחי' שעשועים העצמי' כו', ואח\"כ הוא המשכת בחי' העונג בחו\"ב כו', ועל התו' כמו שהיא בבחי' שעשועים העצמי' א' באגה\"ק ד\"ה דוד זמירות כו' שעז\"א א\"ת אמון אלא אומן כו'. והנה על המדרי' א' או' ואהי' אצלו אמון, ואי' בת\"ז תי' מ\"ב אמון מופלא ומכוסה דאיהו אין כו', והיינו דמופלא ומכוסה שניהם בכתר רק דמופלא הוא פנימי' הכתר ומכוסה הוא חיצוני' הכתר כו' (ובמ\"א אי' להיפך ושרש הדבר במ\"ש לא נפלאת היא ולא רחוקה שיש בזה ב' פי'), וכמ\"ש במ\"א בענין שכל מופלא ושכל נעלם דשכל נעלם הוא בחי' מו\"ס שהוא בחי' העלם של הגילוי וה\"ז בבחי' שייכות לחכ' דאצי' כו', ושכל מופלא הוא שמופלא ומובדל בערך שזהו בחי' חכ' דא\"ק כו', ובמאו\"א אות א' סצ\"ה אי' אמון מופלא נק' מו\"ס כו'. וי\"ל דכל בחי' חכ' בבחי' הפנימי' שבה נק' מופלא וע\"כ נק'"],[3601330551,"חכ' דעתיק בשם מופלא דבעתיק הכל בבחי' פנימי' כו', וכן חכ' שבכתר וגם חכ' דאצי' בחי' הפנימי' הוא בחי' מופלא כו', ומכ\"ש דחכ' דא\"ק הוא בבחי' מופלא כו', ואפשר י\"ל דחכ' דא\"ק הוא בבחי' אמון סתם שלמע' גם מבחי' מופלא כו', וזהו מ\"ש בפסוק סתם ואהי' אצלו אמון כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ובאמת גם חיצוניות התורה שהיא בהשגה ובבחי' נבדל היא כולא חד, הא' מפני שהארת עונג העצמי (שהיא ג\"כ עצמי) יש בכל המדרי' שבתו', והב' מפני שחכ' דתורה היא עצמי, והענין דבפסוק ואהי' אצלו אמון חשיב ה' דברים, והן הה' מדרי' שירדה בהם התורה, חו\"ב זו\"נ בי\"ע, והכל מדבר בהמשכת פנימיות הכתר בחי' עונג, שהמדרי' הא' היא ואהי' אצלו אמון, אמון מופלא ומכוסה, שכל מופלא עתיק, וי\"ל דכל פנימיות חכ' נק' מופלא, וי\"ל דחכ' דא\"ק נק' אמון סתם.</span>\nקפד) <b>וביאור</b> הענין ילה\"ק מ\"ש (ישעי' כ\"ה) הוי' אלקי אתה ארוממך אודה שמך כי עשית פלא עצות מרחוק אמונה אומן, ואי' בזהר בלק קצ\"ג ע\"ב הוי' רזא עילאה שירותא דנקודה עילאה כו'. ומבו' במ\"א (ע\"פ מאה\"ז הנ\"ל) דבג' תיבות הוי' אלקי אתה, נכללים הג' פרצופים דאו\"א וז\"א, וכנודע דהוי' הוא בחכ', וזהו היו\"ד דש' הוי' שמורה על בחי' החכ' בפרט והוא עיקר ש' הוי' כו', והקוצו ש\"י רומז על הכתר מקור החכ' וכמ\"ש והחכ' מאין דכתר כו', ואח\"כ אלקי הוא בחי' הבינה שנק' אלקים חיים כו', ומ\"ש אלקי משום דהכוונה כאן על בחי' התבונה מקור המדות כו', ואתה הוא בחי' חסד דז\"א כו', והן בחי' החסדים שמתגלים למטה מהחזה בבחי' מל' וכמ\"ש אתה כהן לעולם על דברתי מלכי צדק, אתה כהן לעולם היינו בחי' החסד דכהן איש החסד כו', ועל דברתי מלכי צדק הוא המשכת החסד בבחי' המל' כו' וכמ\"ש במ\"א. ונמצא דג' תי' הוי' אלקי אתה כולל כללות ההשתל' כו', ועז\"א ארוממך והיינו לרומם ג' מדרי' בבחי' הכתר, וכדאיתא בזהר בשלח דנ\"ה ע\"ב ע\"פ אלקי אבי וארוממנהו כמד\"א\nאלקי אברהם היינו בחי' חכ' שנק' אלקי אברהם כו', אר\"י אי הכי מאי וארוממנהו דהא אלקי אברהם לעילא הוא, והיינו דבחי' חכ' הוא מדרי' גבוה כו' (וי\"ל מפני שהיא למע' מהעולמות כו', דמקור העולמות הוא מבחי' המדות וכמ\"ש זכור רחמיך וחסדיך כי מעולם המה, אבל חכ' היא למע' ממקור לעולמות כו'), א\"ל אפי' הכי אצטריך כו' דגם בחי' חכ' צריכה הרמה להעלותה בבחי' הכתר, דעיקר הרוממות הוא בחי' הכתר וכמ\"ש המלך המרומם לבדו דקאי על בחי' פנימי' הכתר וכמשנת\"ל פ\"ל, ובחי' חכ' הגם שהיא למע' מבחי' מקור לעולמות כו', מ\"מ ה\"ה ראשית ההשתל' ונק' חכ' ידיעא כו', וכמשנת\"ל (ד\"ה נשא הב') דמש\"א חכים ולא בחכ' ידיעא היינו בחי' החכ' שלמע' מאצי', אבל חכ' דאצי' הוא בחי' חכ' ידיעא כו', וכתר שנק' רם היינו שלמעלה מגדר השגה וידיעה כו', וז\"ע יד רמה היינו מה שלמע' מהשגה כו', דיד הגדולה ויד החזקה נא' בה' הידיעה לפי שהן בבחי' השגה כו', ויד רמה נא' בלא ה' לפי שזהו למע' מהשגה כו', וע\"כ צריכים לרומם בחי' החכ' ברוממות הכתר כו'. דהנה כתי' ויקרא הוי' הוי'\nשיש ב' שמות הוי', הא' ש' הוי' דאצי' והוא בחי' החכ', והב' ש' הוי' דעתיק, וזהו הוי' אלקי אתה ארוממך לרומם ש' הוי' דאצי' לש' הוי' דעתיק כו', והוא בכדי להמשיך אור חדש מבחי' פנימי'"],[3601330552,"הכתר כי כל העלאה גורמת המשכה כו', וע\"י שמרומם בחי' ההשתל' בבחי' הרוממות דכתר שזהו בד\"כ עליית בחי' אדם בבחי' כי לא אדם הוא כו', ממשיכים עי\"ז מבחי' רוממות הכתר גילוי אור חדש כו'. וכמ\"ש במ\"א בפי' ארוממך אלקי המלך שיש בזה ב' פי' (ועמשית\"ל), א' מלמטלמ\"ע והב' מלמעלמ\"ט, והוא ע\"י שמרוממים בחי' אלקי המלך מלמטלמ\"ע עי\"ז ממשיכים בחי' הרוממות דא\"ס מלמעלמ\"ט כו'. וכן בענין תרומה יש ב' פי', הא' ל' רוממות והוא מלמטלמ\"ע, והב' ל' הפרשה שזה בבחי' המשכה מלמע' למטה כו'. וז\"ע ב' פרשיות דק\"ש שמע והא\"ש דפ\"ר היא ש' מ\"ב בבחי' העלאה מלמטלמ\"ע כו', דש' מ\"ב עולה ואינו יורד כו', והיינו העלי' במדרי' גבוה ונעלית ביותר ע\"ד עד ולא עד בכלל כו', והוא בפ\"ר דק\"ש בה' אחד שהוא למסו\"נ באחד דמס\"נ הוא ביטול כל הרצונות והיינו גם הרצון בהגילוים כו', והיינו שאין הכוונה רק בביטול רצונות הגוף שהן הרצונות החומרי' בעניני העולם שזהו חיצוני' העולם כו', אלא ביטול הרצונות גם בהגילוים שבעולמות (שזהו בבחי' הרגש עצמו כו') שאין רצונו בהגילוים\nכ\"א בבחי' עצמו' אוא\"ס כו', וכמ\"ש מי לי בשמים ועמך לא חפצתי כו', ועי\"ז ההעלאה בכללו' ההשתל' דהיינו הגילוים כו', דע\"י שפועל בעצמו הביטול שאינו רוצה בהגילוים כ\"א בבחי' עצמות כו', נעשה עי\"ז העלאת כל הגילוים בבחי' עצמו' אוא\"ס כו', וכן באה' דבכל מאדך שהיא בלתי מוגבלת והוא בחי' הרצוא בעצמו' אוא\"ס כו'. וזהו ג\"כ ענין יד רמה דכתי' ובנ\"י יוצאים ביד רמה, פי' יוצאים בבחי' יציאה מגדר כלים וכמ\"ש אליך ה' נפשי אשא, אליך ה' בחי' הוי' שבעצמו' כו', וכמא' מי כה' אלקינו בכל קראינו אליו, אליו ולא למדותיו, היינו לבחי' עצמו' אוא\"ס שלמע' מבחי' האור המתלבש בכלים שזהו בחי' מדותיו כו', ועי\"ז אח\"כ ההמשכה בפ' שני' דק\"ש שנא' בה והא\"ש תשמעו אל מצותי דמצות הן בחי' המשכות והן גילוי הרצון כו', אך ע\"י הקדמת האה' דבכל מאדך אז המצות הן בבחי' ערש\"מ שממשיכים בחי' הרצון היינו בחי' פנימי' הרצון כו'. וזהו ג\"כ מש\"א ה' אלקי אתה ארוממך לרומם בחי' ההשתל' עד גם בחי' המל', שזהו מ\"ש אתה דהיינו התגלות החסדים עד בחי' המל' כנ\"ל, וגם ידוע\nדהמל' נק' אתה וכמ\"ש בסי' בפי' ברוך שאמר דתי' אתה הוא בג' מדרי' כו', וע\"י הרצוא במס\"נ מרוממים בחי' המל' וכללות ההשתל' בבחי' עצמו' אוא\"ס כו', ועי\"ז נמשך בחי' רוממות העצמות בחי' גילוי אור חדש כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ויקדים מ\"ש ה' אלקי אתה ארוממך, ה' חכ', אלקי תבונה, אתה חסד למטה מהחזה שמאיר במל' שנק' ג\"כ אתה, ארוממך לרומם כללות ההשתל' בכתר בחי' יד רמה, שגם חכ' צריכים לרומם בכדי שיומשך גילוי אור חדש, וכמו תרומה הרמה והפרשה, והן ב\"פ דק\"ש שע\"י מס\"נ להכלל בעצמות למעלה מכל הגילוים נעשה עליית כל הגילוים, ונמשך או\"ח ע\"י המצות.</span>\nקפה) <b>והענין</b> הוא דהנה פ' זה א' ישעי' הנביא בנבואה כעין הקדמה על הנבואה שאח\"ז שמנבא על מפלת בחי' מל' דק\"נ, וכמ\"ש בפסוק שאח\"ז כי שמת מעיר לגל כו', עיר הוא בחי' מל' דנוגה, והבחיי בענין ואלה המלכים כו' כ' מעיר אותי' מיער והו\"ע יכרסמנה חזיר מיער כו', ומ\"ש ושמת מעיר לגל הוא"],[3601330553,"ביטול מל' דנוגה כו'. וכאשר יתבטל ק\"נ אז יבא משיח שהוא בחי' המל' שתתעלה בבחי' אור הכתר (והיינו שבמל' יהי' גילוי אור הכתר ממש ותהי' במדרי' הכתר כו'), וכמ\"ש ועת\"י יתיב מלכותי' מלכות עלם, דכאשר יאיר אור הכתר בחי' עתיק במל' אז תהי' מלכותי' מלכות עלם בבחי' נצחי', וכמ\"ש ה' ימלוך לעולם ועד בבחי' נצחי' דא\"ס כו'. דהרי ע\"פ ס' השתל' הנה המל' היא בבחי' חסרון אור שזהו\"ע מיעוט הירח כו', וגם כאשר ממשיכים הגילוים דס' השתל' בבחי' מל' שעי\"ז נעשה המילוי בבחי' מל' שז\"ע די מחסורו כו' הרי אין מילוי לגמרי כו' (שהרי אי אתה מחוייב לעשרו כו', וכמשנת\"ל פקנ\"ז), כ\"א כאשר הגילוי הוא מבחי' רוממו' הא\"ס דהיינו בחי' פנימי' עי\"ז נעשה רוממו' המל' להיות בבחי' נצחי' דא\"ס כו'. ובכדי שיהי' גילוי בחי' פנימי' הכתר ה\"ז דוקא בהקדם תחלה מפלת מל' דק\"נ, דכל זמן שלא נתבער רוח הטומאה א\"א שיהי' המשכת בחי' הפנימי' כו', דמבחי' חיצוני' אוא\"ס יכול להיות הגילוי גם כשלא נתבטל ק\"נ לגמרי מפני שהגילוי הוא בבחי' מקיף לבד כו', אבל להיות גילוי בחי'\nהפנימי' דאוא\"ס (שצריך כלי דוקא כו' וכמ\"ש במ\"א), והגילוי הוא בבחי' פנימי' בנש\"י כו', צ\"ל קודם ביטול דק\"נ כו'. וכמ\"ש באריכות בלק\"ת ד\"ה למנצח על השמינית שלבחי' חיצוני' א\"ק להיות שהוא בבחי' מקיף לבד אין לזה שום דבר המונע כו', אבל להיות גילוי בחי' פנימי' א\"ק שזהו גילוי בבחי' פנימי' דוקא צ\"ל הסרת הדברים המסתירים כו', וז\"ע מצות מילה להסיר ההעלמות וההסתרים בכדי שיהי' גילוי בחי' פנימי' א\"ק כו'. וזהו הטעם דשכר מצוה בהאי עלמא ליכא, דשכר מצוה הוא עצמות האור של המצוה ושיאיר בבחי' גילוי ממש בבחי' פנימי' כו', וזה יהי' דוקא לעתיד שיהי' וחד חרוב דהיינו שתתבטל ההנהגה דעכשיו שמק\"נ ויהי' שמם מזה אז יהי' גילוי אור עצם המצות כו', ועמ\"ש בסש\"ב פל\"ז. ועוד זאת שהרי כתי' ולאום מלאום יאמץ וכתיב אמלאה החרבה לא נתמלאה צור אלא כו', וכמו\"כ הוא להיפך דמילוי הקדושה הוא ע\"י חורבנה של צור כו', והו\"ע יתרון האור שמתוך החשך שע\"י דאתכפי' ואתהפכא חשול\"נ עי\"ז דוקא נעשה יתרון האור כו'. והנה בכדי שתתבטל ק\"נ לגמרי זהו דוקא ע\"י\nהמשכת אור חדש מעצמו' אוא\"ס ב\"ה כו', והענין דהנה כתי' והסירותי מחלה מקרבך, ופי' מחלה הוא מקור החולי וכמא' מחלה זו מרה והוא בחי' ק\"נ כו' וכמ\"ש במ\"א, ובכדי להסיר המחלה או' והסירותי בעצמי כו', דקודם לזה א' ועבדתם את ה' אלקיכם וברך את לחמך כו' שנא' בל' נסתר והוא כמו שלישי המדבר, ונת\"ל ספקס\"ט דשלישי המדבר והמספר זהו בחי' עצמו' אוא\"ס המספר איך וידבר הוי' אל משה כו', וענין הספור הוא ההמשכה מבחי' אוא\"ס לש' הוי', וכמו אנכי ה' אלקיך שמאנכי נמשך להיות הוי' באצי' ומהוי' דאצי' נמשך למשה כו' (ועמ\"ש לעיל פק\"ע), וזהו ג\"כ ענין ועבדתם את ה' אלקיכם שזהו ההמשכה מבחי' שלישי המדבר בחי' אוא\"ס שלמע' משם הוי' להיות הוי' והוא כדי להיות אלקיכם אלק' שלכם כו'. ועי\"ז וברך את לחמך כו' קאי על ש' הוי' כי הברכה נמשך מש' הוי', וכידוע דברוך בחכ' כו' והוא ההמשכה מהעלם אל הגילוי כו', והיינו דלאחר שנמשך מעצמו' אוא\"ס בש' הוי' אזי נמשך הברכה מש' הוי' מבחי' החכ' מהעלם אל הגילוי כו'. אבל אין בזה התחדשו' ושינוי דבר רק מה שהוא\nבשרשו ומקורו יומשך בהתגלות כו', וכמ\"ש הבחיי גבי אסוך שמן דאלישע שז\"ע הברכה מיש ליש להגדיל הברכה (והיינו שתהי' ההמשכה כמו שהיא בשרשה כו'), וזה ביכולת הנביאים כו', וכך הברכה שיהי' וברך את לחמך זהו נמשך מבחי' חכ' כו'. ואח\"כ והסירותי כמדבר בעד עצמו והיינו גילוי בחי' עצמו' אוא\"ס ממש,"],[3601330554,"דמתחלה או' כשלישי המדבר שא\"ז גילוי בחי' העצמו' כ\"א מה שנמשך בש' הוי', ואח\"כ ההמשכה היא מהעלם אל הגילוי שז\"ע הברכה שא\"ז בבחי' התחדשות ממש כו', אבל להיות והסירותי מחלה שיעקר המחלה לגמרי מעיקרה שזהו כעין שינוי יש מאין זהו דוקא ע\"י ההמשכה מבחי' עצמות אוא\"ס ממש כו'. דהנה כל בחי' התחדשו' מעיקרו וכמו הנס שהוא היפך הטבע להפוך כל הצירופים שנבראו בהם כל העולמות צריך שיבא האור מבחי' עצמו' אוא\"ס דוקא, וכמ\"ש במ\"א בענין קשה לזווגם כקרי\"ס, דקי\"ס הוא קשה כבי' להיות שזהו שינוי הטבע כו' (ובמ\"א נת' דהקושי דקי\"ס הוא מה שהי' חבור עדאת\"כ עם עדאת\"ג והיינו שהיו במציאותם כמו שהן בבחי' עדאת\"ג והי' בהם הביטול דעדאתכ\"ס כו', וי\"ל דכמו\"כ הביטול דק\"נ הוא לא שתתבטל לגמרי ממציאותה כ\"א שתצא מטומאתה ומחולאתה ותתהפך לקדושה, והוא הענין שלעתיד יתהפך הגוף ויהי' אלקו' כו', שזהו למע' הרבה במדרי' מחבור עדאת\"ג ועדאתכ\"ס כו'), וכתי' גבי קי\"ס מה תצעק אלי בעתיקא תלי' מלתא, דבכדי שיהי' הפך ים ליבשה זהו מבחי' עתיק שזהו גילוי אור חדש\nשאינו בגדר העולמו' ומזה דוקא יהי' ההתחדשו' כו'. ועמ\"ש הרמ\"ז פ' בשלח דנ\"ד ע\"א שב' מיני זווגים יש למע', א' מסוד החיצוני' שאינו פוסק כו' ובו מתנהג הטבע המוטבע בארץ כו', והב' הוא זווג הפנימי' כו', והיותר מובחר הוא בהמשכה מעתיק, ואז תתחדש בעולם הנהגה מחודשת והיא עשיית הנסים השולטים על הטבע כו'. וכמו\"כ הוא בכדי להסיר מקור החולי שהוא בחי' ק\"נ עז\"א והסירותי בעצמי כו' (ולפעמים כתי' והסיר ה' ממך כל חולי י\"ל דחולי הוא בחי' התפשטו' לבד וכמארז\"ל זה הרעיון כו'). והנה ידוע דלחמך זו תו' שעז\"א ג\"כ וברך כו', י\"ל שזהו הבירורים בכח התו' שהוא הרחבת מקום הקדושה כו', וכמ\"ש במ\"א בענין ואלה מוסיף על הראשונים כו', ובכדי להיות ביטול הק\"נ לגמרי זהו בכח עצמו' ופנימי' התו' דוקא כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וזהו הקדמה למ\"ש אח\"כ ושמת מעיר לגל מל' דק\"נ שמסתיר על גילוי הפנימיות דוקא, וכשתתבטל יבא משיח גילוי עתיק ויהי' מלכותו מלכות עלם, וגם דלאום מלאום יאמץ, יתרון האור מהחשך, ובכדי שיתבטל מל' דק\"נ צ\"ל גילוי או\"ח, ועבדתם את ה' אלקיכם שלישי המדבר שיהי' גילוי ש' הוי', וברך הוי' את לחמך, מהעלם אל הגילוי, גם לחמך הבירורים שע\"י התו' שזהו רק שמרחיב מקום הקדושה, והסירותי מחלה ק\"נ שיעקר לגמרי זהו והסירותי בעצמי.</span>\nקפו) <b>ועד\"ז</b> יובן כאן דבכדי לעשות נס בהיפך הטבע כמו להפיל שר דק\"נ הי' צריך להמשיך אור חדש כו', ועז\"א בנבואתו פסוק דה' אלקי אתה ארוממך להעלות הכל לעצמו' אוא\"ס ב\"ה להמשיך משם אור חדש זה כו', ובאמת המשכת אור חדש זה הוא הגבה למע' מאד על כל המשכת אורות שנמשכו גם ביצי\"מ כו', וכמ\"ש הרמ\"ז ס\"פ בא ד\"מ ע\"ב ההפרש בין משה למשיח, דמשה המשיך מבחי' פנימי' אריך שהוא חיצוני' עתיק ומשיח ימשיך בחי' פנימי' עתיק ממש, וי\"ל דזהו מה שע\"י משה נתגלה בחי' מטר דתו' שזהו בחי' ז\"ת דעתיק, וכידוע בענין גשם שזהו אור שבעת הימים כו', והגם דבאמת במ\"ת ניתן הכל שהרי לא יהי' מ\"ת עוד הפעם כו', ולכן פעל משה בנשמו' הגבוהות עכ\"פ להיות תורתן אומנתן דהיינו המשכת התו' כמו שהיא בשרשה ומקורה בעצם התענוג הפשוט"],[3601330555,"העצמי כו' וכמ\"ש במ\"א, מ\"מ מה שבא בהתגלו' הוא בחי' מטר דתו' דהיינו בחי' חיצוני' התו' מה שבא בהשגה כו'. ומשיח יגלה בחי' פנימי' התו' בחי' טל תו' שזהו בחי' ג\"ר דעתיק כו', והיינו כמו שהתו' היא בבחי' חכה\"ק דא\"ק תענוג העצמי כו' (וי\"ל ג\"כ שזהו בחי' קוב\"ה דאסתכל באורייתא דהיינו בחי' א\"ס המתלבש בחכ' דא\"ק ובפנימי' התו' כו'). ואופן הגילוי יהי' בבחי' ראי' ממש והוא בחי' ראיית המהות כמו ראיית העין כו', ויהי' בשוה בכאו\"א מישראל כו', והיינו מפני שיהי' הגילוי מבחי' עצמו' א\"ס ממש כו'. והמשכה זו היא ע\"י ה' אלקי אתה ארוממך ואזי יומשך מפנימי' עתיק כו', וזהו שאומר אח\"כ אודה שמך פי' להמשיך האור החדש הזה גם בבחי' המל' דאצילות שנק' שמך בכדי שיהי' הגילוי בבי\"ע כו'. ומש\"א אודה הכוונה היא בבחי' המשכה לא לענין העלאה כי אחר שאמר ארוממך בהעלאה כו' אמר אודה שמך למטה ג\"כ כו', ואומר אודה להיות כי הודאה הוא בבחי' עצמות כו' כידוע בענין ברכה והודאה כו', רק שבכ\"מ הודאה היא בבחי' העלאה וכאן הכוונה על ההמשכה כו'. ועוי\"ל מ\"ש\nאודה שמך להיות דהמשכת אור חדש אינו מאיר עדיין בבחי' פנימי' כו', דההמשכה בפנימי' יהי' כאשר יתבטל מל' דק\"נ לגמרי כו', וכאן ההמשכה הוא בכדי לפעול הביטול כו', וכידוע דבכל המשכה שע\"י עבודה בהסרת ההעלמות הנה בכדי להסיר ההעלמות ההמשכה היא ממדרי' זו גופא כו', וכמו\"כ כאן המשכת האור חדש הוא בכדי לבטל ק\"נ כו', הרי ההמשכה אינו עדיין בבחי' פנימי' ע\"כ או' ע\"ז אודה כו', וההמשכה היא מבחי' מל' דוקא שז\"ע אודה שמך כו', והוא בחי' המשכת אור חדש זה גם בבי\"ע להיות נס בפו\"מ כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש כי תצא למלחמה על אויביך, אויביך הוא הנה\"ב והיציאה למלחמה הו\"ע בירור הנה\"ב כו', דהנה ידוע שיש ב' אופני בירור והן הבירור דתפלה ובירור דתו' כו', דהבירור דתפלה הוא בדרך מלמטלמ\"ע, דתפלה נגד קרבנות תקנו. וענין הקרבנות הוא שמקריבין בהמה גשמי' ע\"ג המזבח ונכללת באש שלמע' שז\"ע אש אוכלה אש כו', דהנה החי הוא בחי' אש וכידוע דד' מדרי' דצח\"מ הן כנגד ד' בחי' ארמ\"ע והחי הוא בחי' אש כו', וכשנכלל החי באש שלמע' הו\"ע אש אוכלה אש כו'. וכמו\"כ הנה\"ב הוא בחי' אש והו\"ע חמימות התאוה ורתיחת הדמים בענינים הגשמי' כו', וע\"י שמתבונן בהתבוננו' אלקי ומתעורר באה' ברשפי אש כו' כ\"ז שורף ומכלה את האש דנה\"ב כו' וכמ\"ש במ\"א, אך כ\"ז הוא בדרך מלחמה להיות שבנה\"א מה שבא לברר את הנה\"ב ה\"ז מדרי' התחתונות דנה\"א, שהן בבחי' שייכות אל הנה\"ב כו', ואופן הבירור הוא בבחי' התלבשו' שמתלבש ונתפס בהנה\"ב לבררו כו' כנודע וע\"כ הוא בדרך מלחמה כו'. ועז\"א כי תצא למלחמה על אויבך כו', ואח\"כ או' ונתנו ה\"א בידיך שזהו הבירור\nדתו' שהוא בדרך מלמעלמ\"ט כו', וענין הוי' אלקיך הו\"ע תומ\"צ דהוי' הו\"ע התו' דאורייתא מחכ' נפקת והוי' בחכ' כו', ואלקיך הו\"ע המצות דרמ\"ח פקודין הן רמ\"ח אברי' דז\"א כו', ועז\"א ונתנו ה' אלקיך כו', שהבירור הוא בדרך מלמעלמ\"ט כו' (שגם הבירור דמצות הוא בדרך מלמעלמ\"ט וכמשנת\"ל ד\"ה שופטים), להיות שזהו ע\"י התגלו' הנה\"א כו'. הגם שזהו ג\"כ במדרי' נר\"ן כו', מ\"מ ה\"ז במדרי' גבוהות שהכחות דנה\"א הן בהתגלות כו', וגם שזהו ע\"י התו' כו', ע\"כ הוא בדרך מלמעלמ\"ט כו'. ועז\"א ושבית שביו שביו של אויב כו', דע\"י ב' הבירורים דתפלה ותו' הוא רק שלוקחים שביו של אויב"],[3601330556,"היינו מה שבא בדרך שבי' בהנה\"ב מהכחות דנה\"א כו'. דהנה ידוע דהחיות דישראל הוא מנה\"א דוקא, וכאשר משתמש בכחותיו בענינים הגשמי' ובדבר תאוה עי\"ז נשבאים הכחות דנה\"א בנה\"ב כו', דכשם שהוא בהטוב דכאשר משתמש בכחותיו בקדושה ברצון ובחשק ה\"ז עילוי דנה\"א, ולהיות שיש בזה השתתפות הכחות הטבעים הרי גם הכחות דנה\"ב נכללי' בנה\"א ומתעלים בקדושה כו', כמו\"כ הוא להיפך שע\"י העסק בהענינים החומרים גם הכחות דנה\"א הן בבחי' שבי' בזה כו', וז\"ע שביו של אויב כו'. וע\"י התו' ותפלה לוקחין שביו של אויב כו' שמבררים הכחות דקדושה כו', אבל הנה\"ב עצמו אינו מתהפך בזה לקדושה כו'. ואח\"כ או' וראית בשבי' אשת יפ\"ת שזהו כדאי' בת\"ז דמאן דקטל לחויא יהבין לי' ברתא דמלכא כו', פי' דקטיל לחויא היינו שהנה\"ב נהפך לטוב שזהו ביטול דמל' דנוגה לגמרי כו', שעי\"ז נעשה רוממות המל' דקדושה שהיא הנה\"א כו'. דעיקר זה יהי' לעתיד שז\"ע ועת\"י יתיב מלכותי' מלכות עלם כו', וכמו\"כ גם עכשיו בנשמות הגבוהות דקטלי לחויא כו'. וזהו כי תצא למלחמה על אויבך דהיינו בתפלה\nדשעת צלותא שעת קרבא כו', ונתנו ה' אלקיך בידיך ע\"י הבירור דתומ\"צ שהוא מלמעלמ\"ט כו', ובכ\"ז ושבית שביו רק שביו של אויב שהוא הרחבת מקום הקדושה לבד כו', ואח\"כ וראית בשבי' אשת יפת תואר היינו מאן דקטיל לחויא בבחי' אתהפכא חשול\"נ, עי\"ז יהבין לי' ברתא דמלכא דהו\"ע מלכותי' מלכות עלם כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וכמו\"כ לבטל מל' דק\"נ הוא ע\"י המשכה מעצמות למעלה גם מההמשכה דיצי\"מ, דמשה המשיך פנימיות אריך, ולכן ע\"י נתגלה רק חיצוניות החורה, ובהעלם גם הפנימיות, והו\"ע תו\"א, ומשיח יגלה פנימיות התורה ג\"ר דעתיק, ויהי' בבחי' ראי' בכאו\"א, וזהו אודה שמך גילוי הפנימיות במל', ונא' אודה דבעצמות הוא בחי' הודאה, גם י\"ל שנמשך בבחי' מקיף להיות ביטול ק\"נ, ואח\"כ יהי' בבחי' פנימיות. וזהו כי תצא למלחמה הבירור מלמטלמ\"ע, ונתנו ה\"א בידיך הבירור מלמעלמ\"ט, ומאן דקטיל לחיויא מל' דק\"נ יהבין לי' ברתא דמלכא ממ\"ע.</span>"],[3601330557,"<h3>בס\"ד. ש\"פ תבוא, תער\"ג</h3>\n<b>את</b> ה' האמרת היום להיות לך לאלקים כו', ולשמור חוקיו ומצותיו כו', וה' האמירך היום להיות לו לעם סגולה ולשמור כל מצותיו כו', הנה האמרת והאמירך הן ל' שבח והוא שבח נש\"י להקב\"ה ושבח הקב\"ה לנש\"י כו'. והקשה באוה\"ח מהו אומרו לשמור כל מצותיו בשבח הקב\"ה לישראל כו', דהנה בשבח ישראל להקב\"ה ניחא או' ולשמור חוקיו ומצותיו דהיינו שמקבלים עליהם עומ\"ש ותומ\"צ כו', אבל בשבח הקב\"ה לישראל מהו\"ע ולשמור כו'. והנה רז\"ל בגמ' דברכות אמרו אתם עשיתוני חטיבה אחת בעולם אף אני אעשה אתכם חטיבה א' בעולם, אתם עשיתוני חטיבה כו' שמע ישראל כו' ה' אחד, אף אני אעשה חטיבה"],[3601330558,"כו' ומי כעמך כישראל גוי אחד כו', וצ\"ל שייכות הענינים דה' אחד וגוי אחד זל\"ז כו'. ולהבין זה ילה\"ק משנת\"ל במ\"ש ה' אלקי אתה ארוממך דג' תי' ה' אלקי אתה כולל כל ההשתל' דע\"ס דאצי', ה' הוא חכ' דהוי' בחכ' אלקי בינה אתה חסד ומל', ופי' ארוממך לרומם כללו' ההשתל' בבחי' רוממות הכתר ע\"י המס\"נ דק\"ש למסור נפשו באחד ואה' דבכל מאדך כו', ועי\"ז נמשך גילוי אור חדש מבחי' רוממות הכתר בכדי לבטל בחי' מל' דנוגה שעז\"א ושמת מעיר לגל כו', דבכדי שתהי' ההמשכה זהו ע\"י העלאה בתחלה שמרומם בחי' ההשתל' ברוממות הכתר עי\"ז נמשך גילוי האור חדש כו', וזהו אודה שמך שהוא בחי' המשכת האור בבחי' שמך בחי' המל' בכדי שיהי' הגילוי בבי\"ע להיות הנס בפו\"מ בבחי' ביטול הנוגה כו'.\nקפז) <b>ואחר</b> זה או' כי עשית פלא עצות מרחוק כו', ופי' בזהר כסוייא ולבושא לאתלבשא נהורא סתימא עמיקא וטמירא בכסוייא דנהורא אחרא כו', והיינו דפלא הוא בחי' כיסוי ולבוש לנהורא סתימא כו', וזהו כמ\"ש בזהר בלק דר\"ד ע\"ב גבי נהורא קדמאה כו' דלא הוה יכלין עלמא למסבלי' מה עביד קוב\"ה עבד נהורא לנהורי' לאתלבשא דא בדא כו'. והענין הוא כמ\"ש הפרד\"ס שער ס' האצי' פ\"ד בענין השתל' הספי' מהכתר אל החכ' ומחכ' לבינה כו', שכ\"ז הוא בכדי שיתגלם האור בכדי שיהי' בבחי' מציאו' כו', דהאורות כמו שהן ה\"ה בבחי' פשיטו' ואין העולמות יכולים לקבל אור כזה כו', וע\"י ס' ההשתל' מהכתר אל החכ' ומחכ' לבינה כו' מתגלם האור שנעשה בבחי' מציאו' אור שביכולת העולמו' לקבלו כו'. ובשער טעם האצי' פ\"ו כ' שבסדר האצי' מתרחק האור משרשו ומקורו ועי\"ז הוא שנעשה מדרי' פרטי' כו', וכן כל מדרי' מתחלקת לפרטים כו', דהאור כמו שהוא כלול במקורו אינו ניכר המדרי' פרטי' שבו (וכמשנת\"ל פי\"ט ופכ\"א בענין ע\"ס הגנוזות) וכל מדרי' הוא בבחי' כללית כו', וע\"י שנתרחק\nהאור ממקורו (דגם התגלו' הראשונה היא ריחוק ממקורו, והיינו מפני שכל התגלות הוא ע\"י הצמצום דקודם הצמצום הי' הכל כלול בעצמותו ית', וע\"י הצמצום הוא היציאה והתגלות חוץ לעצמותו כבי', וזהו דגילוי הקו בראשית המשכתו היא בבחי' ריחוק ממקורו (הגם שנוגע ודבוק במקורו ה\"ז ע\"י הפסק הצמצום כו'). ולבד זאת הנה כל התגלות אפי' בחי' גילוי מההעלם ה\"ז בחי' ריחוק ממקורו, וכמו בענין אצי' דהתגלות האור מאוא\"ס המאציל ה\"ז בחי' ירידה, וכמ\"ש בתו\"א ד\"ה פתח אלי' בענין וירדתי ואצלתי מהרוח אשר עליך אוריד ואמשיך בחי' שלך למטה ממדריגתך, הרי דאצי' רוחו של משה הוא בחי' ירידה בהאור לגבי שהי' כלול ברוחו של משה כו', דכמו\"כ הוא בענין האצי' דהאור כמו שכלול במקורו באוא\"ס המאציל הוא במעלה עליונה יותר וההתגלות הוא בחי' ירידה בהאור, והוא דבעצם מעלתו אינו כמו במקורו, וגם שנעשה בבחי' מציאות אור כו' (ועמשנת\"ל פכ\"ט). והנה בע\"ח שער הנקודים פ\"ב דהצמצום הוא בשביל האצי', והיינו דאור האצי' הוא שבא ע\"י הצמצום כו', וכ\"ה בתו\"א ד\"ה הנ\"ל, ומ\"מ\nבמדרי' פרטיות הרי אצי' הוא בחי' גילוי ההעלם, וכן הקו בכלל הוא בבחי' גילוי ההעלם ממקורו, וכמשנת\"ל פי\"ח דבשרשי האורות הצמצום הוא בבחי' מיעוט לבד כו' וההתגלות היא בחי' ירידה לגבי מקורו כו', וכל מה שיורד ונמשך ה\"ה מתרחק יותר ממקורו ועמ\"ש בסי' בד\"ה להבין ענין כד אנת תסתלק) עי\"ז ניכר כל מדרי' פרטי' שבאור וכל מדרי' בא בבחי' התחלקו' כו'. וה\"ז"],[3601330559,"כמ\"ש בע\"ח שע\"י הקו נעשה מעומ\"ט כו', דלהיות שבקצהו העליון נוגע ודבוק באוא\"ס ובקצהו התחתון אינו נוגע ודבוק כו', לכן כל מה שמתרחק ממקורו ה\"ז בבחי' מטה לגבי המעלה כו' ועי\"ז נעשה ההתחלקות למדרי' פרטי' כו' (ועמש\"ל פל\"א דהקו הוא בבחי' נקודות פרטי' כו'), וע\"כ כל מדרי' כשמלבשת המדרי' העליונה ממנה ה\"ז נעשה לבוש והעלם לאור העליון כו', ואין הכוונה בבחי' לבוש המעלים ח\"ו, כ\"א מה שבא האור באופן אחר מכמו שהוא במדרי' העליונה כו'. דז\"ע ההתלבשו' דכאשר המדרי' העליונה מתלבשת בהמדרי' התחתונה ה\"ה נעשית כמהות המדרי' התחתונה כו', וכמ\"ש בע\"ח בענין מעבר והתלבשו' כו'. והגם דבהתלבשו' הוא שהמדרי' המתלבשת באה בהתגלו' בהמדרי' התחתונה כו', הנה אדרבה דוקא ע\"י שבאה בהתגלו' בההתלבשו' עי\"ז דוקא היא נעשית כמהות המדרי' התחתונה כו'. וגם זאת הוא בהתלבשו' שהמדרי' תחתונה מתעלה במדרי' ע\"י שמתלבש בה המדרי' העליונה כו', ומ\"מ המדרי' העליונה היא כמהות המדרי' התחתונה כו' וכמ\"ש במ\"א. דכמו\"כ הוא גם בענין השתל' הכתרים זמ\"ז דע\"ה דשם אינו\nשייך בחי' התלבשו' (אדרבה שם הוא בבחי' התכללו' שהעליון מעולה כו', והעיגול תחתון כלול בהעליון שהוא מה שנכלל ובטל להעליון כו'), מ\"מ ע\"י שמתרחק ממקורו מתמעט האור, וז\"ע הכתרים הפרטים כמו כתר דאצי' וכתר דברי' כו' (ובאצי' גופא כתר דז\"א וכתר דנוק') דע\"ה שכ\"ז הוא בחי' כתר (היינו שאין בזה התחלקו' בעצם המהות כמו המעומ\"ט דבחי' או\"פ שהוא שמחולקים בעצם מהותן כו', משא\"כ בהאו\"מ דהמעומ\"ט הוא בבחי' מיעוט לבד כו' וכמשנת\"ל פרק פ'), מ\"מ הם במדרי' פרטי' כו', וכמשנת\"ל מפס\"ד עד פע\"ח בענין המקיפים פרטי' דאבי\"ע כו'. ועד\"ז יובן כאן מ\"ש בזהר כסוייא ולבושא לאתלבשא כו' שזהו בכדי שיהי' אפ\"ל הגילוי כו' (וכאן הוא בבחי' או\"פ רק שזהו בבחי' עצמו' האור כו', וע\"כ סדר ההתלבשו' בזה אינו בבחי' התלבשו' ממש (וקרוב יותר לענין השתל' הכתרים כו'), כ\"א הוא מה שהעצם נעתק ונמשך ממדרי' למדרי' כו' (וזה למע' במדרי' גם מכענין השתל' הכתרים כו'), וכמו בחי' האין העצמי דכתר כשנמצא בין הנאצלי' הוא בבחי' אצי' (והיינו בחי' הפנימי' והעצמי' דאצי' כו'), וכמ\"ש מזה בדרוש יו\"ט של ר\"ה רס\"ו, וכמשי\"ת).\n<span data-k=\"ks\"><b>קיצור.</b> ואו' כי עשית פלא, ופי' בזהר כסויא ולבושא לאתלבשה נהורא סתימא כו', דפלא הוא בחי' לבוש לנהורא סתימא, דהנה השתל' הספי' הוא בכדי שיהי' האור בבחי' מציאות, דכמו שכלול במקורו הוא לא במציאות ובבחי' אחדות, ובהתגלות יורד ממדריגתו ובפרט שההתגלות היא ע\"י הצמצום, נעשה בבחי' מציאות ובהתחלקות מדרי', וכל מדרי' היא לבוש למדרי' העליונה, דהתלבשות הוא בחי' התגלות פנימי בהמדרי' שלמטה ועי\"ז נעשה כמהותה, דכן הוא גם בהשתל' הכתרים זמ\"ז, וכמו\"כ הוא בהמשכת האור דעצמות אוא\"ס (רק שבזה ההמשכה היא העצם שנעתק ונמשך).</span>\nקפח) <b>והענין</b> הוא דמ\"ש כי עשית פלא הוא שמפרש סדר המשכת האור חדש מאוא\"ס ב\"ה שנמשך ע\"י או\"א וזו\"נ, שבכדי שיוכלו זו\"נ לסבול האור צ\"ל מתלבש תחלה בחכ' ואח\"כ בבינה, וע\"ז מתחיל לפרש כי עשית פלא"],[3601330560,"עצות מרחוק אמונה אומן, ופי' כי עשית פלא, דהנה ידוע דחכ' נק' אלף מל' אאלפך חכ' שהו\"ע אולפנא ולימוד כו', ובגמ' שבת דק\"ד ע\"א אי' אלף בית אלף בינה והיינו שהחכ' נק' אלף ע\"ש שמלמדת את הבינה, והענין הוא עד\"מ הרב המלמד את תלמידו הרי מגלה לו שכל וסברא עמוקה וחדשה שלא הי' ביכולתו להשיגה הרי שהרב מגלה לו התחדשו' ממש כו', דזהו עיקר ענין ההשפעה מה שהרב מגלה לו ענינים חדשים שמעצמו לא הי' בא עליהם כלל כו', וגם מעמידו על בורי' שלא יכשל בה בטעות לעולם כו'. וכך בחי' החכ' מלמדת את הבינה, שהרי כל השגה דבינה הוא מנקודת החכ' הרי הבינה מקבלת מאור החכ' כו' (ועמ\"ש מזה בד\"ה תקעו עת\"ר), וא\"כ לכאו' בינה היא כמו בחי' כלי המקבל והאור הוא מבחי' החכ' וז\"ע הלימוד כו', וכמו עד\"מ ברב ותלמיד הרי אינו מתהווה מהות השכל של התלמיד מן הרב שכבר יש שכל להתלמיד ומשו\"ז יכול להיות תלמיד ומקבל מהרב כו', ומ\"מ הרי לא נתפתח שכלו עדיין (שכ\"ה בכל תלמיד לפ\"ע הרב כו'), וגם אינו יודע עדיין השגת הענין כו', והרב הוא שמלמדו שמפתח כלי שכלו\nוהשגתו שיהי' כלי לקבל כו', והוא התפתחות כלי ההשגה אל הענין השכלי שיהי' לו השגה בכלל בהשכלי הזה (ובד\"כ הוא רק שיהי' לו שייכות אל זה השכלי), שזהו ג\"כ ע\"י ההשפעה שמשפיע לו ענינים שהן כעין הקדמה שבזה מתפתח שכלו והשגתו בענין השכלי הזה כו' ומגלה לו ומלמדו הענין שכלי ואיך להשיגו כו'. ועד\"ז הוא בבחי' חו\"ב, דע\"ה דבינה הו\"ע השגה מ\"מ גילוי ההשגה וענין המושג שזהו בחי' האור הוא מבחי' החכ' כו', והיינו דבינה הוא כמו כח היולי והיא העילולית להשיג כו', וגילוי ההשגה דבינה והאור המושג הוא מבחי' החכ' כו', והיינו דמ\"ש בע\"ח דאוא\"ס מאיר בכתר וחכ' בקירוב מקום ובבינה בריחוק מקום כו', ומבו' במ\"א שכ\"ז הוא בהמשכת האור הא\"ס כמו שבא ונמשך ממדרי' למדרי' כו', ובבינה הוא בריחוק מקום דהיינו להיותו בבחי' השגה כו', ה\"ז בא לבינה ע\"י בחי' החכ' כו'. אמנם ממ\"ש כאן נר' דמה שהחכ' מלמדת את הבינה הוא שפועל התחדשות דבר בבינה כו', וכמו במשל דמשפיע ומקבל הרי המשפיע מגלה לו ענינים חדשים שהמקבל לא הי' בא עליהם מעצמו, כמו\"כ צ\"ל בדוגמא\nכזאת בחו\"ב דהחכ' עושה התחדשו' בבחי' בינה מה שאין בה מצ\"ע כו' (הגם דלמע' א\"ז כמו למטה במשפיע ומקבל שהמקבל יש בו ג\"כ ב' הכחות דחו\"ב כו', וא\"כ מה שהמשפיע מחדש לו היא התחדשות הענינים בהשכל מה שבכח חו\"ב שלו לא הי' בא ע\"ז כו', אבל למע' הרי בינה הו\"ע ההשגה, ולהיות גילוי ההשגה והאור המושג הוא ע\"י החכ' כו', וזהו ההתחדשות כו' (וכמו שאא\"ל נהר בלא מעין כו' וכמ\"ש במ\"א דדוקא בכחות הנעלמים הכחות דחו\"ב אינם תלוים זב\"ז כו'). מ\"מ צ\"ל דהכוונה היא בענין הלימוד שהחכ' עושה התחדשות בבחי' בינה מה שאין בה מצ\"ע כו', וצ\"ל דבהעלם יש בבינה הכח ע\"ז (וכמו בהמקבל שזהו דוקא כשהוא עלול אל ההתחדשות כו'), והיינו משום דבשרשם הרי הבינה היא כמו החכ' כו' וכמ\"ש במ\"א), וצ\"ל מהו ההתחדשות. וילה\"ק מה דאי' בירושלמי סנהדרין פ' חלק ע\"פ דברי חכמים כדרבונות ג' שמות יש לו מרדע דרבן ומלמד כו', מרדע שמורה דעה בפרה, דרבון שהוא משרה בינה בפרה, מלמד שהוא מלמד את הפרה לחרוש בשביל ליתן חיים לבעלי' כו', אם לפרתו עושה אדם דרבן ליצרו הרע כו' עאכו\"כ, וקאי על התורה שמורה דעה ומשרה בינה ומלמד כו', וי\"ל שהן נגד ג' בחי' חב\"ד כו',"],[3601330561,"ומלמד הוא בחי' החכ' וכמ\"ש והחכ' תחי' כו'. ולהבין ג' מדרי' אלו בנפש, הענין הוא דהנה ידוע דשרש נה\"ב הוא מפני שור שבמרכבה, ושרש הנה\"א הוא מבחינת אדם שעל הכסא ושרשו הוא מבחי' החכ' וכמ\"ש בסש\"ב דשרש כל הנשמו' הן מבחי' החכ' כו', ואפי' נשמו' דבי\"ע שנק' בשם זרע בהמה ג\"כ יש בהם מבחי' חכ' דאצי' שבה שורה אוא\"ס ב\"ה וכמ\"ש בסש\"ב פי\"ח, ובכאו\"א מישראל יש בהם הביטול דבחי' חכ' שהוא להתבטל במציאו' ממש באוא\"ס ב\"ה, וזהו בטבע בנשמה דשם טבע הוא שם המושאל על כל דבר שלמע' מטו\"ד כו', רק שהיא מוסתרת בנה\"ב ועש\"ז נק' אה' מוסתרת כו' כמש\"ש פי\"ט. ובכדי להוציא אה' זו מההעלם אל הגילוי, וכ\"ש בכדי לפעול הביטול דבחי' ביטול היש בנה\"ב כו', זהו ע\"י התו' שנק' עוז ותושי' שפועלת בנה\"א ובנה\"ב כו', היינו שפועל התגלו' הנה\"א להיות התגלו' האהבה מוסתרת הנ\"ל, ופועל החלישות בנה\"ב להיות בו ביטול היש כו', וזהו בד\"כ בחי' הלימוד דתו' מה שפועל בנפש האדם.\n<span data-k=\"ks\"><b>קיצור.</b> פלא אותיות אלף, א' ב' אלף בינה, וכמו עד\"מ הרב שמחדש בשכל התלמיד, כמו\"כ בחו\"ב לבד מה שבינה מקבלת מאור החכ', דאוא\"ס בבינה הוא ע\"י חכמה, וכמו שא\"א להיות נהר בלא מעין, הנה החכ' מחדשת דבר בבינה, ויקדים ענין מלמד דרבן מרדע חב\"ד, והוא בנפש שהתורה מתשת כח הנה\"ב, ונותנת עוז לנה\"א להיות התגלות האהמ\"ס ולפעול הביטול בנה\"ב.</span>\nקפט) <b>אמנם</b> בד\"פ יש בתו' ב' מדרי' תושב\"כ ותושבע\"פ, דתושב\"כ הוא בחי' חכ' ברורה והיינו שבאה מלמע' בבחי' גילוי אור כו' וה\"ז לימוד לנה\"א כו', ותושבע\"פ הוא לימוד לנה\"ב כו'. דהנה בתושבע\"פ הרי אור החכ' אינו מאיר בגילוי ממש רק שע\"י ריבוי העלמות והסתרים שהם הסתירות והקושיות ועי\"ז בא התגלו' אמיתי' אור החכ' כו', משא\"כ בתושב\"כ אור החכ' היא בגילוי שלא בא בהעלמות והסתרים כלל כו'. והענין הוא דהנה התו' בכלל היא בחי' ש' מ\"ה דאורייתא מחכ' נפקת דחכ' הוא בחי' מ\"ה כו', רק דתושבע\"פ הוא בחי' הארה משם מ\"ה שירד ונתלבש בבחי' עה\"ד טו\"ר לברר בירורים כו', ותושב\"כ הוא בחי' ש' מ\"ה בעצם שלא בא בבחי' התלבשו' כו', וזהו דתושב\"כ נק' עה\"ח ותושבע\"פ נק' עה\"ד, ומבו' באגה\"ק סי' כ\"ו דבאמת גם תושבע\"פ הוא בחי' עה\"ח רק שנתלבשה בעה\"ד כו' (ומבו' שם דתושב\"כ הוא בחי' ז\"א שלא בא בהתלבשו' ותושבע\"פ בחי' מל' המתלבשת בק\"נ לברר כו'), וידוע דש' מ\"ה הוא בחי' ביטול בעצם היינו ביטול אמיתי שמצד עצמו' אוא\"ס ב\"ה כו', וז\"ע חכמה כח מ\"ה\nלהיות שבחכ' שורה אוא\"ס אחד האמת שהוא לבדו הוא ואין זולתו, וע\"כ החכ' היא בבחי' ביטול במציאו' ממש כו'. והענין הוא דהנה ידוע בענין אל דעות הוי' שהן ב' דעות ד\"ע וד\"ת, דהדעה העליונה היא איך שכולא קמי' כל\"ח והיא הדיעה דאוא\"ס ב\"ה דהכל בבחי' אין ואפס קמי' כו', אבל בנבראים מצ\"ע אא\"ל בהם דעה זו, שהרי הדעת שלהם הוא ע\"פ השגתם ואא\"ל בהם ההשגה איך שהכל אין ואפס שה\"ה נמצאים בבחי' מציאו' דבר כו', וגם ההשגה גופא היא בבחי' מציאו' דבר דכל השגה היא יש כו' כנודע, ואיך יכול היש לתפוס את האין כו', וע\"כ הנבראים אינם משיגים גם המציאו' דאין ואפס וכ\"ש המהות כו'. וכמו שאין אנו משיגים איך הוא"],[3601330562,"למע' מן המקום והזמן מפני שאנו נתפסים במקום וזמן כו', והגם שנת\"ל פקס\"ח שאפ\"ל קצת השגה בענין מקום מכחות הנפש שכמה כחות נמצאים במקום אחד כו', הנה לבד זאת שזהו ההשגה רק במציאו' דמקום רוחני לא במהות הדבר כו', הנה כ\"ז הוא ענין המקום רק שהוא מקום רוחני כו', אבל בלי מקום לגמרי (כמו באצי' וכ\"ש למע' מאצי' כו') אין אנו יודעים גם המציאות כו', וכמו\"כ אין אנו משיגים בענין אין ואפס מה הוא גם המציאו' כו', דכל מה שאנו מציירים בחי' אין ה\"ז בחי' מציאו' באמת כו'. דהנה מה שאנו יודעים בחי' אין הוא בענין האור להיות דאור הוא בחי' אין כידוע, הנה לבד זאת שאין אנו יודעים מהות האור כלל, ומה שאנו מציירים ענין האור הוא מענינים גשמי' כמו מהאור שאנ\"ר אור היום ואור השמש כו' או מאור השכל וכה\"ג, הרי כ\"ז אור הנתפס בגשם כו', וכאשר מזה אנו יודעים ענין האור האלקי הרי כמה שנשלל מזה ההגשמה והחומרי' (שמצד המשל) כו', הרי מ\"מ ה\"ז בא בהגשמה אצלנו מאחר שאנו תופסים בזה ע\"י ענינים הבאים בהגשמה כו' (וגם ההשגה גופא היא יש כו'), וע\"כ\nא\"א לנו לידע אמיתית ענין האור במהותו כלל כו' (ומ\"מ אפ\"ל קצת ציור במציאו' ענין האור כו', ובאמת זהו רק בדרך השערה לא בדרך השגה כו'). לבד זאת ה\"ז שהאור הוא בבחי' אין אין אנו יודעים כלל גם לא מציאות הענין, שהרי נודע דאמיתית הענין מה שהאור הוא בחי' אין ה\"ז לגבי מקורו כו', שהרי האור בעצם ה\"ה בבחי' מציאו' אור עכ\"פ כו', רק הוא בחי' אין לגבי מקורו, דלהיותו דבוק במקורו נרגש בו הדעה האמית' כמו שהוא באוא\"ס המאציל דכולא קכל\"ח שעי\"ז האור גופא הוא בבחי' כלא כו', אבל א\"ז בהאור מצ\"ע כ\"א מצד מקורו המאציל עליון כו', וענין האין דהאור כמו שהוא מצד המאציל (שז\"ע ביטול האמיתי) אין אנו יודעים כלל אפי' בהשערה כו' (דבענין האור יכול להיות השערה עכ\"פ, וזהו ידיעתינו בבחי' אין להיות שהאור הוא אין כו', אבל באמית' ענין האין דהיינו הביטול בהאור מצד מקורו המאציל שז\"ע ד\"ע כו' אין אנו יודעים כלל כו'), והיינו שהנבראים מצ\"ע אינם משיגים את הדיעה העליונה איך שהכל אין ואפס כו'. וע\"ה שג\"ז יוכל להיות מושג בשכל איך שמצד עצמו'\nאוא\"ס אין העולמו' וההשתל' בבחי' מציאו' כלל שז\"ע ההתבוננות דה' אחד כו', זהו רק ההשגה לבד, אבל שיהי' בדרך הנחה במוחו ובהרגש הענין ומכ\"ש שיהי' הביטול באופן כזה, א\"ז בנבראים מכח עצמן כו'. ומה שמושג בנבראים הוא בחי' ד\"ת שהן בבחי' מציאו' ושכח אלקי מהוה ומחי' אותם כו', והוא בהאור האלקי שבא בבחי' התלבשו' בעולמו' ונבראי' שמהווה את העולמו' ומחי' אותם כו', שבזה יכול להיות השגת הנבראים כו', וההשגה הוא מהנבראי' עצמן שהרי אין דבר עושה א\"ע וכמשנת\"ל פק\"נ ואינו חי מעצמו, ובהכרח שיש בו כח אלקי המהווה ומחי' אותו כו' ומבשרי אחזה כו'. וע\"י ההתבוננו' בזה נעשה הענין בקירוב אליו כו', דלולא ההתבוננו' הגם שיודע איך שאלקו' מהווה את העולמו' ומחי' אותם כו', הרי הידיעה הוא בריחוק אצלו ואינו פועל בו דבר כו', וע\"י ההתבוננות בהעמקת הדעת נעשה הידיעה בקירוב אליו ונרגש בו ופועל בו הביטול כו', ובפרט כאשר מתבונן באופן האור והחיות האלקי שבכל עולם ועולם כו', הרי ניתק עי\"ז מעניני העולם וכל חפצו ורצונו הוא באלקו' כו', וכ\"ז הוא\nבחי' ד\"ת שהביטול בזה הוא בבחי' ביטול היש לבד כו'. אבל בחי' ד\"ע והביטול שבזה א\"ז בנבראי' מצ\"ע כ\"א כאשר נותנים מלמע' ידיעה והשגה זו וביטול זה כו', ומה שנותנים זה מלמע' זהו רק בנה\"א שיש"],[3601330563,"לו שייכות עכ\"פ לידיעה וביטול זה כו', כי א\"א להשיג מה שאינו שייכים לזה כלל, דכל השגת ענין בהכרח שיהי' להמשיג איזה שייכות אל הענין כו', וכמו השגת הנה\"א שהוא רק באלקו' ואין לו שום שייכות להשגת ענין הטבעי' כלל מצ\"ע כו', והנה\"ב להיפך כל השגתו הוא בעניני הטבעי' ואין לו שום שייכות בהשגה אלקית כו', והקישור והחבור דנה\"א עם הנה\"ב שהנה\"א ישיג אלקו' בענינים הטבעים כו', והנה\"ב יהי' לו ג\"כ השגה באלקו' ה\"ז רק בכח הא\"ס המפליא לעשות לקשר רוחני' בגשמי' כו'. וכמו\"כ יובן דהידיעה והביטול דד\"ע יכול להיות רק בנה\"א מפני שיש לו שייכות בכלל לאלקו' ובפרט ששרשו מאלקו' שלמע' מגדר עולמו' כו', וכידוע שהנשמו' הן בבחי' המשכה עצמי' רק שנעשו בבחי' מציאו' בפ\"ע כו', וע\"כ הנה\"א נותנים מלמע' הביטול דד\"ע איך שכולא קכל\"ח כו', וזהו ע\"י תושב\"כ שהיא המשכת בחי' ש' מ\"ה, והיינו ההמשכה מלמע' להיות בחי' הביטול הזה כו', דהרי תושב\"כ הוא שניתנה מלמע' והיא דבר ה' למשה לאמר לכל ישראל כו', דגם אותיות התורה הן אותיות עליונים שניתנו מלמע' והן\nבחי' אותי' דמ\"ה כו'. וכנודע דבש' מ\"ה יש בחי' אור וכלי כי אא\"ל אור בלא כלי, דכל אור הנמשך ומתגלה בהכרח שיהי' לו כלי שבזה הוא נאחז ועי\"ז הוא הגילוי שלו כו', וז\"ע אותי' דמ\"ה שהן המביאים לידי גילוי אור הביטול דש' מ\"ה כו', והן הן אותיו' התו' שהן המביאים וממשיכים גילוי בחי' דיעה העליונה להיות הביטול דמ\"ה בחי' ביטול במציאות כו', וזהו הלימוד דתושב\"כ להמשיך בחי' הביטול דמ\"ה שזהו בד\"פ בנה\"א, דהנה בק\"ש יש ב' בחי' מס\"נ, למסו\"נ באחד ובכל נפשך אפי' נוטל כו', דלמסו\"נ באחד זהו בנה\"א להיות שבהנשמה יש בה מבחי' החכ' וכמשנת\"ל פקפ\"ח דכל הנשמות שרשן מבחי' ח\"ע כו', והביטול דה' אחד בנשמות זהו שנמשך בהם ע\"י התורה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ובד\"פ תושב\"כ היא הלימוד לנה\"א, דתושב\"כ היא ש' מ\"ה שזהו ביטול בעצם, ועי\"ז נמשך בנה\"א הביטול דיחו\"ע, דהנה ד\"ע איך שלמטה לא יש בנבראים מצ\"ע, שזה היפך מהותם, והשגה היא יש, וע\"כ אין משיגים גם מציאות בחי' אין אמיתי (כמו שאינו משיגים אמיתית ענין בלי מקום), ומשיגים מציאות האור (וג\"ז רק מאור הגשמי ומאור השכל בדרך השערה בלבד), ואור הוא אין, אך אמיתית האין בהאור שהוא מצד העצמות אינו מושג גם המציאות, רק השגתם הוא בד\"ת שע\"י ההתבוננות ה\"ז בקירוב אליו, וד\"ע הוא שנותנים מלמעלה ורק לנה\"א שיש לו שייכות עכ\"פ להשגה זו, והוא ע\"י תושב\"כ, דגם האותיות הן אותיות דמ\"ה שניתנו מלמעלה, וזהו הביטול דה' אחד.</span>\nקצ) <b>והנה</b> עיקר הענין דה' אחד הוא בנשמות הגבוהות שלא נסתר ונתעלם בהם האור כו', והיינו שגם בס' ההמשכה שלהם בבי\"ע לא נתעלם בהם אור שרשם ומקורם כמו שהן באצי' כו', וי\"ל דהעיקר הוא בנשמות דאצי' שהן רק בבחי' מעבר דבי\"ע כו', דגם נשמות אלו עם היותם נשמות דאצי' מ\"מ בירידתם למטה צריכים להמשכת אור מלמע' להיות בהם הביטול האמיתי דה' אחד כו', והוא ע\"י התו' כו', ובפרט לפמ\"ש באגה\"ק ד\"ה איהו וחיוהי חד דנשמות דאצי' גם במקורם באצי' יצאו ונפרדו מהכלים די\"ס שבהן מלובש הקו כו', וע\"כ בכדי להיות"],[3601330564,"בהם הביטול דה' אחד שזהו דוקא בהאור להיותו דבוק במקורו כו' צ\"ל ע\"ז המשכה מלמע' כו', ובפרט בירידתן למטה שהגם שלא נשתנו ממהותן להיות דבר נפרד כו' וכמש\"ש (והיינו לא כמו נשמות דבי\"ע שנעשו בבחי' יש נפרד וכמו נבראים דעדאת\"ג כו', עם היותם אלקות בעצם מהותם כו', מ\"מ הרי בפרט זה נשתנו ממקורם במה שנעשו בבחי' יש כו', דכמו שירדו בבי\"ע נק' נבראים דעדאת\"ג, משא\"כ נשמות הרי גם בפרט זה לא נשתנו שלא נעשו בבחי' נפרד כו', דגם כמו שירדו למטה ה\"ה במדרי' עדאתכ\"ס ונק' נוני ימא דאזלין ביבשתא כו' כנודע), מ\"מ ודאי שנתרחקו ממקורם גם ע\"י המעבר דבי\"ע כו', שהרי עכ\"פ המעבר פועל בהם להיות להם שייכות אל עולם התחתון כו', וכמ\"ש באגה\"ק בקו\"א ד\"ה להבין מ\"ש בפע\"ח שהמעבר הוא ג\"כ בחי' התלבשות כו', וע\"כ צריכים ג\"כ המשכה מלמעלה כו'. והנה בסש\"ב פכ\"א מבואר שגם בהכלים דאצי' הביטול הוא בבחי' ביטול דיחו\"ע כו' (וא\"כ כמו\"כ הוא בנשמות דאצי' שהן כעין אלקות דכלים כו'), הנה לבד זאת שהנשמות כבר יצאו ונפרדו מהכלים כו', הנה הביטול דיחו\"ע שבכלים\nהוא בדרך התכללות היינו מה שכלולים במקורם וממילא אינם בבחי' מציאות כו' כמבו' בסש\"ב שם (וגם כאן הכוונה שמצ\"ע אינם בבחי' מציאות כו', אבל זה מצד ההתכללות במקורם כו') ועמשית\"ל פ', וא\"ז כענין הביטול דכולא קמי' כלא כו' שזהו דוקא בהאור להיותו דבוק במקורו ונרגש בו הדיעה האמיתית איך שכולא קכל\"ח כו'. וע\"כ בנשמות גם נשמות דאצי' להיותם מרוחקים מן הקו הרי מצ\"ע לא הי' בהם הביטול הזה כ\"א ע\"י התו' כו' (והיינו משום שבעצם יש להם שייכות לביטול זה להיותם נשמות דאצי' כו'), ואפשר י\"ל דגם בנשמות דברי' ויצי' יכול להיות בחי' הביטול דה' אחד. והענין הוא ע\"פ מ\"ש בלק\"ת ד\"ה להבין ענין מי אל כמוך דבאמת הנה\"א מצ\"ע אפי' היא מדרי' תחתונה מאד ה\"ה נפש אלקי' ובטלה באוא\"ס ב\"ה ממש כנר בפני האבוקה, רק מצד התלבשותה בנה\"ב הנה הנשמה שהיא ממדרי' תחתונה ה\"ה מלובשת מאד ומושרשת בטבע הנה\"ב עד שאינה מתפעלת מדברים דקים ורוחנים ואינה בטלה כ\"כ באוא\"ס שלמע' מהשתל' שאינו מאיר לה אלא בריחוק מקום כו', דלפי שהנשמה היא בבחי' גסות הרוחני'\nומושרשת למטה בטבע נה\"ב ע\"כ אינה מתפעלת כו', והיינו בנשמות שהן מבחי' עקביים שזהו בחי' עשי' בכלל, דלהיותן ממדרי' הנמוכות ונתפסים בגשם למטה אין בהם כ\"כ בחי' הביטול לאוא\"ס שלמע' מהשתל' שזהו הביטול דיחו\"ע כו' (ומ\"מ יש בהם העבודה דיחו\"ת ויש בזה ציור קומה דיש שהן עובדי ה' באהוי\"ר כו', ובד\"כ הוא בבחי' חיצוניות הלב כו'). אבל נשמות שמברי' ויצי' גם בירידתן למטה אינן נתפסים בגשם כ\"כ יכול להיות בהם בחי' הביטול דיחו\"ע ע\"י גילוי אור עליון המאיר עליהם כו', וכמו התנאים ואמוראים שהן מבחי' ברי' ויצי' כנודע והיו בבחי' ביטול בתכלית כו' (ומ\"מ תנאים ואמוראים הן מייסדי תושבע\"פ שזהו בחי' ש' מ\"ה שבא לברר המ\"ן דב\"ן בבחי' בירור שני כו' וכמ\"ש במ\"א, ועמ\"ש בזהר משפטים דק\"י ע\"ב לגבי תושב\"כ איתנים ולגבי תושבע\"פ תנאים כו', ומ\"מ בנשמתן היו בבחי' ביטול במציאות כו'). גם י\"ל עפמ\"ש בלק\"ת ד\"ה כי תצא הב' בשם הרמ\"ז בפ' משפטים שיש ג' מדרי' בנשמות, הא' בחי' נר\"ן דבי\"ע עצמן (והן הנשמות שנק' עבדים שעובדים עבודתם לברר ולזכך הגוף ונה\"ב ע\"י הדעת וההתבוננות באלקות בבחי' חיצוני' הלב כו', ונשמות אלו נק' זרע בהמה שאין להם"],[3601330565,"דעת והיינו שאין להם בחי' ד\"ע כ\"א ד\"ת כו' וכמ\"ש במ\"א), והב' נר\"ן מבחי' אצי' שבפנימי' בי\"ע (וי\"ל שהן נשמות הנק' בנים המבו' בהבי' הב' דיונתי בהג\"ה, ובחי' אצי' שבפנימי' בי\"ע זהו בחי' אור הנשמה דבי\"ע, וידוע מ\"ש באגה\"ק דהלכות הן בחי' אור הנשמה דברי' ויצי' כו', וע\"כ י\"ל דנשמות אלו הן שייכים לתושבע\"פ והן נשמות תנאים ואמוראים מייסדי תושבע\"פ כו', והן בחי' הביטול דש' מ\"ה להיות שזהו בחי' אצי' כו'), והג' מסוד אצי' בעצמו כו' (והן הנולדים מיחוד או\"א ונק' אחים ורעים לז\"א כו'). ומבו' במ\"א שיש הפרש גדול בין אצי' כמו שהוא נמשך ומלובש בבי\"ע לכמו שהוא באצי' ממש, וכפה\"נ שם הוא דמה שנשמה דאצי' לא תוכל לסבול כל דבר רע כו' זהו דוקא בנשמות דאצי' ממש והן המסתלקות בעת החטא, אבל הנשמות דאצי' שבבי\"ע אינן מסתלקו' הגם שגם אינן נתפסים ח\"ו בזה כמו נשמות דבי\"ע עצמן שעז\"נ ונפש כי תחטא כו', והעיקר הוא בנפש דעשי', אך כמו\"כ בד\"כ בנשמות דבי\"ע שנתפסים כו', משא\"כ בנשמות דאצי' שבבי\"ע שאינם נתפסים כו', מ\"מ אינם מסתלקים כמו נשמות\nדאצי' ממש כו'. ולפ\"ז כמו\"כ יובן בענין הבירורים דנשמות דאצי' ממש הוא שהבירור הוא בדרך ממילא בלי שום התלבשות כלל וכמו שלמה שהי' איש מנוחה כו', וכמו במשיח דכתי' ונהרו אליו כל הגוים שיתבטלו בדרך ממילא כו', ומבחי' אצי' שבבי\"ע הגם שזהו ג\"כ בדרך מלמעלמ\"ט מ\"מ הוא בבחינת התלבשות כו', וכמו ההלכות שהן בבחי' התלבשות והתעסקות בהענינים הגשמיים כו', וזהו דתנאים ואמוראים שהיו מבחי' אצי' שבבי\"ע היו המה מייסדי תושבע\"פ להיות הבירור בדרך התעסקות בהענינים הגשמי' כו', ולהיותם מבחי' אצי' דלכן הבירור הוא בדרך מלמעלמ\"ט כו', הי' בהם הביטול בבחי' ביטול במציאות כו'. וזהו הלימוד דתושב\"כ שהוא הלימוד לנה\"א לבא לבחי' הביטול דיחו\"ע, דהעיקר הוא בנשמות דאצי' גם בנשמות שמבחי' אצי' שבבי\"ע כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ועיקר הביטול דיחו\"ע הוא בנשמות דאצי' ולהיותם בדרך מעביר בי\"ע וגם בשרשם יצאו ונפרדו מהכלים, ע\"כ הביטול הוא ע\"י התורה, והכלים גם בבחי' יחו\"ע אך הוא בדרך התכללות, וי\"ל דרק נשמות נמוכות דעשי' שנשרשים בנה\"ב אין בהם הביטול דיחו\"ע, אבל דברי' ויצי' שאינן נתפסים כ\"כ בגשם יש בהם הביטול דיחו\"ע, וכמו תו\"א שהיו בבחי' ביטול בתכלית, וי\"ל ע\"פ מ\"ש הרמ\"ז שיש בנשמות ג' מדרי', דאצי' ממש הנק' אחים, ואצי' שבבי\"ע בנים, ובי\"ע עבדים (וי\"ל דמדרי' מסתלק בעת החטא ודאצי' שבבי\"ע אינו מסתלק ואינו נתפס), ותו\"א י\"ל שהן מאצי' שבבי\"ע, ולכן הן מייסדי תושבע\"פ בירור שני דש' מ\"ה, והבירור הוא בדרך התעסקות לא בבחי' תפיסא, וע\"כ יש בהם ג\"כ הביטול דיחו\"ע ע\"י התורה.</span>\nקצא) <b>אמנם</b> ע\"י תושבע\"פ הלימוד הוא גם לנה\"ב היינו לפעול את הביטול גם בנה\"ב, וכמא' אם פגע בך מנוול זה משכהו לבהמ\"ד גם אם אבן הוא נימוח, והיינו שגם שיהי' לבו כלב האבן המס ימס ע\"י המים דתו' כו', כי תושבע\"פ הוא בחי' הארת ש' מ\"ה כמו שבא בהתלבשות לברר כו', ולכן האותי' דתושבע\"פ אינם אותי' שלמע' שהרי יש בהם אותי' גם מל' הארמי כו' כנודע והיינו מה"],[3601330566,"שנתברר כו', והן אותי' דלבנה כו'. וכידוע שיש אבן ולבנה, דאבן הוא בידי שמים והיינו אותי' דמ\"ה שניתנו מלמע' כו', ולבנה הן אותי' שנתבררו שהו\"ע ש' ב\"ן כו' וכמ\"ש בתו\"א ד\"ה ויראו כו' ותחת רגליו כו', והנה עיקר לבנה שזה מה שנתברר הוא בתפלה שהן אותי' שמתבררים מהנה\"ב כו', וכמ\"ש במ\"א שהתפלה הוא דבור האדם ממש. וזהו מט\"ט קושר כתרים כו', דהכתר נעשה מאב\"ט שהן אותי' התפלה שטובים ומאירים ע\"י הזיכוך כו' (והעיקר הוא ג\"כ בבחי' מס\"נ בתפלה ובד\"כ דבור היוצא מקירות פנימי' לבו כו'), אבל הדבור דתו' הרי באמת הוא דבר ה' דכל ההלכות הן דבר ה' ממש שנתגלה ע\"י התנאים ואמוראים כו', וכמ\"ש ואשים דברי בפיך כו' (ומ\"מ ה\"ז בא בדבור התו\"א ואינו דומה להדבור דתושב\"כ שהן מפי הגבורה כו', ועמ\"ש בהבי' הב' דיונתי ספ\"ג בענין משה מפי עצמו כו'), רק שזהו שבא בהתלבשות לברר, ע\"כ יש בזה ג\"כ אותי' שנתבררו כו', וכענין לבנת הספיר כו' וכמ\"ש במ\"א. וי\"ל דב' בחי' לימוד הנ\"ל דתושב\"כ ותושבע\"פ, דתושב\"כ הוא הלימוד לנה\"א ותושבע\"פ לימוד לנה\"ב כו', ז\"ע ב'\nהבחי' דמלמד ודרבון, דמלמד הוא שמלמד את הפרה כו' בשביל ליתן חיים לבעלי' זהו הלימוד לנה\"א להמשיך בה מבחי' החכ' וכמ\"ש והחכ' תחי' כו', והיינו להיות בנה\"א גילוי בחי' דעה העליונה להיות הביטול בבחי' כל\"ח כו', ודרבון הוא שדר בינה בפרה הוא הלימוד דתושבע\"פ לפעול הביטול בנה\"ב, דתושבע\"פ הוא בינה וכנודע דתושב\"כ ותושבע\"פ הן חו\"ב כו', ומרדע שמורה דעה בפרה י\"ל שזהו ג\"כ הלימוד לנה\"א, רק שזהו בנשמות דבי\"ע שנק' זרע בהמה דבהמה אין לה דעת, וידוע הענין שזהו שאין להם בחי' ד\"ע רק בחי' ד\"ת כו' כמ\"ש במ\"א, וגבי משה כתי' ונתתי עשב בשדך לבהמתך שהמשיך בחי' הדעת גם בנשמות דזרע בהמה כמ\"ש בתו\"א ד\"ה ואלה המשפטים, וזהו ג\"כ ענין שמורה דעה בפרה, שגם בנשמות דבי\"ע יהי' בהם הביטול דד\"ע כו'. ועפ\"ז יובן ג\"כ ענין אלף בינה שהחכ' מלמדת הבינה ומחדש בה דבר חדוש שאין בה מצ\"ע כו'. והענין הוא לפי המבו' לעיל דהנבראים מצ\"ע אין בהם הדעה הזאת איך שכל\"ח גם בנשמות דאצי' להיות כי דעת הנמצאים הוא הכל במה שמושג, ובהשגה אא\"ל איך שהכל אינו בבחי'\nמציאות כו', וע\"כ זהו רק מה שנותנים מלמע' כו', והוא הלימוד דתושב\"כ שמלמד לנה\"א כו'. וכמו\"כ יובן בבחי' בינה למע' דהעיקר הוא בחי' השגה ותהי' ההשגה באיזה אופן שתהי' הרי ענינה הוא ענין ההשגה כו', וע\"כ אין בה מצ\"ע הידיעה הזאת איך שכולא קמי' כלא כו', רק שזהו מה שנמשך מבחי' החכ' שהיא באמת למע' מהשגה ושם נודע הדעה העליונה איך שהוא לבדו הוא כו', והיינו כמ\"ש בד\"ה מזמור לתודה דבינה הוא בחי' ד\"ת כו', ונת\"ל פמ\"ב דבחכ' העיקר הוא ההנחה ומה שבינה מקבלת היא בחי' השכלי לבד, אבל ההנחה היא בבחי' העלם מהבינה כו', וע\"כ זהו\"ע הלימוד שהחכ' מלמדת את הבינה להיות בה ג\"כ בחי' הדעה העליונה שזהו התחדשות ממש כו'. וכמ\"ש במ\"א בענין כלה עילאה שגם בבינה הביטול הוא בבחי' ביטול במציאות ממש כו', ועמ\"ש בלק\"ת ד\"ה שה\"ש בענין ב' בחי' כלה כו', וזהו מה שנמשך בבינה מבחי' חכ' כו'. וענין שמעמידו על בורי' שלא יפול בטעות הוא כי בתושב\"כ הרי כל הענינים המה בקיצור נמרץ ובתושבע\"פ באים הענינים בפרטיות באריכות גדולה בריבוי סברות ובפלפול עצום\nכו', שזהו בחי' בינה כו', וצ\"ל בזה וחכם בבינה והוא שמחמת ריבוי האורך ורוחב יכול לשכוח את תוכן המכוון, וכמו"],[3601330567,"עד\"מ מי שלומד גמ' עם פרש\"י ותוס' וכו' ועכ\"ז יכול להיות שלא ידע את נקודת האמת, וע\"כ צ\"ל וחכם בבינה שידע התוכן המכוון בחי' נקודת האמת שבהדבר הלכה כו', וזהו ע\"פ פשוט. וברוחני' הענין הוא להיות דבתושבע\"פ אין האלקוח בגילוי כ\"כ כמו בתושב\"כ שנא' תמיד וידבר ה' אל משה כו' שנראה בה האלקות, משא\"כ בתושבע\"פ כו', וע\"כ יכול להיות שהגם שלומד תו' ומ\"מ יהי' בבחי' יש ודבר ויכול לשכוח ח\"ו על ה' נותן התורה כו', וע\"כ צ\"ל וחכם בבינה שילמוד בבחי' ביטול ממש, וכמ\"ש בסש\"ב שצריך לכוון איך שזהו חכמתו ורצונו ית' והכוונה הזאת צ\"ל תמיד במוחו (בהעלם עכ\"פ ופעם בשעה או שתים צריך לכוון בזה כמ\"ש בסש\"ב שם), ועי\"ז יהי' הביטול בלימוד התו' ויהי' תכלית כוונתו לידע אמיתית התורה כו'.\nוע\"פ כל הנ\"ל יובן מ\"ש את ה' האמרת היום כו' (חסר בכי\"ק).\n<span data-k=\"ks\"><b>קיצור.</b> ותושבע\"פ שהיא הארת ש' מ\"ה שמתלבש לברר, ולכן עם היותה דבר ה' יש בה אותיות דלבנה המתבררים מק\"נ, הרי היא לימוד גם לנה\"ב, משכהו לבהמ\"ד שע\"י התורה נהפך האבן למים, וזהו מלמד י\"ל תושב\"כ בנה\"א, ודר בינה תושבע\"פ בנה\"ב, ומורה דעה י\"ל דעת בנשמות דבי\"ע, וז\"ע אלף בינה, דבינה השגה היא בחי' ד\"ת, וע\"י החכ' מתחדש בה בחי' ד\"ע, ומעמידו על בורי' הו\"ע וחכם בבינה שזה שומר את ההשגה, ובתורה הוא שבתושבע\"פ יזכור תמיד שזהו חכמתו ורצונו ית'.</span>"],[3601330568,"<h3>בס\"ד. ליל ב' דר\"ה, תרד\"ע</h3>\n<b>תקעו</b> בחדש שופר בכסה ליום חגינו, וצ\"ל מה שנא' בחדש סתם ולא פי' איזה חדש רק אח\"כ נא' בכסה, וארז\"ל איזה חג שהחדש מתכסה בו זה ר\"ה, ואינו מובן לכאו' למה נא' תחלה סתם ואח\"כ נותן סימן הול\"ל איזה חדש. ובמד\"ר אמור פכ\"ט אי' ר' ברכי' פתח תקעו בחדש שופר וכי כל החדשים אינם חדש, אלא בכסה שהחדש נכסה, וכי כל החדשים אינם נכסים, אלא ליום חגינו שיש בו חג, והלא ניסן החדש נכסה ויש בו חג, אלא שהחדש נכסה ויש בו חג וחגו בן יומו זה תשרי, וצ\"ל מה מחדש בזה שהחג בן יומו היינו ביום הכסה דוקא. ולהבין כ\"ז צלה\"ק מ\"ש (ישעי' סי' כ\"ה א') הוי' אלקי אתה ארוממך אודה שמך כי עשית פלא עצות מרחוק אמונה אומן, ואי' בזהר פ' בלק דקצ\"ג ע\"ב ה' אלקי זהו חכ' ובינה דהוי' בחכ' כו' ואלקי הוא בחי' בינה שנק' אלקים חיים, ומ\"ש אלקי הכוונה על בחי' תבונה מקור המדות כו', אתה הוא בחי' חסד והיינו התגלות החסדים שמאירים בבחי' מל' וכמ\"ש אתה כהן לעולם בחי' החסד על דברתי מלכי צדק בחי' המל' כו'."],[3601330569,"<b>וגם</b> המל' נק' אתה וכנודע דחכ' חסד ומל' נק' אתה כו'. ונמצא דבג' תי' ה' אלקי אתה נכלל כללו' הע\"ס מהחכ' עד המל' כו'. ארוממך לרומם כללו' ההשתל' בבחי' רוממות הכתר כו', וזה נעשה ע\"י העבודה דנש\"י דלמס\"נ באחד, דמס\"נ הו\"ע מסירת הרצונות והכוונה הוא למסור כל רצונותיו היינו גם הרצון בהגילוים, וכמ\"ש מי לי בשמים ועמך לא חפצתי כו' רק להכלל בעצמות א\"ס כו', ועי\"ז מרוממים כללות ההשתל' דהיינו הגילוים העליונים בבחי' רוממות הכתר כו', ועי\"ז ממשיכים גילוי אור חדש מבחינת פנימי' הכתר כו', דלכל המשכה צ\"ל העלאה, וע\"י העלאת ההשתל' בבחי' הרוממות דא\"ס ממשיכים גילוי אור חדש כו'. והנה פסוק זה אמר ישעי' הנביא בנבואה כעין הקדמה להנבואה שאו' אח\"ז שמנבא על ביטול מל' דנוגה וכמ\"ש אח\"כ ושמת מעיר לגל ואי' בבחיי דמעיר הן אותי' מיער והוא דחזיר מיער יתבטל ויהי' לגל כו', ובכדי שיתבטל מל' דנוגה צ\"ל ע\"י גילוי אור חדש מעצמות א\"ס כו'. וזהו דבר\"ה דאז הוא תכלית הרוממו' דא\"ס וכמא' המלך הקדוש שקדוש ומובדל מצ\"ע כו', אז דוקא אנו מבקשים\nוהרשעה כולה בעשן תכלה כי תעביר ממשלת זדון מן הארץ, להיות שזהו ע\"י המשכה מבחי' רוממות העצמות כו'. וזהו ג\"כ מש\"א ארוממך בכדי להמשיך גילוי אור חדש מבחי' עצמו' א\"ס לבטל את מל' דנוגה כו'. וזהו אודה שמך אודה הוא ההמשכה מלמעלמ\"ט כו', וההמשכה היא בשמך בחי' המל' להיות הגילוי בבי\"ע, והוא שיהי' הנס בפו\"מ והיינו שיהי' ביטול הנוגה בפו\"מ זהו ע\"י בחי' המל' שמאיר בגילוי בבי\"ע כו'. כי עשית פלא בא לבאר סדר ואופן ההמשכה דהאור חדש איך שנמשך בכללו' ההשתל' בע\"ס דאצי' ובבי\"ע כו', ועז\"א כי עשית פלא עצות מרחוק אמונה אומן כו', ואי' בזהר שם דכי עשית פלא הוא בחי' החכ' שהיא בחי' כיסוי ולבוש להאור דע\"ק כו', והנה ידוע דחכ' נק' א' מל' אאלפך חכ' שהו\"ע אולפנא ולימוד כו', אך זה כמו שהחכ' מאיר בגילוי והיינו בחי' הגילוי דחכ' שמאיר ומלמדת את הבינה כו'.\nקצב) <b>וכ\"ז</b> הו\"ע אלף מה שהחכ' מאיר ומלמד לבחי' בינה, אמנם ענין פלא שהוא היפך אותי' דאלף היינו כשהחכ' עולה למע' ומעלמת לאור הכתר, דבחי' כתר הוא בחי' העלם והיינו שהוא בבחי' העלם לגמרי שאינו גם בבחי' מקור להשתל' כו', והיינו שא\"ז בחי' ההעלם דכתר השייך אל הגילוי דההעלם הוא רק מה שאינו מתגלה כ\"א הוא בחי' העלם בעצם שאינו שייך לגילוי כו', וכאשר החכ' עולה לגבי הכתר נק' אז החכ' ג\"כ בשם פלא מל' הפלאה והעלם, כמו כי יפלא ממך דבר דהיינו שאינו מושג ונעלם כו', וכמו במופלא ממך אל תדרוש בחגיגה די\"ג ע\"א, ופרש\"י במופלא במובדל ומופרש ממך שלא רצה הקב\"ה לגלות לך (א\"כ זהו ע\"ד ולמכסה עתיק דברים שכיסה עת\"י כו'), וה\"ז היפך ענין הלימוד כו'. וענין ההעלם מה שהחכ' דוקא מעלים לאור הכתר, יובן עד\"מ באדם ששכלו וכח חכמתו חזק יש בכחו להעלים ולהסתיר את התענוג גם בחי' התענוג שמגיע לעצם נפשו שלא יהי' נראה ונגלה כלל, דהנה כאשר מתענג באיזה דבר הרי התענוג בא בגילוי וע\"ה שאינו בהתגלות כ\"כ כמו השמחה שבאה בהתגלות\nובהתפשטות, משא\"כ העונג שאינו בא בהתפשטו' והתגלו' כ\"כ כו' (וכידוע ההפרש בין שמחה לעונג, דשמחה היא מהבינה וכמ\"ש אם הבנים שמחה כו', דבחי' בינה להיות שזהו מה שבא בהתפשטו' והתרחבות שהשכל בא בהתגלו' ממש בהשגה בריבוי פרטים כו', ע\"כ"],[3601330570,"בא מזה בחי' השמחה שהיא בהתגלות ופועל התגלו' כל דבר נעלם (וכמו התפעלות מדות שבשכל שמתגלים בלב ע\"י השמחה כו', דטבע השמחה לפרוץ גדר כו' וכמ\"ש באורך בד\"ה שמח תשמח רנ\"ז), והתענוג להיותו בבחי' החכ' שאינו בבחי' התגלות עדיין אדרבה הוא בבחי' נקודה שהו\"ע הכיווץ וההתכללו' בעצמו כו', ע\"כ גם התענוג אינו בהתגלו' והתפשטו' כו', והוא ההפרש בין מועדים לשמחה בחי' מוחין דאימא ובשבת וקראת לשבת עונג בחי' מוחין דאבא כו'). ומ\"מ העונג נראה ונגלה ג\"כ, וכמו חכמת אדם תאיר פניו שזהו מצד העונג, וכמו צהבו פניו מגילוי השכלה חדשה כו', וכן כל עונג ניכר בפניו דהכרת פניו ענתה בו שהוא מתענג על איזה דבר, דכשם שהצער והעוצב נראה ונגלה בפנים כמו ויפלו פניו, מדוע נפלו פניך כו', כמו\"כ העונג נראה ג\"כ בפנים כו'. אמנם מי שכח חכמתו חזק ביכולתו להעלים ולהסתיר בעצמו גם תענוג עצמי, כמו כאשר מבשרין לו בשורה טובה בתענוג נפלא מאד אשר מגעת בעצם נקודת עצמותו אם בעוצם הגדולה וכבוד או בעושר גדול או בתענוג השכלה עמוקה ביותר ה\"ה מעלים את התענוג\nשלא יהי' נראה ונגלה כלל, ויש אדם שאין כח שכלו חזק ואין מעצור לרוחו וזהו מצד מוחין דקטנות כו', אבל כשיש מוחין דגדלות יוכל להעלים ולהסתיר כל מה שראוי וצריך להעלים כו'. וי\"ל לפי שכח החכ' ה\"ה בבחי' אחיזה ותפיסא בכלי במקצת עכ\"פ וגם שבא בבחי' ציור והגבלה שהוא בבחי' חכ' כו', ע\"כ בכחו להעלים את התענוג, דהנה תענוג הוא כח עצמי שאינו בבחי' ציור והגבלה בעצם ואינו בבחי' תפיסא בכלי כלל, וה\"ז אור בלא כלי, והוא אור הבלתי מוגבל ומצוייר באיזה דבר, וע\"כ הוא בא בהתגלו' שניכר עכ\"פ שמתענג כו' (רק להיותו עצמי אינו בהתפשטות כמו השמחה כו'), כי אין דבר שיעכב אותו כו', רק החכ' להיותה בבחי' ציור גם במדרי' היותר גבוה ונעלה שהיא בחי' חכ' עכ\"פ ע\"כ ביכולתו להעלים ולעכב בחי' התענוג שלא יהי' ניכר כו', ומובן שהמעלים צ\"ל בערך ובקירוב אל הנעלם (כי הרי אין הכוונה כאן שהמעלים הוא דבר זר ח\"ו רק שמתעלם באיזה כח היינו שמתלבש בהכח ההוא ועי\"ז הוא מתעלם כו', שבהכרח הוא שיש בזה איזה קירוב כו'), ולהיות שהנעלם הוא עצמי ע\"כ גם המעלים\nצ\"ל כח עצמי דוקא, וזהו שהחכ' דוקא להיותו כח עצמי (לא כח המתפשט כמו הבינה כו') ביכולתו להעלים על התענוג כו', וזהו שההתעלמו' הוא ע\"י החכ' דוקא לפי שההתעלמו' הוא ע\"י התלבשו' באיזה כח, והמעלים צ\"ל כח עצמי דוקא לכן זהו ע\"י החכ' דוקא שהוא כח עצמי כו' (ובשרשו זהו שהתענוג נעשה בבחי' חכ' ובזה הוא מתעלם כו' וכמשי\"ת) (וענין ההעלם אין זה שהוא בחי' העלם ממש, כ\"א הכוונה שעי\"ז יהי' ההמשכה וההתגלות דבחי' פנימיות הכתר דהיינו התענוג העצמי כו' וכמשי\"ת), ושרש בחי' זו הו\"ע בחי' ח\"ס שיש בכחו להעלים ולהסתיר שלכן נק' סתימאה דלא אתפתחא בל\"ב שבילין כו'.\n<span data-k=\"ks\"><b>קיצור.</b> אמנם פלא הוא כמו שהחכ' מעלמת על פנימיות הכתר שהוא בחי' העלם בעצם, וכשהחכ' עולה לפנימיות הכתר נק' פלא, ועד\"מ מי שכח חכמתו חזק בכחו להעלים את התענוג, דתענוג להיותו עצמי אינו בהתגלות כמו השמחה שהיא התפשטות, ולכן שמחה בבינה ועונג בחכ', ומ\"מ ה\"ה ניכר ונגלה כמו צהבו פניו, ומי שכח חכמתו חזק בכחו להעלים גם תענוג עצמי, והוא מפני שחכ' הוא ג\"כ כח עצמי ע\"כ התענוג מתלבש ומתעלם בזה, ובשרשו הוא בחי' ח\"ס.</span>"],[3601330571,"קצג) <b>וביאור</b> הענין הוא, דהנה ידוע דכתר הוא בחי' ממוצע בין אוא\"ס המאציל אל הנאצלים, דלהיות שהנאצלים הם באין ערוך לגבי עצמו' המאציל, דהרי אצי' הוא בחי' ציור אדה\"ע שעז\"נ ועל דמות הכסא דמות כמראה אדם כו' חכ' מוחא בינה לבא כו', ועצמו' המאציל הרי אינו בגדר ציור אדם כלל וכמ\"ש כי לא אדם הוא כו', שעז\"א וגם נצח ישראל לא ישקר ולא ינחם כי לא אדם הוא כו', דהטעם מה שלא ינחם לפי שלא אדם הוא כו', דבציור אדם שייך ניחומים כו', להיות דענין הניחום הוא ענין השינוי שמשתנה ומתהפך כו', וזה שייך בציור אדם שהו\"ע שכל ומדות דלפעמים השכל מחייב כך ולפעמים מחייב באו\"א ולפי אופן השכל כן משתני' המדות, וע\"כ יכול להשתנות מחסד לדין ומדין לחסד ע\"פ השכל, והיינו שגם אם נתפשט כבר לחסד ביכולת להשכיל באופן אחר והוא שצריך לשנוא ולהרחיק כו', וכן להיפך משנאה לאה' כו'. דכמו\"כ הוא למע' במדות דאצי' דמתחלה חייבו כבי' חכמתו ומדותיו ית' להיות בריאת והתהוות העולמו', וכמ\"ש בראשית ברא בחוכמתא ברא וכתי' ששת ימים עשה ה' כו', ואח\"כ\nהי' להיפך וכמ\"ש ויתעצב כו' נחמתי כו', ואח\"כ כתי' לא אוסיף עוד לקלל כו', והיינו מפני שנמצא טעם ושכל אחר נתהפך לחסד כו', וכן גם מדות שברצון שהן מדות שבכתר יכולים ג\"כ להתהפך הגם שנק' טורי חשוכא להיותם למע' מבחי' שכל וטעם כו', הרי ידוע שזהו שהן למע' מטעם גלוי אבל מ\"מ יש טעם כמוס לרצון כו', ומאחר שיש טעם כמוס ע\"כ ביכולת שיתהפך כו', רק שזהו בבחי' חיצוני' הרצון, דפנימי' הרצון אין טעם לרצון כלל גם לא טעם כמוס כו', והוא בחי' רצון עצמי שאינו בא מצד איזה טעם שיהי' כ\"א מצד העצם שהוא כך כו', ובחי' ומדרי' זו זהו בחי' כי לא אדם שלא ינחם ולא ישתנה כלל כו'. ומשם הוא שרש מלכות בית דוד שעז\"נ וגם נצח ישראל כו' ולא ינחם כו', דמלכות בית דוד הוא מבחי' פנימי' ועצמו' א\"ס שאין בזה שום השתנות כלל כו', ולכן דוד מלך ישראל חי וקיים כו', וכמש\"א לא יכבה נרו לעולם ועד והיינו שישנו אורו תמיד כו', וכמ\"ש ודוד עבדי נשיא עליהם לעולם כו', וכמ\"ש רמה קרני דוד שנמשח בקרן כו', דקרן הוא המשכה עצמי' וכמ\"ש וירם קרן לעמו כו'. וזהו\nג\"כ הרצון דמצות שהוא רצון עצמי שאינו משתנה כו', ומ\"ש מצות בטלות לעתיד אין הכוונה שיתבטלו ח\"ו, כ\"א שיתבטלו בבחי' העדר תפיסת מקום לגבי האור העצמי דלעתיד והיינו בחי' תענוג העצמי שמתגלה לעתיד כו', וכידוע דרצון ועונג שניהם בבחי' עצם ממש רק שהרצון הוא בחי' מרוצת העצמו' שהוא בחי' ההמשכה וההתגלו' כו', והעונג הוא העצמי שאינו בא בבחי' המשכה והתגלות כו', וע\"כ הרצון הוא בחי' חיצוני ועונג פנימי כו', וכמ\"ש מזה באורך בדרוש יו\"ט של ר\"ה, רס\"ו. ולעתיד כשיהי' התגלו' בחי' העונג העצמי הבלתי מורגש שזהו אמיתית העלי' דלעתיד בחי' אהי' אשר אהי' כו', והוא גילוי בחי' עדן עילאה סתימאה כו', יתבטל בחי' הרצון לגבי גילוי זה וכמו שרגא בטיהרא כו', וכמו כ\"ע אע\"ג דאיהו אור צח כו' אוכם הוא כו' בבחי' שחרות וביטול כו'. וזהו ג\"כ שרש ענין התשו', דלכאו' מה שע\"י התשו' נמשך סליחת עוונות ה\"ז כמו ניחום ושינוי ח\"ו, אבל באמת א\"ז בבחי' ניחום כ\"א שע\"י התשו' מגיע בבחי' התענוג העצמי שלמע' מהרצון דמצות כו' (והו\"ע קדושתי שלמע' מקדושתכם דאשר\nקדשנו במצותיו כו'), דלהיות שהעונג והרצון שניהם עצמי' ע\"כ אינם בבחי' סבה זל\"ז ויכול להיות עונג בלא רצון, וכמו רק באבותיך חשק ה' שזהו העונג בנש\"י מצ\"ע"],[3601330572,"לבד קיום התו\"מ כו', וכן יש רצון בלא עונג כמו החוקים כו' וכמו אין טעם לרצון גם לא טעם ועונג כו', וע\"י התשו' מגיעים בבחי' עונג העצמי דעצמות ופנימיות א\"ס דלהתם דוקא מטא עקתא דישראל בחי' המיצר שבא מהריחוק כו' דשם אינו תופס מקום הרצון דמצות כו', אבל א\"ז שהרצון משתנה ומתחלף ח\"ו, וגם אינו כענין כחשכה כאורה כו', כ\"א מפני שלגבי תענוג העצמי אין הרצון תופס מקום ויכול להיות עונג גם בלא רצון כו', וממילא נמשך הרצון ג\"כ להיות דהרצון הוא חיצוני והעונג פנימי ע\"כ כשנמשך בחי' העונג העצמי נמשך ג\"כ הרצון מחדש כו', וזהו מה שמתמלאים הפגמים דלבד מה שנסלח הכל מצד המשכת והתגלות העונג העצמי כו', הנה מתמלא הכל ע\"י שנמשך הרצון מחדש כו'. והמשכת העונג העצמי הוא ע\"י התשו' דוקא לפי שא\"ז כענין דכחשכה כאורה ע\"כ צריכים תשו' כו', והעיקר הוא בתשובה אמיתי' שבעומק הנפש ביותר וכענין צעק לבם כו' צעקת הלב שלמע' מצעקת הקול כו' וכמ\"ש במ\"א, וי\"ל דכמו\"כ ע\"י התשו' בחרטת הלב וקבלה על להבא ממשיכי' ג\"כ מבחי' התענוג העצמי, והוא מפני\nשנש\"י מושרשים בעצמו' א\"ס ע\"כ ע\"י התשו' שמתחרט באמת ובקבלה אמית' על להבא ממשיכים ג\"כ בחי' תענוג העצמי ולהיות המשכת הרצון מחדש כו', אמנם העיקר הוא התשו' דצעק לבם כו'. ומובן מכ\"ז איך שהנאצלים שהן בבחי' ציור אדם ה\"ה באין ערוך כלל לגבי עצמו' המאציל כו', וע\"כ בהכרח שיהי' בחי' ממוצע שעל ידו יהי' חיבור ושייכות לעצמו' המאציל עם הנאצלים.\n<span data-k=\"ks\"><b>קיצור.</b> דהנה אצי' הוא באין ערוך לגבי עצמות המאציל, אצי' בחי' אדם, וא\"ס כי לא אדם הוא להנחם, ניחומים שייך בשכל ומדות שמשתנים, גם ברצון מפני הטעם כמוס לרצון, אבל רצון עצמי אינו משתנה, ומשם שרש מב\"ד, והוא הרצון דמצות, ומה שמצות בטלים לעתיד, זהו מפני גילוי תענוג העצמי שהוא בחי' פנימיות ורצון העצמי חיצוניות, ואינו תופס לגבי הפנימיות, וזהו שרש ענין התשובה שמגיע בבחי' תענוג העצמי, שהוא העונג בנש\"י מצ\"ע, וממילא נמשך גם הרצון, והעיקר בתשובה דצעק לבם, וי\"ל גם בחרטה וקבלה על להבא, ולהיות שאצי' הוא באין ערוך צ\"ל ממוצע.</span>\nקצד) <b>(וי\"ל</b> דענין הממוצע בזה א\"ז רק שמאוא\"ס המאציל יתהוו הנאצלים כ\"א שיהי' חבור ושייכות להנאצלים עם העצמו' כו', וא\"ז כמו שהאצי' הוא בבחי' ממוצע בין אוא\"ס אל הנבראי' וכמשנת\"ל פקס\"א, שהרי הנבראים אין להם שום חבור ושייכות אל האוא\"ס המאציל שהן באין ערוך לגמרי כו', וענין הממוצע בזה הוא רק ירידת האור דאוא\"ס ב\"ה באופן כזה להוות נבראים שזהו ע\"י האורות וכלים דאצי' דהאור הוא בחי' אור מצומצם והכלים הם בבחי' מציאות כו' (וגם בזה צריכים ממוצע לחבר האורות עם הכלים לפי שרחוק ערכם זמ\"ז כו' וכמ\"ש במ\"א), וע\"י הכלים האור מהווה כמהות הכלים כו', וההתהוות הוא בדרך אין ערוך כו'. אבל התהוות האצי' ה\"ה בבחי' אצי' והיינו בבחי' קירוב הערך כו', וע\"ה שנתהוו ג\"כ בבחי' יש וכמ\"ש והחכ' מאין תמצא שנמצא מאין בבחי' יש ונק' יש נאצל כו', מ\"מ הרי א\"ז בבחי' יש ממש ח\"ו דמאחר שנק' יש נאצל הרי ש' אצי' שולל מבחי' יש וה\"ז רק מה שנתגלה כח הכמוס והסתום באוא\"ס המאציל כו' (ומה שנק' יש זהו מפני שבא בהתגלו' וכל התגלו' ה\"ז בבחי' מציאו' דבר כו', וכמ\"ש במ\"א"],[3601330573,"שזהו ההפרש בין ש' אור לש' אצי', דאור הוא כמו שכלול עדיין בהעצמו' שאינו עולה עדיין בשם אור וזיו כו', וש' אצי' הוא האור שנאצל ונתגלה בבחי' הפרשת הארה מן העצמו' כו'). והגם דזה שאצי' הוא בבחי' גילוי ההעלם זהו רק לגבי חיצוני' הכתר שבבחי' מקור לאצי' כו' (דבד\"כ זהו בחי' ז\"ת דאריך דאו\"א מלבישי' לזרועות דא\"א כו'), דבבחי' זו שייך שהע\"ס דאצי' הם כלולי' שם ונאצלו ונתגלה מן ההעלם אל הגילוי כו', אבל בחי' פנימי' הכתר שזהו בחי' עצמו' המאציל הרי אינו בבחי' מקור לע\"ס דאצי' ואינו בערך לו' שהם שם בבחי' התכללו' כו' כנודע. ומ\"מ מאחר שהן בבחי' אצי' בהכרח לו' דכללו' בחי' האצי' (היינו גם בחי' חיצוני' דאצי' כו') יש להם שייכות לאוא\"ס עצמו' המאציל כו', שה\"ה עכ\"פ בבחי' מאציל ונאצל בהכרח שיש להם שייכות שהנאצל הוא לפ\"ע המאציל הגם שאינו בבחי' מקור אליו כו'. והגם דבאמת הרי יותר משאין ערוך עשי' לגבי אצי' אין ערוך אצי' לגבי הא\"ס כו', הנה עיקר ענינו הוא לגבי האוא\"ס שלפה\"צ, וכמו שמבו' הטעם ע\"ז בתו\"א ד\"ה פתח אליהו לפי שענין\nהצמצום הוא התעלמו' האור ונמשך רק הארה לבד כו', והתהוות בי\"ע מאצי' הוא ע\"י פרסא דמהות האור מתלבש בהפרסא כו'. ומ\"מ הרי התהוות בי\"ע בבחי' ההתגלו' שבהם הוא מבחי' אור של תולדה לבד שאינו מהות האור הראשון (המתעלם לגמרי בהפרסא כו'), והתהוות האצי' ה\"ה בבחי' קירוב מהאוא\"ס שאחה\"צ דהיינו בחי' אור הקו בכלל שגם האור הוא בבחי' דבקות במקורו כו', דע\"ה שהצמצום הוא סילוק האור ופרסא הוא שמהות האור הוא בהפרסא כו', מ\"מ יש יתרון מע' בצמצום על פרסא דבפרסא האור מתעלם ואינו מאיר רק אור של תולדה כו', ובצמצום האור חוזר ומאיר כו' כמ\"ש במ\"א, וע\"כ הקו הוא בבחי' דבקות במקורו כו'. ובאמת הרי גם עצמו' האור דאוא\"ס שלפה\"צ נמצא ונמשך גם לאחה\"צ (וכמו עצמו' נקודת המל' דאצי' שנעשית בבחי' עתיק כו', וכמו\"כ הוא בבחי' מל' דא\"ס ועוד למע' מזה כו' והוא בחי' פנימי' הקו כו'), דצ\"ל דאצי' הוא בבחי' שייכות לזה כו', והרי לגבי מדרי' זו הרי ודאי אין ערוך כו', דבבחי' ומדרי' זו שייך לומר דיותר משאין ערוך עשי' לגבי אצי' אין ערוך אצי' לגבי הא\"ס\nכו'. הנה ע\"ז הו\"ע הממוצע שהערך והשייכות דאצי' הוא לגבי בחי' הממוצע כו', וז\"ע הממוצע שבין עצמו' המאציל אל הנאצלי' שהממוצע יש בו מבחי' העצמו' כמשי\"ת, בכדי שיהי' חבור ושייכות הנאצלי' אל העצמו' כו', הגם שהעצמו' שבהממוצע ג\"כ אינו בבחי' מקור כו'. ולכאו' מאחר שהנאצלי' לגבי העצמו' הן באין ערוך לגמרי והממוצע הרי יש בו מבחי' העצמו' ממש איך יהי' להנאצלי' ערך ושייכות להעצמו' שבהממוצע ושעי\"ז יהי' להם שייכות אל עצמו' המאציל כו', זה יתבאר לקמן בעזה\"י.\n<span data-k=\"ks\"><b>קיצור.</b> וענין הממוצע הוא שיהי' לנאצלים שייכות אל העצמות, ולא כמו האמצעית דאצי' שזהו רק בההתהוות והנבראים הן באין ערוך, שהרי אצי' הוא מ\"מ בבחי' גילוי ההעלם, הגם שזהו רק לגבי מקור הנאצלים, מ\"מ מאציל ונאצל יש להם שייכות, ומה שא' יותר משאין ערוך עשי' כו', היינו לגבי אוא\"ס שלפני הצמצום, משא\"כ לגבי הקו, אך הלא בהקו יש בפנימיותו בחי' העצמות ולגבי' הרי אצי' באין ערוך, הנה ז\"ע הממוצע שבו מבחי' העצמות ועי\"ז יש לאצי' שייכות אל העצמות.</span>"],[3601330574,"קצה) <b>והנה</b> כשם שהוא בנאצלי' י\"ל דכמו\"כ הוא גם בנשמו', שהרי הנשמו' הן אלקו' גם הנשמו' דבי\"ע שנתהוו בבחי' יש מ\"מ ה\"ה אלקות בעצם מהותם כו', וא\"כ הרי התהוות הנשמה הוא באו\"א מהתהוות הנבראים כו', והיינו דלבד זאת דהתהוותם הוא בבחי' השפעה עצמי' כו' וכמ\"ש במ\"א הרי מ\"מ זהו בבחי' העלם כו' (וכמ\"ש במ\"א דא\"ז כמו אור ומאור שהאור הוא מעין המאור, משא\"כ בתולדה יכול להיות שלא יהי' כמו המוליד כו') (ובד\"כ אין הכוונה כאן רק על בחי' העצמי' כ\"א גם על ההתגלות כו'), כ\"א שהתהוות הנשמו' הוא באופן כזה שהן בבחי' שייכות לאוא\"ס ב\"ה. ולכן כאו\"א יכול להגיע למדרי' היותר גבוה בעבודתו וכמו מתי יגיעו מעשי כו', והוא שבעבודתו ביגיעת נפש ויגיעת בשר בזיכוך החומרי' ובעבודה פנימי' בנשמתו בעבודה אמיתי' תתעלה נפשו למע' מאד כו', והיינו גם במוח ולב תתעלה בגילוים ובהשגות נעלות מאד כו', ובפרט כשיגיע לבחי' רעו\"ד ואה\"ר שעי\"ז תופסים בבחי' עצמו' א\"ס וכמא' לית מח' תב\"כ אבל נתפס איהו ברעו\"ד כו', שאחר העבודה דרעו\"ד גם העבודה דתומ\"צ\nהיא במדרי' נעלית יותר, וכמ\"ש טוב טעם ודעת למדני כי במצותיך האמנתי דהיינו שיהי' הטו\"ד במדרי' גבוה יותר כו', שהרי אין הכוונה שמתחלה לא יש לו דעת כלל רק הכוונה שע\"י שבמצותיך האמנתי יהי' יתרון גילוי אור ביותר בטו\"ד דתומ\"צ כו', ומכ\"ש ע\"י התשו' שמגיע בבחי' עצמו' א\"ס כו', ואח\"כ ויעקב הלך לדרכו בעבודה דמוח ולב ותומ\"צ הוא במדרי' גבוה ונעלה ביותר כו'. וכ\"ז הוא בכח הנשמה לבא לזה שאינו בא בבחי' שינוי המהות כו' (ועם היות דבחי' אה\"ר זהו מה שנותנים מלמע' כו', הרי בכח הנשמה לקבל זאת ולא כמו מלאכים דהושיט הקב\"ה כו', ובד\"כ זהו גילוי בחי' האו\"מ שבנפש כו'), והיא יכולה לקבל כל אור עליון הנמשך ע\"י התומ\"צ שהן גילוים דאוא\"ס ב\"ה ואינה מתבטל ממציאותה כו', וכ\"ז הוא מפני שהנשמו' יש להם חבור ושייכות לאוא\"ס ב\"ה (וכמ\"ש במ\"א דנשמו' עיקרם הוא באצי' משא\"כ המלאכים עיקרם הוא בבי\"ע כו'), והיינו ג\"כ ע\"י הממוצע שבין אוא\"ס המאציל אל הנאצלי' שעי\"ז יש חבור ושייכות לנאצלי' ולנשמות אל עצמו' המאציל כו'). ובחי' ממוצע זה בהכרח שיהי'\nבו מבחי' העצמו' וגם מבחי' הנאצלים דאל\"כ אינו בבחי' ממוצע (וא\"א שיהי' ע\"י חבור ושייכות נאצלי' אל העצמות כו'), אך מה שיש בו מבחי' העצמו' אינו רק מבחי' אחרונה שבעצמו' שמאיר בבחי' פנימי' הכתר שבו שנק' כשב\"כ, ומה שיש בו מבחי' הנאצלים הוא מה שנק' ראש ומקור לנאצלי' והוא בחי' חכ' שבכתר שנק' ח\"ס דא\"א כו'. דהנה הכתר הכללי הוא בחי' רצה\"ע ויש בזה ג' מדרי' בד\"כ, בחי' המדות שברצון וזהו מה שבא בבחי' מקור ממש לע\"ס דאצי' ומתלבשי' בהם והן בחי' ז\"ת דאריך דאו\"א מלבישי' כו', ובחי' חכ' שבכתר שבבחי' טעם כמוס לרצון שמזה הוא סבת התחלקות הרצון כו' ה\"ז בבחי' שייכות אל הנאצלים כו', ובחי' כשב\"כ הוא בחי' הרצון העצמי שאין טעם כלל לרצון כו', שזהו בחי' תחתונה שבעצמו' שמובדל בערך מלהיות בבחי' מקור לנאצלים כו' (ומובדל ג\"כ מבחי' ח\"ס ומדות שברצון וכמ\"ש והבדילה כו' בין קדש ובין קה\"ק כו', דקה\"ק זהו בחי' כשב\"כ וכמ\"ש במ\"א בפי' אית מלך לעילא ברזא דקה\"ק כו' שיש פרוכת והבדלה ביניהם כו'). ובד\"כ ב' המדרי' שבממוצע דכתר הן בחי' עתיק\nואריך, דבחי' עתיק היא בחי' תחתונה שבמאציל, וכידוע בפי' עתיק שהוא ל' העתקה מספר לספר וכמו אשר העתיקו אנשי חזקי' כו', שזהו המשכת"],[3601330575,"והעתקת העצמו' כמו שהוא כו', וע\"כ הוא בבחי' העתקה מל' ויעתק ההרה שנעתק ונבדל מע\"ס דאצי' שאינו כלל בבחי' מקור להם כו', ובחי' א\"א הוא בבחי' מקור לנאצלים שג\"כ למע' מהם רק שהוא בבחי' מקור להם כו'. וזהו מ\"ש בע\"ח דלפעמים הכתר נמנה במנין הספי' ולפעמים אינו נמנה והיינו דבחי' אריך בכלל או בחי' ח\"ס בפרט נמנה במנין האצי' ובחי' כשב\"כ או בחי' עתיק אינו במנין הספי' וכמא' אנת הוא חד ולא בחושבן כו'. וע\"כ ע\"י הממוצע דכתר שיש בזה מבחי' עצמו' המאציל עי\"ז הוא חבור ושייכות דנאצלים לעצמו' המאציל כו'.\n<b>ועפ\"ז</b> יובן מ\"ש תקעו בחדש שופר, דפי' בחדש הוא ל' התחדשות והיינו להמשיך גילוי אור חדש מבחי' עצמו' א\"ס כו', דהנה בר\"ה הוא בנין המל' והוא שממשיכים רצון ועונג בענין המלוכה דשרש ההמשכה הוא מבחי' עצמו' א\"ס ב\"ה, וזהו מ\"ש בכסה דהיינו שההמשכה היא מבחי' א\"ס המכוסה ונעלם והיינו מבחי' העליונה שבהממוצע, דהרי מה שהוא בבחי' ראש ומקור לנאצלים הרי א\"ז אור חדש מאחר שהוא בבחי' שייכות אל הנאצלים כו', כ\"א המשכת האור חדש מבחי' העליונה שבהממוצע שזהו בחי' תחתונה שבעצמו' וזהו בכסה כו', וממשיכי' זה ע\"י תקיעת שופר שהו\"ע הצעקה פנימי' דתשו' שזה מגיע בבחי' עצמו' כו', וכמשנת\"ל פקצ\"ג שע\"י התשו' ממשיכי' בחי' תענוג העצמי ועי\"ז הרצון מחדש בבחי' אור חדש ממש כו'. וזהו שאמר בחדש סתם דהכוונה כאן לבאר ענין ההמשכה שע\"י תקיעת שופר שהוא המשכת אור חדש כו', ובחדש הוא ג\"כ התחדשות הלבנה והיינו שההמשכה היא בבחי' מל', דזהו עיקר הכוונה להיות בחי' המלוכה בגילוי למטה וכמש\"א מלוך על העולם כולו בכבודך כו' והופע בהדר גאון עוזך על\nכל יושבי תבל ארצך כו' שזהו ע\"י המשכת אור חדש כו'. וזהו ג\"כ מש\"א במדרש שחגו בן יומו שהוא ביום הכסה דוקא והיינו שהמדרי' שמכוסה זהו עצמו שנמשך ומתגלה כו', דהנה יש במדרי' הממוצע שמאיר רק הבחינה התחתונה שבהממוצע והוא שהממוצע מפסיק ביניהם והיינו בממוצעים דס' השתל' כו' וכמ\"ש במ\"א, וע\"כ או' כאן שהחג והגילוי הוא ביום הכסה דהיינו דהמדרי' העליונה שבהממוצע שמכוסה ונעלם זהו עצמו שנמשך בגילוי כו', וזהו תקעו בחדש שופר שע\"י השופר ממשיכים בחי' אור חדש מעצמו' א\"ס ב\"ה, וזהו בכסה ליום חגינו דהגילוי הוא מבחי' הא\"ס המכוסה ונעלם שמאיר בגילוי בחי' מל' ועי\"ז יהי' גילוי המלוכה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וכמו\"כ הנשמות שהן מהות אלקות התהוותם הוא שיש להם שייכות אל העצמות, ולכן ביכולתם לבוא למדרי' גבוהות גם במוח ולב וכ\"ש ברעו\"ד וכ\"ש בתשומע\"ט, ויכולים לקבל הכל, וזהו ע\"י הממוצע שיש בו מהעצמות מבחי' אחרונה שבו, ומהנאצלים מהעליון וראש שבהם, והוא בחי' הכתר, בחי' חכ' ומדות שבו, ובחי' כתר שבו, ובד\"כ הוא בחי' עתיק ואריך. וזהו תקעו בחדש גילוי או\"ח, בכסא בחי' העליונה שבממוצע, וההמשכה היא ע\"י שופר.</span>"],[3601330576,"<h3>בס\"ד. יום ב' דר\"ה, תרד\"ע</h3>\n<b>שיר</b> המעלות ממעמקים קראתיך הוי', הנה מזמור זה תקנו לאומרו בעשי\"ת, וצ\"ל מהו\"ע דבכ\"י מעשי\"ת צ\"ל מזמור זה דשיר המעלות ממעמקים כו'. ובזהר בשלח דס\"ג סע\"א אי' ר' חזקי' פתח שיר המעלות ממעמקים, שיר המעלות סתם ולא פי' מאן אמרו, אלא שיר המעלות דזמינין כל בני עלמא למימר כו' ומאי הוא ממעמקים קראתיך, הכי תאנא כל מאן דמצלי צלותא קמי' מלכא קדישא צריך למבעי בעותי' ולצלאה מעומקא דלבא כו', ומי אמר דוד הכי והא כתי' בכל לבי דרשתיך (ופי' במק\"מ וא\"כ מה הי' צריך לו' עוד ממעמקים קראתיך כו'), אלא דבעי לכוונא דעתי' ורעותי' מעקרא דכל עקרין כו'. וצ\"ל מהו ההפרש בין מ\"ש בכל לבי דרשתיך למ\"ש ממעמקים קראתיך שזהו מעקרא דכל עקרין כו'. גם צ\"ל מ\"ש דזמינין כל בני עלמא למימר דתנא דמאן דמצלי כו' מעומקא דלבא כו', וכי משו\"ז זמינין כל בני עלמא למימר דא כו'. ולהבין זה ילה\"ק משנת\"ל דהכתר הוא בחי' ממוצע בין המאציל לנאצלים דלהיות שהנאצלים הן באין ערוך לגבי העצמות, וע\"כ בכדי שיהי' חבור ושייכות להנאצלים אל עצמו' זהו ע\"י הממוצע שכלול מבחי' עצמו' המאציל ומבחי' הנאצלים כו'.\nקצו) <b>אמנם</b> עדיין אינו מובן איך הכתר הוא בבחי' ממוצע, מאחר דבחי' עליונה שבו שהיא בחי' תחתונה שבמאציל והוא בחי' עתיק או כשב\"כ, דעתיק הוא בחי' העתקת העצמו' ה\"ז בחי' עצמות המאציל ממש כו', וגם בחי' כשב\"כ שזהו בחי' רצון העצמי כנ\"ל פקצ\"ה ה\"ז בחי' עצמות א\"ס ב\"ה, הרי בחי' ומדרי' זו אינו בבחי' שייכות כלל אל הנאצלים ואינו נמנה עמהם, וא\"כ ה\"ה לעולם למע' כמו בבחי' עצמות המאציל כו'. ובחי' תחתונה שבו שזהו בחי' ח\"ס בפרט וא\"א בכלל לעולם נמנה עם הע\"ס שזהו בבחי' מקור להם כו', הרי שהן ב' מדרי' נבדלות שזה במדרי' העצמות וזה במדרי' הנאצלים כו', ואיך הוא בבחי' ממוצע כו'. דכשם דעצמו' המאציל והנאצלים הן באין ערוך, כמו\"כ הוא בהב' מדרי' שבהממוצע מאחר שזה בבחי' העצמות ממש וזה בבחי' שרש לנאצלים כו', ובפרט לפמשנת\"ל פקצ\"ד דענין הממוצע שיהי' חבור ושייכות אל הנאצלים עם עצמות המאציל, ואיך יהי' זאת ע\"י ממוצע כזה שהמדרי' העליונה מובדלת לגמרי מהנאצלים והמדרי' התחתונה שייכה להנאצלים ואינה בערך המדרי' העליונה כו',\nוהיינו שבהממוצע גופא המדרי' התחתונה שבו היא באין ערוך לגבי המדרי' העליונה שבו, כי המדרי' העליונה שהיא בבחי' העתקה והבדלה לגמרי מן הנאצלים כמו\"כ הוא גם לגבי שרש ומקור הנאצלים כו', ואיך יהי' החיבור והשייכות ע\"י בחי' ממוצע כזה כו'. כ\"א זה יכול להיות רק כאשר הממוצע הוא מדרי' אחרת שאינו לא העליון ממש ולא התחתון ויש בו מן העליון והתחתון כו', והיינו דע\"ה שאינו העצמות מ\"מ יש בו מבחי' העצמות ממש, וכמו\"כ ע\"ה שאינו התחתון דהיינו הנאצלים יש בו ממש מבחי' התחתון כו', ובממוצע כזה שייך לומר דלפעמים הוא נמנה ולפעמים אינו נמנה דע\"ה נמנה במנין הספי' מצד מדרי' הנאצלים שבו, לפעמים הוא עצמו אינו נמנה במנין הספי' מצד בחי' העצמות שבו כו', וע\"י ממוצע כזה יכול להיות חבור ושייכות הנאצלים אל העצמות מפני שהמדרי' התחתונה שבו"],[3601330577,"ה\"ה ממש כמו הנאצלים (ע\"ה שא\"ז בחי' הנאצלים ממש כמובן), ובחי' העליונה שבו היא ממש כמו העצמות ומ\"מ אינו עצמות ממש כו', והכל הוא במהות א' כו', וע\"כ עי\"ז אפ\"ל חבור ושייכות הנאצלים עם העצמות כו', וזה אא\"ל בבחי' עתיק ואריך שהן ב' מדרי' מובדלות כו' כנ\"ל. והנה במ\"א מבואר דבחי' עתיק ע\"ה שזהו העתקת העצמות מ\"מ כאשר בא בבחי' כתר אינו כמו בבחי' המאציל עצמו כו', וכמו בחכ' דאצי' דפנימי' אבא הוא פנימי' עתיק ממש ומ\"מ אינו כמו בחי' פנימי' עתיק דלא ידע ולא אתיידע כלל, וכמו שבא בבחי' פנימי' אבא אפשר להגיע לזה ע\"י בחי' השלילה דמצות ל\"ת דלאו קודם להן כו' וכמ\"ש במ\"א, וכמו\"כ בחי' עתיק ע\"ה שזהו בחי' העצמות מ\"מ הרי נעשה בבחי' ממוצע דעצמות המאציל אינו בגדר ממוצע כו'. וי\"ל דזהו דבע\"ח שמ\"א ספ\"ג כשמדבר בענין הממוצע שבכתר שיש בה בחי' מאצילות ובחי' נאצלות כ' ושניהם נק' כתר, די\"ל הכוונה שא\"ז בחי' עצמות המאציל ולא בחי' האצי' כ\"א מדרי' ממוצעת כו', ומ\"מ א\"ז מספיק עדיין שהרי מ\"מ בחי' עתיק הוא בבחי' העתקה והבדלה מהאצי'\nשאינו ממהותו כלל כו', ונק' לא ידע שבעצמותו אינו מהות ידוע כלל וממילא לא אתיידע כלל כו', וזהו מה שמובדל לגמרי מהנאצלים דמאחר שאינו בבחי' מהות ידוע כלל גם בעצמו ממילא ה\"ה מובדל לגמרי מהנאצלים (שהן בבחי' מהות ידוע כו'). וע\"ה שא\"ז כמו העצמות ממש היינו שבעצמות אינו שייך לו' כלל ענין ההעתקה מן הנאצלים, וכמו שבא בבחי' כתר ה\"ה בבחי' העתקה כו', וע\"ד המבו' במ\"א בענין ההפלאה דאוא\"ס שמופלא מן הגילוים (והו\"ע ידיעת השלילה כו'), דזה שייך בהאוא\"ס שבבחי' שייכות עכ\"פ אל הגילוים, אבל מה שאינו בבחי' שייכות כלל הרי אינו שייך לומר כלל שהוא מופלא מן הגילוי כו', וכמו\"כ הוא בענין ההעתקה דדוקא כאשר העצמות בא בבחי' כתר ועתיק שייך לומר בו ענין ההעתקה כו'. אבל סכ\"ס ה\"ה בבחי' העתקה לגמרי מהנאצלים כו', ובחי' אריך מאחר שזהו בבחי' מקור לנאצלים ונודע ומורגש בעצמו ובנאצלים כו', ה\"ז באין ערוך דבחי' עתיק כו'. ועוד זאת דגם לגבי הנאצלים הרי בחי' אריך עם היותו מקורם א\"ז ממהותם כו', דהרי הנאצלים עיקרם הוא בחי' חכ' (דגם המדות\nדאצי' הן דוקא המדות שע\"פ החכ' כו'), ובחי' אריך ה\"ז בחי' הרצון שלמע' מהחכ' כו', הרי א\"ז ממהות הנאצלים כו'. ואיך יהי' זה בבחי' ממוצע ושיהי' עי\"ז חבור ושייכות הנאצלים אל העצמות כו', מאחר דבחי' העליונה הוא בחי' עצמות שבבחי' הבדלה לגמרי מהנאצלים, ומדרי' התחתונה הוא באין ערוך לגבי המדרי' העליונה והיא גופא ג\"כ אינו ממהות הנאצלים כו'. אלא מוכרח לומר דמה שהכתר נק' ממוצע היינו דאותה מדרי' עצמה שנק' בחי' אחרונה שבעצמות הוא עצמו שנעשה כתר לנאצלים כו' והיא ממהות הנאצלים כו', וזה אא\"ל בב' מדרי' שבכתר בחי' עתיק ואריך דבחי' עתיק מובדל בערך ואינו יורד מעולם להיות בבחי' מקור כו', ובחי' אריך שנעשה מקור לנאצלים א\"ז בחי' ומדרי' עתיק כו' (וג\"ז אינו ממהות הנאצלים ואיך יהי' עי\"ז חבור הנ\"ל כנ\"ל). וא\"כ צ\"ל בהכרח דעיקר הממוצע הוא בחי' ח\"ס, דבכללותו הוא בחי' חכ' והיינו שזהו כמהות הנאצלים שהן בחי' חכ' כו', רק דבחי' ח\"ס ה\"ז למע' מע' מבחי' חכ' דאצי' וכמא' אנת הוא חכים ולא בחכ' ידיעא כו', דחכ' דאצי' נק' חכ' ידיעא\nלהיותה בבחי' מהות ומדרי' החכ' כו', משא\"כ בחי' ח\"ס היא לא ידיעא שאינה בבחי' מהות חכ' עדיין כו' עד שהיא למע' מן החכ' לגבי החכ' וכמא' שתוק כך עלה"],[3601330578,"במח' כו' וכמשנת\"ל בכ\"ד, רק שהיא בבחי' מקור לחכ' וכמו כח המשכיל שהוא מקור השכל ואינו בבחי' מהות שכלי כו' וכך ח\"ס היא רק בחי' מקור לחכ' כו', ועם היותה בחי' מקור לנאצלים הנה לפעמים עולה ונכלל בבחי' עצמות ואינו נמנה עם הע\"ס (ואז הדעת נמנה שהוא הממשיך מבחי' העצמות דמו\"ס כו'), ולפעמים יורד למטה להיות מקור וכתר לנאצלים כו', ופי' שעולה ונכלל היינו דהעצמות שלו הוא כמו העצמות והוא שיש בו מבחי' העצמות ממש כמשי\"ת דמשו\"ז אינו נמנה עם הספי' כו', ובחי' חיצוני' שבו הוא בבחי' מקור לנאצלים כו', ולכך נק' ממוצע שיש בו מבחי' העליון והתחתון דהיינו דפנימי' שבו עולה למע' (והיינו שזהו בחינת העצמות שבו כו'), וחיצוני' שבו יורד למטה שנעשה בחי' מקור כו', והוא עצמו כולל ב' המדרי' כו', והיינו דח\"ס עצמה היא מדרי' בפ\"ע שאינו העליון והתחתון שא\"ז בחי' העצמו' (דעצמות אינו בגדר חכ' כו') ולא בחי' הנאצלים, וכולל ב' המדרי' שיש בו מבחי' העצמיות ממש והוא הפנימי' שבו ויש בו מהתחתון היינו בחי' החיצוני' שלו שנעשה מקור כו', וכללותו\nהוא בחי' חכ' ועי\"ז יהי' החבור כו'. ולפ\"ז מובן כללות הענין איך שע\"י הממוצע יהי' חבור ושייכות הנאצלים אל העצמות שהן באין ערוך לגמרי כו', והיינו שהשייכות שלהם הוא בבחי' העצמות שבממוצע, דע\"ה שזהו בחי' העצמות ממש ה\"ז כמו שבא בבחי' חכ' כו', דבחי' ומדרי' זו היא ג\"כ אינו כלל בבחי' מקור לנאצלים רק בחי' החיצוני' כו', מ\"מ מאחר שבכללות ה\"ז בחי' החכ' (שזהו כמהות הנאצלים כו') והחיצוני' מזה נעשה בבחי' מקור לנאצלים ע\"כ יש לנאצלים שייכות גם לבחי' העצמות שבהממוצע כו', ועי\"ז יכולים לבוא גם לבחי' עצמות המאציל כו'.\n<span data-k=\"ks\"><b>קיצור.</b> אמנם בחי' עתיק הגם שזהו העתקת העצמית ולא כמו העצמית ממש, מ\"מ ה\"ז בבחי' העתקה והבדלה לגמרי מן הנאצלים (ובעצמות אינו שייך גם הבדלה), ואינו נמנה עמהם, ואריך הוא מקור הנאצלים ונמנה עמהם, שהן עצמן מובדלים זמ\"ז, וגם אריך בעצם מהותו אינו ממהות הנאצלים, ואיך יהי' עי\"ז שייכות הנאצלים אל העצמות, ובהכרח שהממוצע הוא מדרי' שאינו העליון והתחתון, ויש בו מן העליון ממש ומן התחתון ממש, ולפעמים נמנה עמהם ולפעמים אינו נמנה, והוא בחי' ח\"ס שזהו חכ' כמהות הנאצלים ומובדל מחכ' דאצי', ופנימיותו הוא בחי' העצמות שבא בבחי' חכ', ולכן לפעמים עולה ואינו נמנה ולפעמים יורד בבחי' חיצוניות שבו להיות מקור לנאצלים ונמנה עמהם, וע\"י שייכות הנאצלים אל העצמות שבהממוצע שהוא מ\"מ בחי' חכ' יש להם שייכות אל העצמות ממש.</span>\nקצז) <b>וביאור</b> הענין יובן בבחי' החכ' שיש בכח החכ' ב' הפכים, הא' הו\"ע ההפלאה והוא כח ההעלאה בעילוי אחר עילוי בדקות השכל והעלם אחר העלם עד שנפלא מכל השגה ורעיון לגמרי כו', והב' הוא ההיפך מזה והוא כח הירידה וההמשכה מן ההעלם לגילוי עד למטה מטה כו'. ויובן זה בכמה אופנים, והוא שכח ההפלאה הוא כח ההפשטה להפשיט כל ענין שכלי מלבושי השגה ולהגיע לעומקו ופנימיותו ביותר כמו שהוא בתכלית הדקות עד שאינו נתפס בכלי השגה, והיינו לפי שאינו מוגבל ומצוייר באיזה הגבלה מצד עוצם דקות הענין עד שאא\"ל"],[3601330579,"בבחי' תפיסא ממש כו', וכידוע דכל תפיסת ענין שכלי הוא ע\"י הגבלת הענין שהן הקצוות שבו כו', ודקות הענין ביותר שאינו בבחי' ציור והגבלה ע\"כ אינו בבחי' תפיסא בכלי ההשגה כו' (ואין הכוונה שאינו בבחי' תפיסא כלל דכח החכ' בכ\"מ הוא בבחי' תפיסא במקצת עכ\"פ רק שאינו בבחי' תפיסא ממש בכלי להיות בבחי' השגה כו'). וזה אינו שבא דוקא לאחר ההתלבשות דהיינו שלאחר שיודע את הענין בלבושי ההשגה ה\"ה מפשיט כו', כ\"א שבתחלה תופס כל ענין בבחי' הפשטה ועולה ומטפס בהענין ומעמיק בו ביותר בעילוי אחר עילוי כו', דאז לבד העילוי שבזה בהפשטת הענין (שזהו רק דקות הענין שמופשט מהגשמה), יש בזה העילוי בעצם הענין שיודע את השכלי באו\"א לגמרי כי הוא תופס בעצם הענין שהוא באו\"א לגמרי מכמו שהוא בהשגה כו' (ועמשנת\"ל פצ\"ז). דהנה ע\"י הפשטת לבושי השגה הוא רק שבא אל דקות הענין, וכמו בכל ענין שכלי יש השגה מגושמת והשגה בדקות, כמו\"כ בההפשטה אחר ההלבשה ה\"ה בא אל דקות הענין והוא הפשטת ההגשמה לבד כו', אבל כשתופס הענין בתחלה בדרך הפשטה ה\"ה תופס את הענין\nבאו\"א לגמרי כו', ויש לפעמים שגם בההפשטה שאחר ההלבשה ה\"ה בא ע\"ז שהענין הוא באו\"א מכמו שהי' תחלה בהשגתו כו', אך העיקר הוא כשהתפיסא בתחלה הוא בדרך הפשטה כו'. והב' הוא כח הירידה להלביש כל ענין בלבושי השגה שיהי' נראה ונגלה ומובן לכל כו' (והעיקר הוא בבחי' האורך שהוא המשכת והתגלות עצם הענין שבא במדידה והגבלה ומתלבש בלבוש אחר לבוש שבזה הוא יורד ומתגלה ממדרי' למדרי' כו'), ובד\"כ הוא בחי' חיצוני' הענין מה שאפשר לבא לידי השגה כו', אמנם זהו חיצוני' העצמות שה\"ז עצם הענין שיורד ונמשך רק שהוא החיצוני' שבו מה שיכול להיות בהשגה כו', והחיצוני' הוא לפי אופן הפנימי' דכפי שמגיע בכח ההפלאה שבו בפנימי' ועצמו' הענין לפי אופן זה הוא החיצוני' והירידה ממדרי' למדרי' כו', וכמ\"ש במ\"א בענין ההשפעה דכפי אופן כח חכמתו בעצם הוא מראה כחו בההשפעה כו', דהרי שכל הרב בעצם הוא למע' באין ערוך לגבי התלמיד, וכמו שיודע הענין לעצמו א\"א לבא אל המקבל כ\"א בחי' חיצוני' לבד כו', ומ\"מ החיצוני' הוא לפי אופן הפנימי' דמי שהוא חכם גדול ביותר\nבעצם כח חכמתו גם השכליים שמגלים המה עמוקים ונעלים ביותר כו', וכמו\"כ לפי אופן שמגיע בעצם הענין בכח ההפשטה כ\"ה בחי' החיצוני' שבא בהתלבשות כו'. ועצם הענין יכול לבא ג\"כ בהתלבשות, אבל בלבוש שמתעלם ומסתיר בו וכמו במשל וחידה כו' (וזהו דוקא כשבא אל עצם הענין, דכאשר ידיעתו הוא רק בבחי' חיצוני' לבד א\"א לו להעלימו בלבושים כנ\"ל כ\"א בלבושים המגלים את השכלי כו', רק כאשר יודע עצם השכלי אז דוקא ביכולתו להעלימו כו', דכאשר יודע רק חיצוני' הענין אינו יכול להביאו במשל וכה\"ג כי לא יהי' מכוון רק דוקא כאשר יודע עצם הענין יוכל להלבישו במשל כו' כידוע ומבו' במ\"א, וזהו ג\"כ כח ההפלאה וכח הירידה שהן בערך זל\"ז דכאשר העלי' שלו הוא רק בהחיצוני' הירידה הוא רק בלבוש המגלה וכאשר מגיע אל העצם יוכל להורידו בלבוש המעלים כו'). ועוד יובן זאת ע\"ד ב' הענינים דחריף ומקשה ומתון ומסיק, דחריף ומקשה הוא שמעלים אור השכל בכמה העלמות והסתרים ע\"י הקושיות וסתירות כו', וכאשר מתרץ ומסיר את העלם יקשה עוד ויעלים ביותר כו', דכ\"ז הוא שבא לעומק הענין ביותר, דלבד זאת מה שע\"י הקושיות וסתירות מתגלה עומק הענין הנה סבת הדבר מה שהוא חריף"],[3601330580,"ומקשה הוא מפני שנכנס לעומקו של הדבר כו', וכידוע דכל ענין שכלי בשטחיותו הוא מובן ומושג וכאשר יעיין יותר בהענין יראה איך שאינו מושג עדייין, וכל מה שיעמיק יותר שיגיע יותר לעומקו יותר הוא מוקשה ההבנה עד אשר יבא ויגלה את אור האמת לעומקו כו', הרי שסבת ההעלם הזה שע\"י קושיות המעלימים זהו ג\"כ ע\"י שבא לעומקו דוקא כו'. ומתון ומסיק הוא להביא כל אור שכל ולהורידו ולהמשיכו בבחי' או\"י דוקא כו', והן ב' כחות נבדלות דחריף ומקשה הוא שחוש שכלו הוא בבחי' או\"ח דוקא להעלים ביותר (געפינען די ניט רעכטקייט), וע\"ה שבזה מגיע אל העומק יותר אבל אינו בא בהתגלות (דגם בעצמו אינו יודע אמיתית הענין איך שהוא כו'), דזה שהוא רק בהחוש דחריף ומקשה הגם שמגיע לעומק הענין (דהיינו שקבלתו בכל ענין אינו מקבל אותו כמו שהוא בשטחיותו כ\"א שנכנס תיכף בעומק הענין), הרי מ\"מ אין העומק מובן אצלו שהרי מקשה על זה, וכמו\"כ העומק הבא ע\"י הקושיות אינו אצלו בהתגלות כי הוא בלתי מסודר בהענינים ומסתבך בהם כו'. ומתון ומסיק הוא שכל ענינו הוא למצוא הנחת\nהענין (די רעכטקייט) ואינו מגיע לעומקו כ\"כ, אבל מה שיודע ה\"ה יודע ומשיג בטוב כו'. והן ב' קוין בבחי' החכ' שמובדלים זמ\"ז כו', אבל אמיתית החכ' הוא כשיש ב' הקוים (והו\"ע קו האמצעי הכולל שניהם) והיינו שיש בו כח האו\"ח שמגיע בזה לעומק הענין ביותר, והוא ג\"כ מתון ומסיק והיינו שע\"י הקושיות והסתירות מאיר אצלו עומק הענין (והיינו דע\"י התכללות ב' הכחות הסתירות גופא הן באופן כזה שהן בס' והדרגה ואינו מסתבך בהענין כו', ואדרבה שבהם וע\"י מאיר אצלו עומק הענין כו') ומביאו מן ההעלם אל הגילוי כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ויקדים שבחכ' יש כח ההפלאה והעלי' בהעאה\"ע וכח הירידה, והוא חוש ההפשטה שתופס בתחלה בעצם הענין ועולה בפנימיותו ועומקו ביותר שלמעלה מתפיסת השגה, ויכול להיות גם לאחר ההשגה בהתלבשות, וכח הירידה הוא בחיצוניות העצמיות להלבישו ולהביאו למטה מטה, וחכם הוא שיש בו שניהם, ולפ\"ע כחו בהפשטה כן כחו רב בהלבשה, וגם עצם הענין יוכל לבוא בלבוש, גם כענין חריף ומקשה שזהו מפני שתופס בעומק הענין והולך ועולה בעומקו בבחי' או\"ח, ומתון ומסיק הוא חוש הירידה באו\"י, ואינו בעומק כ\"כ, אבל הענין ברור, וצ\"ל שניהם, ועי\"ז מאיר ומתגלה עומק הענין.</span>\nקצח) <b>והנה</b> ב' הכחות שבחכ' הגם שהם הפכים זמ\"ז הנה באמת הן תלוים זב\"ז, דמי שיש בו רק כח ההפלאה או רק כח הירידה א\"ז אמיתית החכ' כו', דכאשר חסר כח הירידה ה\"ה חסר בכח הזה וגם כח ההפלאה אינו בשלמות, וכנ\"ל דחריף ומקשה לבד ה\"ה בלתי מסודר בהענינים וגם לעצמו אינו יודע אמיתית הדבר כו', והחסר כח ההפלאה אין בו חוש ההעמקה וממילא לא יוכל לירד בהענין כ\"כ כו'. ואמיתית החכ' היא שיהיו בו ב' הכחות וכח הירידה הוא לפ\"ע כח ההפלאה כו', דלפ\"ע כח ההפלאה שמגיע בעומק השכל ביותר למע' מכמו שהוא מושג כו', כמו\"כ הוא כח הירידה שיוכל להמשיך ולירד עד למטה מטה ביותר, וכידוע דכח הירידה בשכל להביא כל אור שכל בבחי' השפעה אל הזולת זהו דוקא ע\"י שיודע את אור השכל בעומקו ופנימיותו יותר וגם צריך לשנות את השכל מכמו"],[3601330581,"שהוא אצלו כו', ועוד צריך להמציא לזה ענינים חדשים במה להביא את השכל שזהו דוקא כאשר יש לו כח המוליד בשכלו להמציא שכלים חדשים ממקור השכל כו', וממקור השכל ה\"ז בא מעומק יותר מהמצאת השכל בתחלה כו', וגם את השכל הזה צריך להעלותו למקור השכל היינו כמו שהשכילו תחלה ואז דוקא יוכל לשנותו וגם להמציא ענינים במה להביאו ולגלותו כו' וכמשנת\"ל פק\"ע. וכמו\"כ כח ההתחלקות להביא את האור שכל בחלקים רבים זהו דוקא כאשר בא לעומק המושג דאותו שכל כו', דכאשר מגיע לעומקו ופשיטותו יוכל לחלקו לכמה חלקים כו', דאם ידיעתו בו הוא רק בחיצוני' ה\"ה מצומצם מאד בהענין ודי לו רק כפי שיודע אותו ואינו יכול להביאו בכמה פרטים. כ\"א דוקא כשמגיע לעומקו ופנימיותו (דשם הוא בבחי' פשיטות כו') אז יכול להביאו בריבוי התחלקות פרטים ובריבוי ענינים עד אין שיעור כו', וע\"ה דבריבוי ההתחלקות וההתפשטות אינו בא בזה בחי' עומק השכל בהתגלות (כ\"א מה שנמצא בהעלם בחלקי פרטי השכל כו') דמה שמתגלה הוא השגת השכל שזהו בחי' חיצוני' בכלל כו', מ\"מ זהו דוקא כאשר בעצמו\nהוא מגיע לעומק השכל בהענין כו', וגם באור השכל המושג צריך להעלותו למקור השכל כמו שהשכיל אותו בתחלה שזהו הכח או\"ח להעלות ולקרב את השכל למקורו כמו שהמציא אותו בתחלה ועוד לעומק מקור השכל יותר מכמו שהי' תחלה בבחי' או\"י כו', עי\"ז דוקא הוא כח ההתפשטות וההתחלקות בריבוי פרטים ביותר כו'. וה\"ז עד\"מ הכיווץ וההתפשטות בכח היד הרי לפ\"ע כח הכיווץ בעצמו שהו\"ע אסיפת הכח בעצמו לפ\"ע זה הוא כח ההתפשטות, וכמו כחו בהגבהת המשא כן כחו להניע המשא מידו כו', וכמ\"ש במ\"א בענין כ\"ף כפופה וכ\"ף פשוטה דהכל ענין א', דכ\"ף כפופה הו\"ע הכיווץ והסתימה דהעלם אחר העלם כו' הוא עצמו כ\"ף פשוטה להתפשט למטה ביותר (והוא בבחי' הכתר כו') דלפ\"ע עומק רום הוא בחי' עומק תחת כו', וכ\"ה בקמ\"ץ ופת\"ח דסתימות שבחכ' הוא בקמ\"ץ ופתיחת החכ' מהעלמו לגילוי הוא בפת\"ח דלפ\"ע הסתימות הוא הפתיחה והגילוי כו',\n<span data-k=\"ks\"><b>קיצור.</b> וב' הכחות תלוים זב\"ז, דכשחסר כח הירידה אין שלימות גם בכח ההפלאה שאין הענין ברור, והירידה והתפשטות השכל וכן התחלקות הפרטים הוא דוקא בידיעת עומק השכל ביותר שזהו בכח ההפלאה, וכמו כ\"ף כפופה הוא כ\"ף פשוטה, וכמו קמץ ופתח דהא בהא תליא.</span>\nקצט) <b>ויובן</b> זה יותר עד\"מ התלמיד היושב לפני רבו דנעשה כנקודה א' לקבל, דלפ\"ע הכח שמצמצם כל עצמי' שלו בבחי' כיווץ בתכלית בלתי יכול להיות ממנו בחי' התפשטות כלל דאיידי דטריד למבלע לא פליט כלל וכלל, מזה עצמו בא כח התפשטותו למטה אח\"כ להיות מקור נובע להשפיע ולהוליד השכלות חדשות כו', דכאשר שומע ומקבל בלי צמצום וכיווץ בעצמו ה\"ה מקבל את השכל אבל לא יוכל להתפשט בו ביותר כו', כ\"א ע\"י צמצום וכיווץ כל עצמותו ה\"ה מקבל את עצם השכלי (ועמשנת\"ל פקל\"ט) ועי\"ז נעשה כמקור נובע בהענין להשכיל ולהתפשט בו ביותר כו'. וזהו כמו ענין ההפלאה שנת\"ל פקצ\"ז מה שעולה בעילוי אחר עילוי בהענין כו', וכמו\"כ יובן באופן הב' שנת\"ל שם שזהו כמו העומד על דבר שכל וסברא ומתעכב בה ומעמיק בה בכל כח שכלו עד שיהי' לו בזה כמה"],[3601330582,"קושיות ותירוצים הנק' פלפול שזהו העלם אחר העלם שאחר שמתרץ חוזר ומקשה וכל שמגיע לעומקו יותר ה\"ה מופלא ואינו מתיישב כו', ואז דוקא רווחא לי' שמעתתא אח\"כ שישכיל בה סברות חדשות רבות עד אין שיעור למטה כו', דאם הי' מקבל את השכל בחיצוניותו לבד הי' הגבלה בההתפשטות כו', רק דוקא ע\"י ההעלם הקודם שמגיע לעומק השכל (והיינו שע\"י ההעלם מגיע לעומקו ביותר והיינו שמגיע עי\"ז לבחי' עומק שהוא בבחי' אור חדש כו') תהי' ההתפשטות בבחי' בל\"ג כו'. ונמצא מובן מכ\"ז דבחי' כח ההפלאה והירידה הגם שהן הפכים זמ\"ז מ\"מ ה\"ז הא בהא תלי' שע\"י ההפלאה דוקא עי\"ז הוא דוקא הירידה, והירידה הוא לפי אופן ההפלאה, דהגם שאינו מתגלה האור המופלא דהיינו בחי' העומק כו', מ\"מ לפי אופן ההפלאה כמה שמגיע בזה בעומק ובהפלאת הענין ביותר לפי אופן כזה הוא בחי' הירידה וההתפשטות כו' (ובהכרח שיש בזה גם מהאור המופלא מאחר שעי\"ז הוא דוקא הירידה וההתפשטות כו'). וי\"ל דזהו בחי' כח ומ\"ה שבחכ' דכח שבחכ' הוא בחי' התקרבותה אל הבינה ובחי' מ\"ה הוא התדבקותה בכתר כו',\nוידוע דחכ' הוא בחי' נקודה, ויש בזה ב' מדרי' הא' מה שיסו\"א הוא בחי' נקודה שזהו ההשפעה אל הבינה וכמו נקודת ההשכלה כו', והב' בחי' חכ' שבחכ' או כתר שבחכ' שהיא בבחי' נקודה דאזעירת גרמא לקבל מבחי' הכתר כו'. וזהו בחי' פלא שבחכ' בעלותה לקבל מבחי' הכתר שכל שהעלי' היא ביותר עי\"ז הוא ההמשכה והירידה ביותר כו', וכמו משה שהי' בחי' החכ' הרי הי' כבד פה לגבי תושבע\"פ כו', ובמ\"ת דוקא נתרפא וכמ\"ש במד\"ר ע\"פ אלה הדברים, דלפי שאז הי' בבחי' הביטול ביותר שעלה אל האלקים בחי' העלם העצמי כו' וכמ\"ש במ\"א, עי\"ז דוקא נתרפא להיות בבחי' ירידה והמשכה כו'.\n<b>ועפ\"ז</b> יובן מ\"ש שיר המעלות ממעמקים שתקנו לומר זה בעשי\"ת, דהנה בר\"ה הוא בנין המל', וידוע דמל' הוא בחי' הגילוי, דהט\"ס שלמע' מהמל' הן בבחי' עלי' למע' וכמו טבע העלול להדבק בעלתו, והתגלות האצי' הוא בחי' המל', וכן בכל ספי' ההתגלות שלה הוא בחי' המל' כו', ובכדי להיות הגילוי צ\"ל שרש ההמשכה ממדרי' גבוה יותר וכמשנת\"ל דכח הירידה הוא לפ\"ע כח ההפלאה דוקא כו'. וזהו דבר\"ה ועשי\"ת עיקר העבודה הוא בבחי' העצמות דנפש דוקא, דבכל השנה עיקר העבודה במוח ולב, משא\"כ בר\"ה ועשי\"ת עיקר העבודה היא בעצמות הנשמה שעי\"ז מגיע בבחי' עצמות א\"ס שעי\"ז ממשיכים בחי' המל' להיות בחי' הגילוי כו', ובפרט שהכוונה בהמשכת המל' בר\"ה הוא להיות גילוי המלוכה למטה דצ\"ל ההמשכה מבחי' פנימי' ועצמות א\"ס כו'. וזהו ג\"כ ענין המל' בר\"ה שעולה בבחי' העצמות שז\"ע המלך הקדוש כו' שזהו בכדי להמשיך בחי' גילוי המלוכה כו'. והנה בעשי\"ת נבנה בחי' המל' בע\"ס פרטי' והיינו פרטי ההתחלקות דכ\"ז הוא ע\"י ההמשכה מבחי' העומק דוקא כו', וז\"ש שיר המעלות ממעמקים\nבר\"ה ועשי\"ת דבר\"ה הוא המשכת המל' דהיינו בחי' ההתגלות וההתפשטות בכלל ובעשי\"ת שהוא בחי' התגלות הפרטי' כו', כ\"ז הוא ע\"י העבודה בבחי' עומק ופנימי' הנפש שמגיע בבחי' עצמות א\"ס ב\"ה, וכמ\"ש לך אמר לבי בקשו פני בחי' פנימי' הלב ועי\"ז את פניך ה' אבקש כו'. וזהו ג\"כ ההפרש בין בכל לבי דרשתיך לממעמקים קראתיך, דבכל לבי הוא העבודה דמוח ולב וכמו בכל לבבך כו', אבל ממעמקים הוא העבודה"],[3601330583,"בעצמות הנשמה כו'. ועז\"א בזהר דזמינין כל בני עלמא למימר דא דהעבודה דמצ\"ע הנשמה יכולים כולם לבא לזה והוא בכולם בשוה וכמ\"ש ויהי בישורון מלך דהיינו בחי' המשכת המלוכה דר\"ה כו' בהתאסף כו' יחד שבטי ישראל כו', דהנה ההתחלקות הוא מבחי' החכ' ולמטה דאין דעותיהן שוות כו', וע\"כ יש חילוקים בהעבודה דמוח ולב שזה משיג כך וזה משיג כך ממילא יש חילוקים בהעבודה, אבל בהעלאת מ\"ן דבחי' פנימי' ועומק הנפש כולם שוין וכמ\"ש בסש\"ב דהנפשות מתאימות המה והכל יכולים לבא לזה כו', וזהו משום דתפלה צ\"ל מעומקא דלבא ע\"כ כל בני עלמא זמינין למימר דא כו'. וזהו שיר המעלות ממעמקים שאו' זה בעשי\"ת להמשיך מבחי' עצמות א\"ס ב\"ה להיות המשכת המל' כו', ואומר שיר המעלות סתם דזמינין כל בני עלמא כו' להיות שזה שוה בכל ישראל שע\"י העבודה בעומק הלב בר\"ה ועשי\"ת ממשיכים גילוי המלוכה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וכמו תלמיד לפני רבו כל שהוא בכיווץ ביותר שמקבל עצם השכל ה\"ה אח\"כ מקור נובע להשכיל ולהשפיע, וכן ע\"י הפלפול דוקא רווחא שמעתתא, וי\"ל שזהו בחי' כח ומ\"ה דחכ', חשב\"ח או כשב\"ח, ויסוד שבחכ', וכמו משה במ\"ת דוקא נתרפא בדבור. ובזה יובן מ\"ש ממעמקים קראתיך דבנין המל' הוא מבחי' העומק דא\"ס שזהו ע\"י עבודה העצמיות דר\"ה ועשי\"ת.</span>"],[3601330584,"<h3>בס\"ד. ש\"ת, תרד\"ע</h3>\n<b>דרשו</b> הוי' בהמצאו קראוהו בהיותו קרוב, ואי' בגמ' כתי' מי כה' אלקינו בכל קראינו אליו דמשמע תמיד בכל קראינו כו' וכתי' דרשו ה' בהמצאו בזמן שהוא מצוי, ל\"ק כאן בצבור כאן ביחיד ויחיד אימתי בעשרה ימים שבין ר\"ה ליוהכ\"פ, והוא לפי שאז הוא זמן רצון ומאיר גילוי אוא\"ס וה\"ה נמצא כבי' לדורשיו גם ליחיד כו'. וצ\"ל והלא ע\"פ בכל קראינו אליו אי' בספרי אליו ולא למדותיו, וידוע הפי' דמדותיו הן ע\"ס דאצי' ואליו הוא בחי' עצמות אוא\"ס שלמע' מהשתל' ע\"ס וה\"ז ג\"כ בחי' רצון כו', ומפני מה זהו רק לציבור, דלכאורה מצד בחי' ומדרי' זו הי' ג\"כ צ\"ל צבור ויחיד שוין כו', ואיזהו גילוי הוא בעשי\"ת שאז דוקא גם ליחיד כו'. ובירושלמי אי' דרשו ה' בהמצאו היכן הוא מצוי בבכנ\"ס ובמד\"ר, וצ\"ל מה מוסיף ומחדש הירושלמי על דרש הגמ' הנ\"ל. ולהבין כ\"ז ילה\"ק משנת\"ל דבחכ' יש ב' ענינים כח ההפלאה וכח הירידה ועם היותם הפכים זמ\"ז מ\"מ צ\"ל ב' הכחות והם תלוים זב\"ז, דבאם חסר כח הירידה הרי לבד זאת שחסר כח הבאת והמשכת השכל גם כח ההפלאה אינו בשלמות כלל\nוכמו חריף ומקשה לבד שהוא מסתבך בהענינים ואין אור השכל בהתגלות כו', וכאשר חסר כח ההפלאה ה\"ה חסר חוש ההעמקה וממילא חסר ג\"כ כח הירידה שאינו יכול להביא את אור השכל למטה מטה כו', כי לפי אופן כח ההפלאה דוקא לפי אופן כזה הוא כח הירידה כו'."],[3601330585,"<b>רי\"ש)</b> והנה כשם דבחכ' יש ב' מדרי' כח ההפלאה וכח הירידה דלפי אופן ההפלאה והעלי' בבחי' העצמות לפי אופן כזה הוא בחי' ההמשכה והירידה כו', וע\"ה שאין העצמות יורד ונמשך ומ\"מ ההמשכה היא לפי אופן ההעלאה בבחי' העצמות והעומק כו' כנ\"ל, כמו\"כ יובן בבחי' מו\"ס שיש בזה ג\"כ ב' מדרי', דע\"ה דבד\"כ מה שנק' סתימאה היינו שזהו בבחי' סתימות והעלם שלמע' מבחי' גילוי כו', מ\"מ הרי ח\"ס הוא בחי' מקור לחכ' הגלוי' וא\"כ ה\"ז שייך לבחי' הגילוי עכ\"פ, ויש בזה מה שסתום ונעלם לגמרי מבחי' גילוי כו', רק להיות דבד\"כ זהו מה שסתום ונעלם ממילא ב' המדרי' שבזה הן באופן אחר מכמו בבחי' חכ' הגלוי' כו'. והענין הוא דהנה בזהר ובע\"ח משמע דגילוי פנימי דעתיק הוא בח\"ס דוקא ובגולגלתא בחי' עתיק הוא בבחי' או\"מ לבד והוא רק בחי' חיצוני' עתיק כו', דבח\"ס מאיר בחי' פנימי' עתיק ובבחי' פנימי' ובגולגלתא מאיר רק חיצוני' עתיק ובבחי' מקיף לבד כו', ולכן גולגלתא היא בחי' חיצוני' הכתר וח\"ס פנימי' הכתר כו'. דהנה באדר\"ז דרפ\"ח סע\"ב אי' תיקונא דעתיקא\nקדישא אתתקן בתיקונא חד כללא דכל תיקונין והיא חכמה עילאה סתימאה כו', והאי איקרי עדן עילאה סתימאה והוא מוחא דעתיקא קדישא כו', הרי שבחי' מו\"ס הוא גילוי והתלבשות עתיק ממש, דמאחר דכללות תיקוני עתיקא הוא בחי' מו\"ס מובן מזה דבחי' עתיק הוא במו\"ס בבחי' התלבשות פנימי כו', ונק' מוחא דעתיקא הרי שזהו בחי' פנימי' עתיק כו'. ובע\"ח שכ\"ב ספ\"ו כ' דכתר הוא בחי' אור רוחני מקיף עליו כו', וחיצוניותו הוא בחי' גולגלתא כו', דעיקר הכתר הוא למע' מגולגלתא, וכמו עד\"מ למטה הכתר הוא העטרה שע\"ג הראש שנעשה מאב\"ט ונבדל הוא מן האדם, דהרי הגולגולת הוא מכלל האדם רק שהוא עצם ואינו בהתחלקות כ\"כ וע\"כ ציור אדם הוא מפרצוף פנים כו', אבל גם עצם הגולגולת הוא מגוף האדם והוא כלי שעליו שורה הרצון כו', והכתר הוא דבר נבדל מן האדם כו', ולמעל' היינו בחי' עתיק שנעתק ונבדל מהשתל' הוא עיקר הכתר כו', ומאיר בגולגלתא רק חיצוניותו ובבחי' מקיף לבד ובח\"ס מאיר בחי' עתיק בבחי' פנימי' ממש כו'. והענין הוא דהנה עד\"מ למטה גילוי התענוג הוא ברצון ובחכ'\nוהיינו כשממלאים רצונו של אדם, אף שהרצון אין בו טעם ושכל כלל רק שלזה יחפוץ בלא טעם, ומ\"מ הרי מקבל הוא נח\"ר על שנעשה רצונו שהנח\"ר הוא העונג המאיר בהרצון כשנשלם רצונו וחפצו כו', ויש בחי' עונג המלובש בשכל וחכ' אף שאין לו שייכות כלל אל הרצון, היינו שאינו שכל המחייב את הרצון כ\"א השכלה שמשכיל באיזה חכ' נפלאה ה\"ה משתעשע בה בשעשוע ועונג נפלא כו', וכמו צהבו פניו של ר\"א שמצא תוספתא חדתא שכאשר משכיל השכלה חדשה ה\"ה מתמלא עונג כו', הרי שיש עונג ברצון וגם בחכ' רק שברצון הוא בבחי' מקיף ובחכ' הוא בבחי' פנימי כו'. וההוראה ע\"ז דברצון אין העונג מוסיף חיות דע\"ה שמתענג כשממלאים רצונו מ\"מ אינו מתחדש מזה שום דבר בהרצון, וכנראה בחוש שהעונג הוא בבחי' הבדלה בהרצון כו', משא\"כ בחכ' הרי העונג שבזה נותן חיות בהשכל דמשו\"ז יש לו חיות (גישמאק) בהענין שכלי כו', ולכן בשכל כשמתיישן לא יש בו חיות והיינו מפני שמתרחק מן העונג כידוע, וברצון אינו שייך שמתיישן כ\"א שמתעלם וכאשר חוזר מתעורר הוא בתוקף כו', וזהו מפני שבחכ' העונג הוא\nבבחי' חיות פנימי כו', וה\"ז הוראה דברצון העונג הוא בבחי' מקיף לבד ובחכ' הוא בבחי' פנימי כו'. והטעם וסבת הדבר ע\"פ פשוט הוא לפי שהרצון הוא בחי' או\"מ ע\"כ גם"],[3601330586,"העונג שבזה הוא בבחי' מקיף, והחכ' להיות או\"פ ע\"כ גם העונג הוא בבחי' פנימי כו'. וזהו ג\"כ מה שברצון הוא רק חיצוני' התענוג ובחכ' מאיר פנימי' התענוג, לפי שכל או\"מ הוא בחי' חיצוני' וכל או\"פ הוא בחי' פנימי' כו' כנודע (והיינו בכל מדרי' כמו שהיא לפ\"ע מדריגתה, דע\"ה דלכאורה מה שבא בהתלבשות ה\"ז הארה לבד והעצמי הוא בבחי' מקיף כו', מ\"מ בחי' הפנימי' הוא הארה פנימי' של המשפיע ובחי' המקיף הוא רק חיצוני' העליון כו', וכמו במשפיע ומקבל יש בחי' מקיף והוא מה שהמשפיע משער חושי המקבל ובאופן כזה הוא משפיע לו, הרי השערה הזאת אינו בעצם השכלתו כו' ומה שמשפיע לו הגם שזהו רק הארה ה\"ה מגוף השכלתו כו', ויש בבחי' או\"פ שפנימי' העליון ממש בא בהתלבשות כו' וכמשי\"ת), וע\"כ להיות שהרצון הוא מקיף וחכ' פנימי ע\"כ בהרצון הוא חיצוני' התענוג ובבחי' מקיף לבד ובחכ' הוא בחי' פנימי' התענוג ובבחי' או\"פ כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וכמו\"כ בח\"ס יש ב' מדרי' עם היותו סתום בכלל, דהנה באד\"ז דכללות תיקוני דעתיקא הוא במו\"ס, והיינו דעתיק הוא במו\"ס בבחי' התלבשות פנימי, והוא בחי' פנימיות עתיק, ובגולגלתא רק חיצוניות עתיק ובבחי' מקיף, דהנה כתר למעלה מהגולגלת ונבדל ממנו, וזהו בחי' עתיק, והנה התענוג הוא במילוי הרצון ובשכל, אך ברצון הוא בבחי' מקיף, ולכן אינו מוסיף בו חיות, ובחכ' הוא בבחי' פנימי שמוסיף חיות, והטעם מפני שהרצון הוא או\"מ וחכ' או\"פ כמו\"כ הוא הארת התענוג בהם, וכל או\"מ הוא חיצוניות ואו\"פ (גם הארה) היא פנימיות.</span>\n<b>רא)</b> אמנם י\"ל בזה, דהנה ידוע דהרצון הוא כח עצמי ממש כמו העונג דהרי אמיתית הרצון הוא דמה שרוצה הדבר הוא רק מצד העצם, דז\"ע שאין טעם לרצון היינו גם לא טעם ועונג כו', והיינו שאין העונג סבה אל הרצון כ\"א הרצון הוא מצ\"ע כו', ולכן יש רצון בלא תענוג וכמו רצון האב בבן ורצון הבן בהאב ה\"ז רצון עצמי שאין העונג סבה לזה, שהרי גם אם ח\"ו לא יש עונג וגם אם להיפך ר\"ל, מ\"מ ישנו להרצון בעצם, והיינו מפני שהוא רצון עצמי מעצם הנפש מפני שהוא עצמותו שאין שום סבה לזה כו'. וכמו\"כ הוא בדוגמא למע' רצון העצמי דהקב\"ה בנש\"י, וכמ\"ש אהבתי אתכם אמר הוי' בבחי' אה' עצמי' בנש\"י שהתקשר עצמו כבי' בנש\"י בלי שום טעם וסבה מחמת איזה עונג וכה\"ג רק מצד עצם הרצון, וכמ\"ש כי תהיו אתם ארץ חפץ וכתי' חפצי בה כו' וכמו רק אתכם ידעתי פי' רציתי כו'. וזהו ענין זכרונות דר\"ה וכמא' אמרו לפני זכרונות בכדי שיעלה זכרוניכם לפני לטובה כו', והוא להיות דבר\"ה הוא העלי' בבחי' רוממות העצמות דא\"ס וכמש\"א המלך הקדוש שהוא בבחי' קדוש ומובדל מצ\"ע כו',\nדאז כללות ההשתל' אינו תופס מקום כלל וכלל כו', וע\"כ צריכים זכרון עליהם כמו על דבר הנשכח, דבאמת הרי אין שכחה לפני כסא כבודך רק מחמת העדר תפיסת מקום כו', וזש\"א אתה זוכר מעשי עולם שזהו עולם הנאצל ועולם הנברא כו', ופוקד כל יצורי קדם שמקדם למע\"ב והן עולמות הא\"ס שלמע' מאצי' כו' שעל כולם צריכים הזכרון בר\"ה כו', ועל כל זה הוא נזכר כבי' ע\"י הזכרון דנש\"י, וכמש\"א וגם את נח באה' זכרת כו' ומסיימים זוכר הברית שהוא הכר\"ב דאברהם ומשה כו', ועי\"ז נזכר על כל מע\"ב כו'. וזש\"א זה היום תחלת מעשיך זכרון ליום ראשון, דפי' יום הראשון הוא ראשית"],[3601330587,"כל ההשתל' שעלה ברצונו הפשוט להאציל ולברוא כו', שהזכרון ע\"ז הוא בר\"ה שהוא יום תחלת מעשיך היינו יום בריאת אדה\"ר, דהרי בכ\"ה באלול נבה\"ע ור\"ה הוא יום ששי למע\"ב שבו נברא אדה\"ר שזהו תחלת מעשיך היינו עיקר הכוונה הפנימי' וע\"י הוא הזכרון על כל מע\"ב כו'. דהנה יש זכרון חיצוני וזכרון פנימי, שז\"ע זכרון הברית דנש\"י כו', והענין הוא דהנה ידוע בענין כר\"ב שהוא מה שמחלקים דבר א' לשני חצאין ועוברים ביניהם שזהו לסימן שהן דבר א', ועוד מורה הכר\"ב שגם אם יתרחקו זמ\"ז יהי' מ\"מ חבורם והתאחדותם בפנימי' נפשם ועי\"ז יתאחדו ויתחברו בחיצוני' כו'. והדוגמא מזה למע' דהתאחדות החיצוני הוא בכללות ס' השתל' שהן רק חיצוני' הרצון כו' (ובד\"כ זהו הכר\"ב דנח שהוא על קיום העולם התחתון בפרט וקיום כללות ההשתל' בכלל שמבחי' יחוד חיצוני דאו\"א כו'), והתאחדות הפנימי הוא ההתאחדות בנש\"י שהן פנימי' רצונו ית' כו' (וזהו הכר\"ב דאברהם אע\"ה על קיום התו\"מ שזה יהי' תופס מקום כו', והכר\"ב עם משה על התשו' שיעורר בבחי' פנימי' ועצמות א\"ס ב\"ה כו'), והזכרון\nהזה הוא שגם אם יתרחקו זמ\"ז כו', וכמו בתכלית העלי' והרוממות בבחי' העצמות דאז הריחוק גדול מאד שהרי כל ההשתל' אינם תופסים מקום כלל גם מדרי' היותר גבוהות כו', ובפרט נשמות שירדו למטה ונתלבשו בגופים שמרוחקים המה מאד מבחי' רוממות העצמות כו' (וביותר בזה\"ג בריבוי ההעלמות וההסתרים כו' והוא אם עוונותיכם היו מבדילים כו' שזהו הבדל וריחוק גדול מאד כו', ובאמת גם הריחוק הזה הוא רק בחיצוני' דהרי גם מחיצה של ברזל אינה מפסקת בין ישראל לאביהם שבשמים כו' והיינו בפנימי' כו', רק בחיצוני' הוא ההבדל והריחוק כו'), וע\"ז הוא זכרון הברית הפנימי שמזכירין לפניו כבי' איך שהתקשר עצמו כביכול בנש\"י בבחי' פנימי' שלהם (דמשו\"ז אינו נוגע כלל הריחוק החיצוני כו'), וע\"י זכרון הברית וההתאחדות הפנימי נעשה התאחדות החיצוני ג\"כ כו'. ומה שצריכים זכרון על ההתאחדות הפנימי הוא מפני שבהעלי' בעצם הרוממות הרי גם הנשמות אינם תופסים מקום כו', ומ\"מ אינו שייך בזה ריחוק ח\"ו רק שצריכים זכרון כו'. ובמה בשופר בבחי' צעקה פנימי' דתשו' וקבעומ\"ש בהזזת\nעצמי' נפשו שזה מגיע בבחי' עצמות א\"ס כו' וכמשנת\"ל ס\"פ קצ\"ה, ומביאים ע\"ז ראיות מן התו' וכמו הזכרון דנח דבאה' זכרת אותו שזהו מצד האה' פנימי' והעצמי' כו' (והראי' שלא העמיד ממנו מגינים וצדיקים כו'), (והגם דכר\"ב דנח הי' על קיום העולם כנ\"ל, י\"ל שהרי הזכרון הי' קודם הכר\"ב, והגם דהכר\"ב הי' על קיום העולם (וי\"ל משום דמנח לא העמיד מגינים צדיקים ומבו' במ\"א מפני שהי' קודם המילה לא נמשכו נשמות גבוהות, כי לא הי' יחוד זו\"נ בבחי' פנימיות, וצ\"ע ממ\"ש במ\"א בענין ומלכי צדק מלך שלם כו'), הנה הזכרון הי' על נח מצ\"ע והיינו מצד עצם מעלת נש\"י, וי\"ל דזהו שבמד\"ר העיר על מ\"ש ויזכור אלקי' מפסוק אדם ובהמה תושיע ה' ועמ\"ש במדרש אמור ר\"פ כ\"ז, וידוע דאדם ובהמה זהו שלמעלה מתו\"מ שהן בחי' אדם כו', והו\"ע התשובה וכמארז\"ל ערומים בדעת כאדם ומשימים עצמן כבהמה כו', ועז\"א וגם את נח באהבה זכרת מפני האהבה עצמיות כו'), והזכרון על האבות דרק באבותיך חשק ה' כו', שהרי בכל פעם שהזכיר משה זכות אבות הי' בהזמן שהי' שלא כדבעי כו' וכמ\"ש זכור\nלעבדיך לאברהם כו', והזכרון דיצי\"מ שהי' רק מצ\"ע מצד הרצון העצמי בנש\"י כו', ועי\"ז יהי' ממילא הזכרון על כל השתל' כו'. וכ\"ז הוא מפני שהרצון הוא עצמי"],[3601330588,"שאין שום סבה לזה כו', וכמו\"כ הוא הרצון העצמי דנש\"י באלקו' שהוא בהתקשרות עצמי בלי שום סבה וטעם כלל, וכמו במס\"נ בפו\"מ על קדה\"ש שאין בזה שום הרגש עונג כלל (שאם הי' בזה איזה הרגש עונג יכול להיות שלא הי' באפשרי להיות במס\"נ בפו\"מ, שהרי השכל אינו מחייב ענין המס\"נ והיינו שאינו מניח למסו\"נ בפו\"מ וכמו\"כ הוא גם בתענוג כו'), רק מצד הרצון העצמי דהיינו עצם ההתקשרות הנשמה באלקו' שא\"א לו כלל להיות נפרד ח\"ו עי\"ז הוא מוסר נפשו בפו\"מ ולא יכבד עליו לקבל כל היסורים ר\"ל רק מצד עצם התקשרותו כו', דכ\"ז הוא רצון בלא תענוג כו', וכמו המצות הנק' חוקים דבד\"כ הרי המצות הן בחי' רצון שלמע' מהטעם דאין טעם לרצון ולכן מצות לאו ליהנות ניתנו כו', ובפרט המצות שהן בבחי' חוקים כו', וכ\"ז הוא מפני שהרצון הוא עצמי שאין התענוג בבחי' סבה אליו כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ועיקר הטעם י\"ל דהנה רצון הוא עצמי בלי סיבת טעם ועונג, וכמו רצון העצמי דאב ובן, וכ\"ה רצון העצמי בנש\"י מצ\"ע, וז\"ע הזכרונות דר\"ה על כללות ההשתל' ע\"י הזכרון בנש\"י שהן תחלת מעשיך, והוא בחי' זכרון פנימי שעי\"ז הוא הזכרון חיצוני, וכמו כר\"ב שזהו התקשרות פנימי (והוא כר\"ב דאברהם על תו\"מ ומשה על התשובה), וגם אם יתרחקו, והוא בתכלית רוממות העצמית וירידת הנשמות למטה (ובפרט ע\"י חטא), וע\"ז הוא זכרון ברית הפנימי שהתקשר עצמו כבי', ובמה בשופר בצעקה דתשובה, וראי' מהתו' מזכרון דנח שלא הי' תו\"מ עדיין, וזכרון האבות ויצי\"מ, וכן רצון העצמי דנש\"י באלקות, וכמו במס\"נ בפו\"מ בלי הרגש עונג כלל, וכמו החוקים שכל זה הוא רצון עצמי.</span>\n<b>רב)</b> והנה בעצם מהותם דרצון ועונג הן הפכים זמ\"ז דהעונג הוא בהעלם בנפש והרצון הוא בהתגלות דוקא, דרצון הוא ל' מרוצה שהוא התגלות והמשכת הנפש וכמו היש את נפשך שהוא התגלות הנפש ומרוצתו לאיזה דבר כו', וזהו שהרצון הוא בבחי' התעוררות דוקא שמתעורר באיזה רצון שהו\"ע ההתגלות כו' (והיינו שלפי שהרצון הוא חיצוניות הנפש דע\"ה שהוא עצמי ה\"ה בחי' חיצוני' העצמות ע\"כ כל ענינו הוא בחי' ההתגלות כו'), והתענוג הוא דוקא בהעלם בנפש שאינו בבחי' מרוצה כ\"א מה שמתענג בעצמו, והיינו גם שמתענג באיזה דבר א\"ז בבחי' מרוצה כ\"א מה שמתענג בעצמו (ולעיל פקצ\"ב נת' שהתענוג הוא בהתגלות היינו להיותו כח נעלה ביותר והוא בבחי' אור בלא כלי כו', ע\"כ כשמתענג באיזה דבר נראה ונגלה בו התענוג שמתענג (ומתעלם ע\"י החכ' דוקא להיותו בחי' עונג בעצם מהותו ובא בבחי' חכ' ושכל כו' וכמשי\"ת), אבל אינו בבחי' מרוצה כלל, דהתענוג הוא בעצמו רק שנראה אורו כו'), ועיקר התענוג הוא שמתענג בעצם מהותו ממש לא בבחי' הגילוים שלו גם לא בבחי' הרוממות שלו כו'\n(צו פרידין פון זיך אליין), שזהו העונג בהעצם לא במה שהוא העצם כו', דהיינו לא במעלת העצם כ\"א בהעצם עצמו כו' וכמ\"ש במ\"א, דא\"ז ברצון לומר שרוצה בעצמו היינו בעצם מהותו כו', דגם מה שרוצה לחיות ה\"ז התפשטות כו', ותוקף התענוג ביותר הוא בתענוג דאו\"ח דוקא כו' (וזהו לפי שהעונג הוא פנימי' ועצמות הנפש ע\"כ הוא בהעלם דוקא כו'), ומה שבא ממנו בהמשכה הוא בחי' הארה לבד לא עצם העונג כו'."],[3601330589,"<b>וזהו</b> הטעם מה שהרצון שולט על התענוג ואין התענוג שולט על הרצון כו', דהנה התענוג אין ביכולתו לשנות מרוצה ללא רוצה או מלא רוצה לרוצה, וכמו מי שהוא חכם גדול והוא אוהב את המושכלות שיש לו תענוג גדול מאד במושכלות, אך איזה מושכלות הוא רוצה רק מושכלות דקדושה בעסק התורה וידיעת אלקות כו', ומושכלות אחרות שאינם אלקו' ובפרט מה שיכול להביא להיפך מאלקו ח\"ו אינו רוצה בהם כלל וכלל כו', וע\"ה שיודע שיש בהם שכלי' עמוקים ויש לו בעצם תענוג גדול בענינים שכלי' (דחכם אמיתי העונג שלו במושכלות הוא גדול ועצום מאד), לא יועיל כ\"ז להיות לו ח\"ו רצון לזה, מפני רצונו העצמי שרוצה רק באלקות וכל מה שהוא היפך מאלקו' אינו רוצה בשום אופן כו'. וכמו\"כ לא ישתנה מרוצה ללא רוצה, והוא שהרצון העצמי דבנש\"י לאלקו' לא נשתנה ולא נתהפך לעולם גם בריבוי תענוגים הגשמי' כו', וכמ\"ש מים רבים דריבוי רצונות ותאוות זרות כו' לא יוכלו לכבות האה' והרצון העצמי כו'. וכמו שאנ\"ר גם בקשב\"ק המשוקעים ר\"ל בריבוי תאוות ותענוגים גשמי' הנה לפעמים כמו בזמן השמחה\nוכה\"ג ה\"ה מתקרבים ליראי אלקים ומדברים בשבחי של יראת אלקים וקיום המצות ואיך שגם הוא רצונו בזה רק שיש לו מניעות ועיכובים כו', וכ\"ז אינו שקר בנפשו דהאמת הוא שרוצה באלקו' כי הרצון העצמי יש בו, וע\"ה שנשקע ונאבד מאד מ\"מ ישנו בו כו', וזהו דלעתיד כאשר יתקע בשופר גדול ובאו האובדים בארץ אשור שהוא בחי' התענוג דגם האבודים ר\"ל בתענוגים הגשמי' יבואו כאשר יהי' גילוי אלקו' כו'. הרי דהתענוג אינו שולט על הרצון לשנותו כו', והרצון שולט על התענוג לשנותו מעונג לצער ומצער לעונג, וכמו בענין הסיגופים דע\"ה צער לנפש ה\"ה לו לעונג מפני שרוצה מאד בתיקון נפשו כו', וכמו שהתירו ת\"ח בשבת מפני שהוא עונג לו כו', וכמו\"כ מצד עוצם הרצון לאלקו' ה\"ה מואס בכל התענוגים הגשמי' וכמו שנאו רע דצדיקים גמורים, וכן בבע\"ת שמואס בכל עניני עוה\"ז ומואס בחייו והיינו שמואס בחיי הקודם שהי' בתענוגים הגשמי' ה\"ה מואס בהם בתכלית המיאוס כו', וכמ\"ש כ\"ז באריכות בד\"ה יו\"ט של ר\"ה רס\"ו. והרי העונג הוא למע' מהרצון ומפני מה הרצון שולט בהעונג כו', אך זהו\nמפני שהרצון שהוא בבחי' מרוצה והמשכה נמשך העצמו' שלו, והעונג שהוא בבחי' העלם מה שנמשך ומתגלה הוא רק הארה לבד כו', ולכן הרצון שולט על העונג והעונג שהוא רק הארה אינו שולט על הרצון כו'. וע\"כ להיות שהרצון הוא עצמי שאין התענוג סבה אליו ובעצם מהותם המה הפכים זמ\"ז כו', לכן מה שבהמשכת הרצון נמשך מבחי' התענוג הוא רק הארה לבד כו', להיות דכללות המשכת התענוג הוא רק הארה לבד ובפרט בהרצון שהם הפכי' זמ\"ז כו', הנה מה שנמשך בזה מבחי' העונג הוא רק הארת והתפשטות העונג לבד כו' (רק בבחי' רצון העצמי יש בו בחי' תענוג העצמי להיות שניהם בחי' עצמות כו', וז\"ע נח\"ר לפני שאמרתי ונעשה רצוני לפני דוקא בבחי' העצמו' כו' כנ\"ל פקצ\"ג).\n<span data-k=\"ks\"><b>קיצור.</b> ובעצם מהותם רצון וענג הפכים זמ\"ז, רצון הוא מרוצת הנפש, וענג העלם, ותוקף התענוג הוא באו\"ח, וענג עצמי הוא בעצם המהות, והמשכת הענג הוא רק הארה, ולכן ענג אינו שולט על הרצון, דתענוג במושכלות לא ישנה, עצם רצונו במושכלות אלקית, ומ\"ר דתענוגים גשמיים לא יכבה האהבה האלקית</span>"],[3601330590,"<b>ורצון</b> שולט על התענוג שמתענג במה שהוא רוצה, מפני שהעצמי נמשך, וע\"כ ברצון רק הארת הענג ובמקיף.\n<b>רג)</b> אמנם כח החכ' הרי אינו עצמו' הנפש רק כח מהנפש שגם שרש ומקור כח החכ' גם בשרשו הראשון (שאינו בבחי' מקור לשכל גלוי כו') אינו עצמות הנפש כו', אמנם ידוע שהנפש נק' נפש המשכלת והוא מפני שכח החכ' מתאחד עם הנפש כו', וכמ\"ש בלק\"ת ד\"ה וידבר כו' כה\"ד האלה, ולכאורה הרי כל הכחות מתאחדים עם הנפש ולמה נק' דוקא ע\"ש החכ', אך זהו משום דמציאות החכ' שבו הוא מצד מעלת מהות הנפש עצמו. והענין הוא דהרי האדם מובדל מכל הבע\"ח בכח החכ' שבו, דהרי מדות טבעי' יש בבע\"ח ג\"כ (וכמו שגם הבהמה נמשכת אחר בנה כו', וכמו לבני עורב אשר יקראו שמרחם על בניו כו', ובפרט הנשר שהוא רחמני כו'), ויתרון האדם על הבע\"ח הוא בשכל ודעת שבו כו', והיינו מצד מהות נפשו שהיא נפש האדם (דשרשו מבחי' פני אדם שבמרכבה או מבחי' אדה\"ע שעל הכסא כו'), ע\"כ יש בו חכ' ושכל כו' (ובד\"כ הוא מפני שנפשו הוא מבחי' התיקון דהעיקר הוא בתיקון בחי' החכ' והוא בחי' ש' מ\"ה כו' וכמ\"ש במ\"א), וכמו שמעלת האדם בבחי' הדבור שבו ה\"ז מצד הנפש שהוא בחי' נפש המדברת כו'\n(וע\"כ הנפש מלאה אותי' כו'), כמו\"כ מעלתו בחכ' ושכל הוא מצד הנפש דלהיותו נפש האדם ע\"כ יש בו חכ' כו'. נמצא דמפני שעצם הנפש הוא במדרי' חכ' (הגם שאינו חכ' ושכל כלל כו'), הוא הסבה למציאת כח החכ' שבו כו', וזהו שנק' נפש המשכלת הגם שהנפש אינו חכ' ושכל, אך להיות דמהות הנפש עצמה הוא הסבה למציאת החכ' והשכל, ה\"ז מתאחד בו בבחי' אחדות ממש עד שנק' ע\"ש נפש המשכלת כו'. ומובן מזה דהחכ' אינו עצמות הנפש ויש לה סבה רק הסבה להחכ' הוא העצמות דהנפש, והיינו בחי' התענוג שבנפש שהתענוג הוא עצמו' הנפש והוא בחי' הפנימי שבו (וכנ\"ל שהרצון הוא חיצוני והתענוג הוא פנימי כו'), והוא סבת כח החכ' גם במקורו ושרשו הראשון כו'. וכמו\"כ גם התגלות החכ' הוא מבחי' התענוג דע\"י התענוג שמתענג בהדבר הוא משכיל בו כו' (דגם מה שלעולם ילמוד אדם במקום שלבו חפץ העיקר הוא מצד התענוג דהיינו שהרצון הוא עם תענוג כו', ורצון בלא תענוג היינו רק בדרך קב\"ע זה ג\"כ יכול לפעול להשכיל, וזהו רק מצד נתינת ומסירת נפשו לזה כו', והעיקר בזה הוא מבחי' הדעת שבאוירא\nשמכריח להשכיל כו', וכמ\"ש במ\"א וכמשי\"ת). ובאמת התענוג עצמו הוא שנעשה בבחי' שכל וחכ' ולכן ההשכלה היא כפי אופן התענוג דוקא כו', דברצון הרי יכול להשכיל היפך הרצון משא\"כ התענוג א\"א שישכיל היפך התענוג (והוא הגישמאק) שיש לו בהדבר כו', רק להיות שהחכ' אינו תענוג היינו שהוא כמו כח בפ\"ע מן התענוג, ע\"כ זהו שהתענוג הוא רק סבה אל החכ', אבל באמת התענוג הוא עצמו שנעשה בבחי' חכ' כו'. וכמו עד\"מ מי שרוצה בבנין בית ויש לו תענוג בענין הבית ורוצה לעשותו בפועל, ומחמת התענוג ה\"ה ממציא בכח המשכיל שבו השכלות באופני ציור חדרי הבנין ואבנים נאות עד להפליא כו', דבכח התענוג לא הי' כל פרטי ההמצאות בציורים הנאים וסדר הבנין כו', ואעפ\"כ לא הי' כח המשכיל ממציא כל השכלי' רק מכח התענוג שיש לו בעצם הבית כו', והנה לאחר שנבנה כל הבנין והוא הולך ומטייל בו ומתענג מגודל עוצם תפארתו הרי התענוג הוא פנימי"],[3601330591,"ועצמי שמתענג בעצם נפשו ממש בהבנין כו', אך אימתי יתענג בזה דוקא כשהבנין נעשה ע\"פ גזרת חכמתו שהשכיל מתחלה באופן הבנין ונעשה כך במכוון בכל הפרטים אז מתענג בו בעצם נפשו, ואם יחסר בו דבר שנעשה לא כפי שכלו וחכמתו מתבטל התענוג לגמרי שאינו מתענג בו כלל כו'. ה\"ז הוראה גמורה שהחכמה הוא התענוג, דמה שהשכיל בתחלה באופני הבנין באופן כך וכך דוקא הוא מצד התענוג שלו בעצם דבר הבנין (רק ששם הוא בבחי' פשיטות לגמרי), וע\"כ דוקא כאשר נעשה כפי חכמתו אז הוא מתענג בו לפי שהחכ' הוא התענוג רק שבא בבחי' חכ' ושכל כו', וזהו שבחכ' התענוג הוא בבחי' התלבשות פנימי היינו שהתענוג הוא סבת החכ' שמשכיל בכח החכ' רק מצד התענוג כו', והוא עצמו הוא שנעשה בבחי' חכ' ושכל כו'. ומובן דהתפשטות החכ' הוא רק מהארת התענוג ובחי' פנימי' החכ' הוא בחי' פנימי' התענוג עד שבשרשו ומקורו הראשון הוא ממש בחי' תענוג הנעלם העצמי כו' (וזהו מעלת כח החכ' מה שמוחין דגדלות הן בבחי' הבדלה והפרשה, וכמ\"ש במ\"א דג\"ר הן בחי' השבת שבכל פרצוף שהוא בבחי' מנוחה בבחי'\nהבדלה כו', מפני שהחכ' הוא בחי' התענוג והתענוג הוא בבחי' העלם כו' כנ\"ל, ע\"כ גם מוחין דגדלות הן בבחי' הבדלה כו'). ועפ\"ז יובן מ\"ש בזהר ובע\"ח דבגולגלתא מאיר רק חיצוני' עתיק בבחי' מקיף ובח\"ס מאיר בחי' פנימי' עתיק בבחי' פנימי ובבחי' התלבשות ממש כו', ולכאורה הרי הרצון למע' מבחי' החכ' כו'. ולפי הנ\"ל מובן דבאמת הרצון הוא למע' במה שהוא בחי' עצמי מהנפש כו' (אבל הוא בחי' חיצוני' העצמות כנ\"ל, וע\"כ בא הרצון בבחי' מקיף לבד שהוא בחי' חיצוני' כו') ואין התענוג סבה אליו כו', וע\"כ מה שמאיר בו מבחי' התענוג הוא התפשטות הארתו לבד כו', והחכ' ע\"ה שאינו עצמי סבתו הוא התענוג והוא מהותו בעצם כו' (ולכן בהמשכת עצמות החכ' נמשך פנימית ועצמות הנפש ממש כו', וכמו בהולדה שהטפה נמשכת מעצמות המוח שבה עצם כח החכ' ועצם התענוג שמוליד בדומה לו מהות נפש ממש כו' שנותן לו כל העצמו' שלו עד שיכול להיות יפה כח הבן כו' וכמ\"ש במ\"א), דבחי' פנימית ועצמות החכ' הוא עצמות התענוג כו'. וכמו דפנימי' אבא הוא פנימי' עתיק ממש, כ\"ש שהוא כן בבחי'\nח\"ס שהוא בחי' פנימי' עתיק ממש כו', וע\"כ נק' באד\"ז מוחא דעת\"ק ממש כו', וי\"ל שזהו מה שבגולגולת מתלבש חסד דעת\"י ובחכ' מתלבש גבו' דעת\"י, וידוע דבחי' החסד דעם היותו בחי' הגילוי (והוא אור שאינו מתעבה כו') מ\"מ הוא בחי' חיצוני' לבד כו', ובחי' גבו' דעת\"י הוא בחי' פנימי' עת\"י שבא בבחי' תגבורת העצמי' כו' ומלובש בבחי' ח\"ס דוקא כו', ועמ\"ש בלק\"ת בהביאור דשוש אשיש כו'.\n<b>ועפ\"ז</b> יובן מ\"ש דרשו ה' בהמצאו בזמן שהוא מצוי גם ליחיד כו', ולכאורה מ\"ש בכל קראנו אליו ה\"ז ג\"כ בחי' אוא\"ס שלמע' מהשתל' כו'. אך הענין דמש\"א אליו ולא למדותיו היינו שלמע' מע\"ס אבל מ\"מ הוא מה ששייך להשתל' (והפרד\"ס מפרש אליו הוא בחי' האור המתלבש בהכלים כו', ובכתבים מבו' דאליו הוא בחי' עצמות אוא\"ס שלמעלה מאו\"כ דאצי', אבל מ\"מ זהו מה ששייך להשתל' כו'), וזהו בחי' הרצון ובחי' חסד דעת\"י שכ\"ז בחי' חיצוני' לבד כו', וע\"כ יש בזה עדיין חילוקי מדרי' שהוא לצבור שיכולים להמשיך מבחי' ומדרי' זו כו', אבל בר\"ה ועשי\"ת אז מאיר בחי' פנימי' ועצמות א\"ס בחי' גבו' דעתיק שמלובש במו\"ס"],[3601330592,"שהוא תגבורת העצמות גילוי בחי' פנימי' עתיק כו', וכמ\"ש חשף ה' את זרוע קדשו כו' קירוב המאור כו', ולכן אז זמן התשו' לתקן כל הפגמים והחסרונות שחיסר באיזה מצוה או קיצר בעבודת הוי', דבכדי למלאות הפגמים והחסרונות צ\"ל ההמשכה מבחי' עצמות א\"ס דהיינו בחי' פנימי' עתיק בחי' עצמות התענוג כו', וכמשנת\"ל פקצ\"ג. וזהו ג\"כ ענין תקיעת שופר שהו\"ע הצעקה פנימי' מעומקא דלבא בחי' צעק לבם כו', ושופר הוא קול המטיל חרדה דהיינו בחי' גבו' דעתיק כו', והזמן המסוגל לזה הוא בעשי\"ת דאז מאיר בחי' פנימי' עתיק כו', דבבחי' ומדרי' זו לא יש חילוקי מדרי' כלל וה\"ה מצוי לכל דורשיו גם ליחיד כו', ובירושלמי אי' שהוא מצוי בבתי כנסיות ובבתי מדרשות היינו בתו', והוא כמשנת\"ל דבח\"ס מאיר בחי' פנימי' עתיק כו', וזהו שהתו' היא ג\"כ תשו' דכמו שהתשו' היא רפואה וכמא' גדולה תשו' שמביאה רפואה לעולם שנא' ארפא משובתם, כמו\"כ בתו' כתי' ולכל בשרו מרפא כו', והיינו מפני שבחכ' דתו' יש בזה גילוי בחי' פנימי' עתיק כו'. וזהו דרשו ה' בהמצאו אלו עשרה ימים שבין ר\"ה\nליוהכ\"פ דאז הוא מצוי היינו שנמשך בחי' עצמי' א\"ס בחי' פנימי' עתיק כו', וה\"ה מצוי כבי' לדורשיו גם ליחיד כו'.\n<span data-k=\"ks\"><b>קיצור.</b> אמנם חכ' עם היותו רק כח, נק' הנפש ע\"ש החכ', דעצם הנפש הוא חכ' שזהו מעלת האדם (והוא בחי' תיקון), וזהו סבת מציאת כח החכ', ולכן מתאחד עם העצם ונק' ע\"ש, וזהו שהתענוג הוא סבת החכ', ובאמת התענוג הוא עצמו נעשה חכ', ולכן החכ' היא כפי התענוג דוקא, וכמו חיוב השכל בהבנין הוא כפי תענוג העצמי בו, וזהו דמוחין דגדלות הן בהבדלה, ובשרשו ומקורו הוא התענוג הנעלם, וזהו דח\"ס הוא פנימיות עתיק ובבחי' פנימיות, וי\"ל דז\"ע גבו' דעתיק שמלובש במו\"ס. וזהו דרשו ה' בהמצאו, דבכל קראנו איליו בחי' רצון, ובהמצאו בעשי\"ת שהעצם מצוי בחי' עתיק, ובירוש' בבת\"כ ובמ\"ד זהו תורה בחי' ח\"ס.</span>"],[3601330593,"<h3>בס\"ד. ליל ב' דחה\"ס, תרד\"ע</h3>\n<b>העושה</b> סוכתו תחת האילן כאלו עשאה בתוך הבית, וצ\"ל והלא ידוע דאילן הוא בחי' או\"מ וכמ\"ש והשענו תחת העץ שזהו מה שהמשיך להם אברהם או\"מ כו', וסוכה הוא ג\"כ או\"מ שז\"ע סכך הסוכה כו', ומפני מה העושה סוכתו חחת האילן כאלו עשאה כו', וביותר אינו מובן לפי מה דאי' במד\"ר פ' וירא אתה אמרת והשענו תחת העץ חייך שאני פורע לבניך במדבר בישוב ולע\"ל, במדבר פרש ענן למסך, בישוב בסכות תשבו כו', ולע\"ל וסוכה תהי' לצל יומם כו', הרי דמצות סוכה הוא משום דוהשענו תחת העץ ולמה סוכה תחת האילן פסולה כו'. ולהבין זה ילה\"ק משנת\"ל ההפרש בין מו\"ס לגולגלתא דבגולגלתא בחי' אור עתיק הוא רק בבחי' מקיף ובחי' חיצוני' לבד, ובמו\"ס מאיר בחי' פנימי' עתיק ובבחי'"],[3601330594,"פנימי, ונת' דגילוי העונג הוא ברצון ובחכ', רק שברצון הוא רק הארת העונג ובבחי' מקיף והבדלה, להיות שהרצון הוא עצמי כמו העונג דשניהם עצמי' רק שהעונג הוא פנימי' העצמיות ורצון הוא חיצוניות העצמיות, אבל אין העונג סבה אל הרצון ובעצם מהותם המה הפכים זמ\"ז כו', וע\"כ מה שבגילוי הרצון יש בזה עונג ה\"ז רק הארה לבד ובבחי' מקיף כו'. משא\"כ החכ' אינו עצמי' כ\"א כח מהנפש ויש לו סבה כו', אמנם הוא עצמות הנפש מה שהוא במדרי' אדם כו', והיינו שהתענוג הוא סבת החכ' וא\"כ ה\"ז בבחי' התלבשו' פנימי מאחר שזהו הסבה כו', רק שבהתפשטו' החכ' הוא הארת העונג ובעצם החכ' הוא בחי' עצמות העונג כו', והיינו דבח\"ס מלובש בחי' התענוג העצמי דהיינו בחי' פנימי' עתיק כו'.\n<b>רד)</b> אמנם לפי הנ\"ל צ\"ל מאחר דבח\"ס מתלבש בחי' פנימי' עתיק וממילא הרי ח\"ס הוא בחי' פנימי' הכתר כו' (למעלה מבחי' גולגלתא שהוא בחי' חיצוני' הכתר דהארת עתיק הוא שם בבחי' מקיף לבד כו', וכמ\"ש בע\"ח דגולגלתא היא חיצוני' הכתר ומו\"ס פנימי' הכתר כו'), איך ח\"ס הוא בבחי' מקור לחכ' הגלוי' כו', שהרי מקור החכ' הוא מבחי' ח\"ס, וכמו עד\"מ שכל גלוי הוא מכח המשכיל כמו\"כ בדוגמא למע' חכ' דאצי' שרשה מבחי' חכ' שבכתר כו', והלא פנימי' הכתר אינו בבחי' מקור לע\"ס כנודע, ומאחר דח\"ס הוא בחי' פנימי' הכתר איך הוא בבחי' מקור לחכ' כו'. אך הענין הוא דהרי באמת התהוות החכ' מבחי' חכ' שבכתר הוא מבחי' שערות לבד וכמא' אבא יונק ממזלא שהוא מזל ונוצר חסד כו', וענין השערות ידוע שזהו הארה הבאה בדרך דילוג שלא בס' והדרגה כו', וכל המשכה שבדרך דילוג הוא שאינו נמשך מהות האור כמו שהוא כ\"א ע\"ד הארה דהארה לבד כו' (וידוע דכל הארה דהארה היא הארה נבדלת ממקורה כו', וכמו\"כ בענין זה הגם שאינה בבחי' הארה נבדלת ממש כמו אור של תולדה כו', מ\"מ\nאינו מהות האור כמו שהוא כו', וכמו גילוי הקו שבדרך דילוג הצמצום הגם שנוגע ודבוק במקורו והוא מעין מקורו כו', מ\"מ המשכתו ע\"י הפסק הוא שאינו מהות האור הראשון כו', וידוע דהקו נק' מזל כו', וכמאמר האי חוטא יקירא קדישא כו' איקרי מזל כו'), וכמו\"כ הוא בבחי' מזל ונוצר מקור החכ' שזהו המשכה בדרך דילוג, וע\"כ הגם דשרש המשכתו הוא מח\"ס שזהו פנימי' הכתר כו', מ\"מ יכול להיות מזה התהוות החכ' דאצי' כו'. וזהו מ\"ש והחכ' מאין תמצא דפי' מאין הוא בחי' הארה לבד שבאין ערוך לגבי מקורו שמזה נמצא מציאו' החכ' כו', וגם פי' מאין היינו מבחי' אין העצמי דכתר, וי\"ל שזהו בחי' ח\"ס שבה מלובש פנימי' עתיק שע\"כ נק' אין שהיא בבחי' אין עצמי כו', וממנה נמצא החכ' בבחי' מציאה, וכמו המציאה שאינו יודעים מאין בא, כמו\"כ החכ' אינה מרגיש מקורה לפי שנמצאה מבחי' הארה לבד ונמצאה בבחי' מציאו' דבר כו', וע\"כ חכ' דאצי' הגם שנמצאה מבחי' ח\"ס היא באין ערוך לגבי', לפי שנמצאה מבחי' הארה דהארה לבד שבאין ערוך לגבי ח\"ס ונמצאה מזה בבחי' מציאו' דבר כו'. אך\nעדיין א\"ז מתיישב שהרי י\"ג ת\"ד בהכרח שבהם מאיר מבחי' מהות מו\"ס ממש, שהרי נודע דיגמה\"ר שהן י\"ג ת\"ד על ידם הוא תיקון כל הפגמים, והיינו משום המשכתם מבחי' מו\"ס, וכמ\"ש באד\"ר דקל\"ב א' כל תקוני דיקנא לא אשתכח אלא ממוחא דרישא כו', ולהיות דבח\"ס מלובש בחי' פנימי' עתיק ע\"כ נמשך משם מילוי כל הפגמים כו', דהרי ידוע דהמצות"],[3601330595,"שרשם מגולגלתא, ונת\"ל פ\"ר דהעונג עליון מאיר שם בבחי' מקיף לבד כו', והוא בחי' חיצוני' העונג כו', ובמו\"ס מלובש בחי' עונג העליון בבחי' פנימי' והוא פנימי' העונג כו', וע\"כ עי\"ז מתתקן הפגם שבמעהמ\"צ כו', וכמשנת\"ל פקצ\"ג דלגבי התענוג העצמי אין הרצון תופס מקום ע\"כ נמשך משם סליחת עוונות, וגם להיות הרצון חיצוניות והעונג פנימי' ע\"כ נמשך משם הרצון מחדש שז\"ע מילוי הפגמים כו'. אמנם מובן מזה דבי\"ג ת\"ד מאיר מהות ועצמו' בחי' עתי', דהרי הארת עתיק מאיר בהרצון ג\"כ, וא\"כ מה שמהי\"ג ת\"ד נמשך מילוי הפגמים זהו מפני שמאיר בהם בחי' מהוע\"צ עתיק כו', ועיקר המשכה זו דבחי' עצמו' עתיק הוא במזל ונוצר, וכדאי' באד\"ז דרפ\"ט ע\"ב בהאי מזלא (דהיינו תקון הח' מי\"ג ת\"ד שהוא מזל ונוצר חסד) פשיט פשיטותא דקוטרא עילאה ההוא רישא דכל רישין דלא אתיידע ולא אשתמודע כו', בג\"כ כולא בהאי מזלא תלי' כו', והיינו דבחי' פשיטת קשר עליון שהוא בחי' רדל\"א נמשך ומאיר בבחי' דיקנא בכלל ובמזל ונוצר בפרט דלכן כולהו מיני' תליין. והנה מה שרדל\"א נק' קשר עליון\nי\"ל שעי\"ז הוא התקשרות עצמות א\"ס עם עולמו' והשתל' כו', דהרי עתיק הוא בחי' העתקת העצמו' כו', וא\"כ הרי בזה הוא התקשרו' הא\"ס עם העולמו' כו', והגם דעתיק הוא שנעתק ונבדל מהשתל' כו', הרי נת\"ל פקצ\"ו דעצמו' א\"ס אינו בגדר העתקה מהשתל' ג\"כ וכשנעשה בחי' עתיק ה\"ז בגדר ההעתקה עכ\"פ כו', א\"כ הרי בזה שנעתק ונבדל מההשתל' ה\"ה בבחי' ההתקשרות בהשתל' כו'. ובאמת י\"ל דעיקר ההתקשרות הוא בנש\"י דזהו מה שעיקר ההמשכה הוא במזל ונוצר להיות דמזלות ונוצר ונקה הן מזלות דנש\"י וכמ\"ש במ\"א, וזהו אין מזל לישראל דהפי' הוא שהאין הוא המזל דישראל והוא בחי' האין העצמי דבחי' פנימי' עתיק שמלובש במזל ונוצר כו', ועש\"ז נק' קוטרא עילאה שהו\"ע ההתקשרו' דעצמו' א\"ס שנתקשר כבי' בנש\"י כו'. גם י\"ל ענין קוטרא עילאה דנתקשר בזה כל העצמו' דא\"ס ב\"ה, דע\"ה שזהו רק בחי' תחתונה שבעצמו' מ\"מ בנקודה זו מקושר כל העצמו' כו', וע\"ד שא' שכשאתה תופס במקצת מן העצם אתה תופס בכולו, וענין מקצת מן העצם היינו בחי' האחרונה שבעצמות כו' (ועמשית\"ל פ') שבזה מקושר כל\nהעצמו' כו'. ונמצא דביגת\"ד בכלל ובמזל ונוצר חסד בפרט נמשך בזה מהות בחי' עתיק ממש כו', ולכאו' א\"מ והלא המזלות הן מח\"ס ומהו\"ע דפשיטות קוטרא עילאה הוא בהאי מזלא כו'. הנה זה מובן ממשנת\"ל פ\"ר דבחי' פנימי' עתיק מלובש בח\"ס, ונת' בפר\"ג דח\"ס הוא בחי' פנימי' עתיק כו', וע\"כ הדיקנא הנמשכת ממו\"ס מאיר בה בחי' פנימי' עתיק כו'. וז\"ע כשמן הטוב על הראש יורד על הזקן כו', דשמן הטוב הוא בחי' פנימי' עתיק וכמ\"ש שמן למאור שזהו בחי' מאור שלמע' מאור כו', ומבו' במ\"א בג' מדרי' דאור מים רקיע דונהר יוצא מעדן הוא בחי' מים כו', ועדן הוא בחי' אור כו', ושמן למאור הוא בחי' עדן עילאה סתימאה הנז' באד\"ז דרפ\"ח סע\"ב ודר\"צ רע\"א, והוא בחי' מוחא דעתיקא בחי' מו\"ס שבו פנימי' עתיק כנ\"ל, ולכן השמן אינו מתערב כו', והיינו בחי' אנת חד ולא בחושבן בחי' הי\"א שבקדושה כו' והו\"ע קדושתי שלמע' מקדושתכם כו', ובחי' שמן הטוב יורד על הזקן שמאיר ביגת\"ד כו', וכמ\"ש באד\"ר דקל\"א א' דנגדין בי' י\"ג נביעין מבועין דמשח רבות טבא כו', ובאדר\"ז דרפ\"ט ב' י\"ג\nנביעין דמשחא רבותא טבא תליין בדיקנא כו'. הרי דבמזל ונוצר מאיר בחי' עצמו' ח\"ס ממש וא\"כ איך הוא בבחי' מקור לחכ' כו'."],[3601330596,"<span data-k=\"ks\"><b>קיצור.</b> ולפי הנ\"ל איך ח\"ס מקור חכ' הגלוי', הענין דזהו בבחי' שערות מזל ונוצר, וזהו והחכ' מאין העצמי דכתר תמצא בבחי' מציאה, מפני שהוא רק ממזל, ועדיין אינו מתיישב שהרי ביגת\"ד מאיר בחי' פנימיות עתיק, ולכן ממלאים כל הפגמים, והעיקר הוא במזל ונוצר וכמ\"ש באד\"ז בהאי מזלא פשיט פשיטותא דקוטרא עילאה בחי' רדל\"א שנק' קשר העליון מפני שמקשר א\"ס עם העולמות, והעיקר עם נש\"י (דשרשם במזל ונוצר), וי\"ל שנק' עתיק קשר עילאה דעם היותו בחי' אחרונה מקושר בזה כל העצמות, והיינו דפנימיות עתיק שבמו\"ס (וי\"ל שהו\"ע שמן הטוב, שמן למאור למעלה מאור, עדן סתימאה), העיקר הוא במזל ונוצר, ואיך הוא מקור לחכ'.</span>\n<b>רה)</b> אך הענין הוא, דבח\"ס גופא יש ב' מדרי' ובד\"כ הוא בחי' פנימי' ח\"ס ובחי' חיצוני' שבו כו', דהנה יש ב' מדרי' בענין הסתימות, הא' שהוא סתום לגמרי ואינו נגלה למקבלים לעולם, והב' כאשר הוא סתום מן המקבלים, ולפעמים נגלה אליהם כו', וזה תלוי בעיקר ענין הסתימות שיש בו ב' מדרי', הא' כאשר הסתימות שלו אינו רק אל המקבלים לבד שמפני מיעוט ערכם לא יוכלו להשיגו, הלא בזה יש חילוקי מדרי' לפ\"ע המקבלים מאחר שהסתימות הוא רק מצד שהמקבלים אינם יכולים להשיגו הרי א\"ז בכל המקבלים בשוה כו', ויוכל להיות לפרקים בחי' התגלו' הסתימות שהרי האור בעצם הוא בערך המקבלים רק שמפני מיעוט ערכם אינם יכולים לקבל, ומ\"מ הרי אפס קצהו נגלה להם ויכול לבא לידי גילוי לגמרי בהגדלת כלי המקבלים כו', והב' כאשר בחי' הסתימות היא מצד עצמו דוקא ולא למקבלים לבד אלא מצ\"ע שהוא בבחי' ההעלם והסתימות שזהו הנק' העלם העצמו' כו', והיינו שהאור בעצם הוא למע' מגדר גילוי כו', דבזה לא יש חילוקי מדרי' וזה א\"א שיבא לידי גילוי לעולם אפי' אפס קצהו כו'.\n<b>וביאור</b> הענין הוא דהנה ידוע מ\"ש בזהר תרומה דקכ\"ז בענין סמ\"ך ומ\"ם דאפרסמון, דעם היות ששניהם סתומים יש הפרש ביניהם, דמ\"ם הסתימה שלו היא בריבוע והיינו שמ\"מ יש לו אחיזה והתיישבות בהפנימי כו', וסמ\"ך הוא בעיגול היינו שאין לו אחיזה והתיישבו' כלל כו', ובזהר ח\"א ד\"ה ע\"א אי' עיגולא וריבועא דלגאו וכ' המק\"מ שז\"ע עגולים ויושר כו', וי\"ל דענין עיגולא וריבועא הוא בחי' האו\"מ דאוא\"ס שלפה\"צ והוא בחי' העיגול הגדול שלפני הקו כו', ובחי' אור המלביש שאחה\"צ שג\"ז הוא בבחי' מקיף כו', ובד\"כ הו\"ע בחי' טה\"ע וטה\"ת דטה\"ע הוא בחי' העיגול הגדול שלפה\"צ כו', ובחי' טה\"ת הוא בחי' אור המלביש כו', ובד\"פ בחי' טה\"ת זהו בחי' א\"ק כו', אך גם בחי' המלביש ג\"כ בכלל בחי' טה\"ת כו'. ואי' בעה\"מ ש\"ב פ\"ב דהמלביש הוא מרובע, ובע\"ח אי' דצמצום הראשון שהוא בנקודה האמצעית דאוא\"ס ב\"ה שנעשה חלל ומקו\"פ והאוא\"ס מקיפו מכל צד הוא בעיגול דוקא, וכ\"ה באוצ\"ח, ובמבו\"ש מבו' הטעם ע\"ז, וי\"ל שז\"ע מ\"ם וסמ\"ך דאור המלביש הוא בחי' מ' סתומה להיות שזהו אחה\"צ ה\"ז\nבבחי' שייכות אל העולמו' וההשתל' כו', ועיגול הגדול שלפה\"צ ה\"ז בחי' סמ\"ך והיינו שמובדל בערך מבחי' השתל' כו'. והנה מה שהמלביש הוא מרובע אי' בעמה\"מ הטעם ע\"ז שז\"ע ד' אותי' הוי' שנעשה מהם הד' שמות ע\"ב ס\"ג מ\"ה ב\"ן, וא\"כ צ\"ל דבחי' עיגול ה\"ז למע' מש' הוי', ולפ\"ז י\"ל ב' הבחי' דמ\"ם וסמ\"ך בחי' עיגולא ורבועא גם באוא\"ס שלפה\"צ. דהנה מבו'"],[3601330597,"במ\"א בענין עד שלא נבה\"ע הי' הוא ושמו בלבד דשם זה הוא ש' הוי', וא\"כ הרי יש ש' הוי' גם באוא\"ס שלפה\"צ רק שזהו בבחי' התפשטו' האור, דהנה ידוע דבאוא\"ס שלפה\"צ ע\"ה דבכללו' הוא בחי' אור הכלול בעצמותו (דענין הצמצום הוא שיהי' התגלו' כבי' חוץ לעצמותו כו', וקוה\"צ הכל הוא כלול בעצמותו כו' וכמ\"ש במ\"א), מ\"מ בד\"פ יש בזה מדרי' והוא בחי' התפשטו' האור ובחי' עצם האור, ובחי' התפשטות האור (שזהו אצי' דכללות) הוא שם הוי' וכמ\"ש במ\"א בענין אתה הוא הוי' לבדיך, אך בדרך כלל כללות האור שלפני הצמצום הוא ש' הוי' ובחי' עצם האור והתפשטות האור הוא בחי' י\"ה ו\"ה, דעצם האור שלמעלה מבחי' שייכות אל העולמות הוא בחי' י\"ה, והתפשטות האור בחי' ו\"ה, ובכללות הוא בחי' שמו הכלול בעצמותו כו' (ועמשנת\"ל פכ\"ד). וכ\"ז הוא בהאור כמו שהוא בבחי' המשכה מן העצמו' יש בזה בחי' עצם האור שאינו בבחי' גילוי והתפשטות עדיין, ובחי' התפשטות האור שז\"ע שהי' אוא\"ס ממלא מקום החלל כו' (והן ב' המדרי' דממכ\"ע וסוכ\"ע בשרשן הראשון באוא\"ס שלפה\"צ כו', דממכ\"ע הוא בחי'\nהתפשטות האור דבזה הוא עליית הרצון שעלה ברצונו להאציל ולברוא כו', ובחי' עצם האור שזהו קודם עליית הרצון ה\"ז בחי' שרש בחי' סוכ\"ע כו') וכמ\"ש במ\"א, וכ\"ז הוא בבחי' המשכה וגילוי מן העצמו' כו'. אמנם האור הכלול בעצמותו ממש הוא שאינו בבחי' המשכה מן העצמו' כלל, רק כלול בעצמותו בבחי' יכולת לבד מה שביכלתו ית' להאיר כו', ועז\"א דשמו קדמון כקדמותו ית' היינו בחי' השם הכלול בעצמותו בבחי' יכולת לבד כו', דעל האור אינו שייך לומר קדמון ח\"ו שהרי הוא גילוי רצוני וכל גילוי רצוני הרי כאלו קדמו ההעדר כו', רק האור כמו שהוא בבחי' יכולת לבד בזה בהכרח לומר שזהו קדמון כקדמותו ית' כו', וכמ\"ש באורך בדרוש יו\"ט של ר\"ה רס\"ו, ומבו' במ\"א דבזה יצדק מ\"ש הגנת אגוז הובא בשל\"ה בהתחלתו דש' הוי' כמו שהוא בעצמו' אינו בבחי' אותי' כו', דדוקא האור כמו שהוא בבחי' המשכה יש בו אותי' שהו\"ע הגילוי ואופן הגילוי בד' אותי' צמצום והתפשטות כו' (ועמ\"ש בד\"ה ועשית חג שבועות רנ\"ו, איך ששייך כ\"ז גם באוא\"ס שלפה\"צ כו'). אבל בשמו העצמי שהוא האור הכלול\nבעצמותו ממש שאינו בבחי' המשכה כלל, אין שם אותי' והוא הוי' בלא ד' אות' הוי', וזהו בחי' העלם העצמי דא\"ס שלמע' לגמרי מבחי' המשכה וגילוי כו' וכמ\"ש במ\"א. ולפ\"ז י\"ל דגם באוא\"ס שלפה\"צ שייך בחי' מ\"ם סתומה דהיינו בחי' אוא\"ס השייך אל העולמות כו', והעיקר הוא בבחי' התפשטות האור כו', ובד\"כ זהו בבחי' האור שבבחי' המשכה מהעצמות כו', וסמ\"ך הוא בחי' העלם העצמי שמובדל בערך לגמרי מהעולמות וההשתל' כו'.\n<span data-k=\"ks\"><b>קיצור.</b> אך הענין הוא דבח\"ס יש ב' מדרי' בחי' סתום רק מהמקבלים, וע\"כ לפעמים מתגלה, ובחי' סתום בעצם למעלה מגדר גילוי, והו\"ע מ\"ם וסמ\"ך, ובהקדמת הזהר עיגולא וריבועא, עיגולא עה\"ג שלפני הקו בחי' טה\"ע, וריבועא טה\"ת בחי' אור המלביש, ובעה\"מ שהו\"ע ד' אותיות הוי', וא\"כ צ\"ל דעיגולא למעלה מש' הוי', ולפ\"ז י\"ל ב' המדרי' גם לפני הצמצום, דשמו הגדול הוא ש' הוי' והוא האור הכלול בעצמותו שבבחי' המשכה מן העצמות, אמנם שמו קדמון כקדמותו הוא הכלול בעצמות ממש, והוא הוי' בלא אותיות, והוא בחי' העלם העצמי י\"ל שזהו בחי' סמ\"ך.</span>"],[3601330598,"<b>רו)</b> והענין הוא דהנה ידוע שיש ב' בחי' מקיפים מקיף דאו\"י ומקיף דאו\"ח והכל מצד המשפיע דוקא (דמקיף דאו\"ח שמצד המקבל הוא מה שבוקע ועולה מלמטלמ\"ע כו' וכמ\"ש במ\"א, וכן יש מקיף דאו\"י שמצד המקבל והוא משנת\"ל פ\"ר שהמשפיע משער חושי המקבל איך למדוד ההשפעה כו', אך יש בחי' מקיף דאו\"י ואו\"ח דהכל מצד המשפיע), דבחי' מקיף דאו\"ח דמשפיע הוא מקיף עליון ביותר אשר בלתי מתגלה למטה כלל וכלל, ובחי' מקיף דאו\"י הוא שבא בגילוי אל המקבל בקירוב אליו כו'. דהנה מקיף דאו\"י הוא עד\"מ בהשפעת השכל כמו רב המשפיע שכל וסברא לתלמידו שמה שיוכל להתקבל בשכל התלמיד ה\"ז נק' או\"פ שמתיישב בכלי מוחו של התלמיד שתופס ומשיג את הענין, ועומק שכל זה שא\"א להתקבל בכלי מוחו ה\"ז נשאר בבחי' מקיף עליו והיינו שהוא בהעלם והסתר מהמקבל כו', ומ\"מ ה\"ז בקירוב אליו כי גם העומק הזה שנשאר בהעלם ה\"ז בערך השגתו דכל מה שמשפיע לו ה\"ז בערך ההשגה שלו, רק מפני שכלי השגתו קטנים עדיין בערך העומק הזה (היינו בכל מקבל לפ\"ע העומק כו'), וגם מפני שהאו\"פ אינו עדיין בהתיישבות\nגמורה אצלו ע\"כ הוא בבחי' מקיף כו', ובמשך הזמן כאשר הענין מתיישב ונתפס יותר בכלי מוחו וגם כלי מוחו מתגדלים כו' (והא בהא תליא דהגדלת הכלים הוא ע\"י השגת ותפיסת השכל כו') ה\"ה בא גם על העומק כו', וכמו לאחר מ' שנין דקאים אינש אדעתי' דרבי' כו', דהיינו ע\"י ההתעסקות בהאו\"פ שעי\"ז מתגדלים הכלים שלו כו' ה\"ה בא גם על העומק כו'. וכן הלומד דבר שכל שהוא עמוק מכלי מוחו שיכול מ\"מ לבא על עומקו לאחר זמן ע\"י שלומד הענין כ\"פ דבכל פעם ה\"ה בא יותר על הענין עד שישיג אותו כו', וכן המתחכם על דבר מה ולא יכול לעמוד על בוריו עד שנשאר אצלו בהעלם, ה\"ז מה שכבר בא מכח המשכיל בחי' אור מושכל פרטי דאל\"כ הרי לא הי' ההתחכמות כלל, ומאחר שמתחכם בזה ה\"ז כבר בא בבחי' מושכל פרטי כו', רק שלא בא עדיין באופן כזה שיהי' בבחי' שכל גלוי ממש כו', והיינו שלא נמדד עדיין בבחינת צמצום והגבלה להיות בבחי' שכל גלוי כו', ואפס קצהו מאיר בכלי מוחו רק שמאיר בבחי' מקיף לבד כו'. וזהו כמ\"ש במ\"א בענין כתר שבחכ' דהיינו מקור פרטי לאור השכל שכבר בא בבחי'\nמציאות מושכל כו', דחכ' שבכתר הוא כמו כח המשכיל עד\"מ שהוא כח היולי על כל השכלי' שאינו בבחי' מציאו' מושכל עדיין כו', וכתר שבחכ' הוא מקור מושכל פרטי והיינו כמו שכבר בא מכח המשכיל מושכל פרטי וה\"ה בבחי' מציאו' מושכל כו' וע\"כ הוא נרגש במוחו, והו\"ע ההנחה (רעכטקייט) שנרגש במוחו עוד קודם שהונח לו כו', וכן הו\"ע הנצוצי אור שמאירים עוד קודם שנתגלה האור שכל כו', וכמו המעיין באיזה ענין שאינו מובן לו ה\"ז בבחי' חשך והעלם ואח\"כ נעשה אצלו אור (עס ווערט עם ליכטיג), והיינו מפני שכבר בא מושכל פרטי מכח המשכיל בהנחת והבנת הענין ומזה הוא הרגש ההנחה והאור כו', רק שהוא בבחי' מקיף והעלם עדיין ויבא לידי גילוי כו'. וכן כשאומרים על איזה שכל עמוק עמוק מי ימצאנו, שאא\"ל זה על שכל שלא נודע ומושג אפי' אפס קצהו דלא יתכן לומר עמוק הוא, דלבד שאינו שייך לדבר בשכל שאינו יודעים אותו שהוא נמצא, הנה אינו שייך בזה ענין העומק שזהו רק שלא יגיע לאמתתו מפני עומקו אבל אפס קצהו כבר מושג כו', אבל מה שאינו מתגלה כלל אינו שייך לומר ע\"ז עמוק כו', וכמו עומק המעיין הוא במעיין שכבר נגלה שיש בו מה שנגלה והעומק"],[3601330599,"שלו, אבל במעיין שאינו נגלה כלל אינו שייך לומר בו עומק כו', אלא שיאמרו זה על שכל וסברא שהיא עמוקה ומוסתרת בהסתר עומק המושג להשיג תכלית אמיתתה שהוא סתום ונעלם מכל חכם, עז\"א עמוק עמוק מי ימצאנו שאינו יכולים לבא ע\"ז אבל אפס קצהו כבר מושג, וכאשר נגלה גם אותו העומק ה\"ז נק' גילוי תעלומות חכ' כו', והיינו מפני שאפס קצהו מושג מכבר ועתה נגלה גם תכלית עומקה שזהו בחי' תעלומות חכ' כו', שזהו חכ' נסתרת דהיינו מה שנסתר מכל אדם ועתה נתגלה כו', והגילוי הזה הוא שנותנים מלמע' כו', וזהו ג\"כ כאשר אפס קצהו כבר נודע ומושג שזהו הכלי להיות מלמע' גילוי בחי' תעלומות חכ' כו'. אבל כשלא הי' בהשגה כלל גם לא אפס קצהו האחרון לא יתכן לומר עמוק הוא כו', וכמו במצות פרה אדומה דכתי' אמרתי אחכמה והיא רחוקה ממני והיינו שחכמתו של שלמה לא הגיע להשיג עומק החכ' שבה, ומ\"מ הוא בערך שיתחכם בזה כו', וע\"כ אמרתי אחכמה רק שהיא רחוקה ממני מפני עומקה כו' וכמשנת\"ל ספקמ\"ח. והדוגמא בזה הוא כמו כח המשכיל שהוא מקור השכל להיותו בבחי' מקור עכ\"פ\nלשכל גלוי ה\"ה ג\"כ בבחי' קירוב כו', וזהו מה שמורגש מציאותו עכ\"פ, דע\"ה שאינו בבחי' שכלי עדיין שהרי הוא רק כח היולי כו', ומ\"מ הרי מרגישים שיש מציאו' כח משכיל מקור לשכל (דבעת שנופל לו שכל חדש ה\"ה מרגיש שבא מאיזה מקור כו'), והיינו לפי שהוא בבחינת קירוב ואפס קצהו מאיר והיינו שכל המבריק כו', וע\"כ הוא מורגש כו'. וכ\"ז הוא בחי' מקיף דאו\"י שהוא בבחינת השפעה והמשכה אם בהמשכה נגלית (בחי' ההעלם שבגילוי וכמו עומק השכל וכמו כתר שבחכ' כו') או בהמשכה נעלמת (כמו כח המשכיל) כו'.\n<span data-k=\"ks\"><b>קיצור.</b> דהנה יש מקיף דאו\"י ומקיף דאו\"ח, מקיף דאו\"י הוא בקירוב, וכמו עומק שנשאר בהעלם מהאו\"פ, שהוא בערך האו\"פ, דכשמתיישב בהאו\"פ ומתעסק בו יבוא על עומק, וכן המתחכם על דבר ואינו עומד על בוריו, דמ\"מ כבר נמשך ממקור השכל, וכמו הרגש הנחת הענין, ונצוצי האור, שכ\"ז הוא בחי' כשבח\"כ, וכן כשאומרים עמוק עמוק הוא, היינו כשיודעים אפס קצה מהעומק, אמרתי אחכמה והיא רחוקה, והגילוי הוא בחי' תעלומות חכ' שנותנים מלמעלה ע\"י הידיעה באפס קצהו, וכמו\"כ כח המשכיל שנרגש מציאותו מפני שהוא בקירוב.</span>\n<b>רז)</b> אמנם בחי' מקיף דאו\"ח דמשפיע הוא שאינו בא בבחי' השפעה אל המקבל אדרבה עיקר ענינו הוא היפך השפע שלא יומשך למטה לא בגילוי ולא בהעלם (היינו בבחי' המשכה נעלמת כו'), אלא להעלים ולהסתיר הדבר בעצמו להיות נעלם לגמרי מכל רואה ומכל משיג כו', ולא שמעלים אותו אלא שממילא מתעלם בעצמו וכמשי\"ת בסמוך, והיינו לפי שזהו מה שנעלם מצד עצמו שאינו בגדר גילוי, לא מה שהמקבל לא יוכל לקבל בכלי מוחו כ\"א שהדבר בעצם אינו בגדר גילוי, וע\"כ לא בא בבחי' השפעה וגילוי כלל כו', והן הדברים סתומים ונעלמים שאינם נראים ונגלים כלל אפי' אפס קצהו, וכמו ואתה חתום וסתום הדבר כו', דענין הקץ הוא נסתר ונעלם לגמרי שאינו נגלה כלל ואדרבה נראה ח\"ו ההיפך מזה כו', כידוע דמשיח בן דוד בא בהיסח הדעת שזהו מצד ריבוי ההעלמות וההסתרים כו' שהן מצד ההתעלמות כו', והיינו לפי שאמיתי' הגילוי דמשיח הוא"],[3601330600,"שיתגלה בחי' עדן עילאה סתימאה שזהו מה שסתום בעצם כו', ולפי שמתעלם בעצמותו ביותר ע\"כ עוד נראה להיפך כו', וכמו משלי שלמה שאינו נראה כלל החכ' שבזה רק מה שאנו יודעים שיש בזה חכ', אבל בהתגלות הרי לא נגלה כלל החכ' שבזה כו', וכמו כח השכל ההיולי העצמי שכלול בעצם הנפש שהוא בבחי' סתום מצ\"ע שאינו בבחי' מקור כלל כו'. ומה שסתום בעצם תמיד הוא חוזר אל העצמות בהעלם אחר העלם כו', דכשם שבחי' הגילוי טבעו הוא להתפשט ולירד למטה, שזהו הכלל שכל מה שבא בבחי' המשכה ה\"ה עתיד להתגלות והיינו מפני שטבע הגילוי הוא לירד ולהתפשט כו', כמו\"כ בחי' ההעלם טבעו הוא להתעלם יותר בבחי' העצמות כו', והיינו מה שנעלם בעצם דוקא (לא ההעלם של הגילוי כו') טבעו להתעלם כו' (ועמ\"ש במ\"א בענין רוח האדם העולה כו' ורוח הבהמה היורדת כו', דבחי' רוח הבהמה היינו בחי' האור והזיו המתפשט מן המאציל אל הנאצלים שהוא בחי' ירידה כו', והו\"ע יותר ממה שהעגל כו' הפרה רוצה להניק ולהשפיע כו'). וז\"ע ב' המקיפים בחי' מקיף דאו\"י שהוא בחי' ההעלם השייך אל המקבלים\nכו', ובחי' מקיף דאו\"ח שהוא בחי' ההעלם דהמשפיע עצמו שמצד עצמו כו', והוא המ\"ם סתומה שבבחי' התיישבות, וסמ\"ך עגול שבלתי מתיישב אדרבה הוא בבחי' העלם בעצמו כו'. ולמע' היינו כמו ישת חשך סתרו שיש בזה ב' עניני מקיפים הנ\"ל, א' שנק' חשמל עליון שמסתיר א\"ע ומלביש א\"ע בלבוש והעלם לגבי המקבלים שיוכל לבא אח\"כ לגילוי בהם וזהו בהאור השייך אל המקבלים, רק שאינם יכולים לקבל עצם האור, ע\"כ צריך להתעלם ומתגלה רק חיצוני' האור, ויש בזה גם מהאור המתעלם כו', וז\"ש ישת חשך סתרו ואח\"כ מגלה עמוקות מני חשך כו' (ובשרשו הוא בחי' הקו שנמשך מבחי' חשך הצמצום ומבחי' ההעלם דאוא\"ס שלפני הצמצום שנתעלם ונסתר ע\"י הצמצום ונתגלה אח\"כ בהקו\"ח כו', דע\"ה שהגילוי הוא רק החיצוני' יש בזה גם מהאור שנתעלם כו' (וא\"ז בחי' פנימי' הקו כ\"א מה שבחיצוני' הקו יש בזה מהאור המתעלם כו' וכמ\"ש במ\"א (ועמשנת\"ל פקל\"ז)), והוא מבחי' האור דא\"ס השייך אל העולמות כו'). והב' בחי' ההסתר וההעלם שבעצמות ממש ולא לגבי המקבלים בלבד שעז\"א ג\"כ ישת חשך סתרו, אבל סתר זה\nהוא מצד העלם העצמות ממש שלא בא לגילוי כלל כו'. וזהו ג\"כ ענין ח\"ס דכולל ב' מיני סתימות הנ\"ל, הא' סתימות לגבי המקבלים שלא ישיגוהו שאז יוכל לבא לפרקים בגילוי אפס קצהו עכ\"פ כו', ויוכל להתגלות גם העומק בזה וכמו בחי' תעלומות חכ' כו' כנ\"ל, והב' בחי' הסתימות שמצד העלם העצמי (שהוא כמו בחי' עתיק ממש) שהוא סתום מצ\"ע שלעולם א\"א שיבא לידי גילוי כו' (והגילוי בזה הוא שההעלם העצמי בא לידי גילוי כו', שזהו למע' מענין הגילוי שהוא שמתגלה רק הארה ושלפ\"ע המקבלים היינו מה שהמקבלים כלים לזה כו', וכאן הגילוי הוא העצמי ולא שהמקבלים כלים לזה רק הוא בכח העצמות כו', והו\"ע מתן בסתר יכפה אף, דמתן בסתר הוא גילוי בחי' הסתר והסתימות שמצ\"ע, וע\"כ יכפה כו' דכל בתי דינין אתכפיין קמי' לגבי גילוי העצמות כו').\n<b>וע\"פ</b> הנ\"ל יובן משארז\"ל העושה סוכתו תחת האילן כו', דהנה סוכה בחי' מקיף, אך זהו בחי' המקיף דאו\"ח שמאיר בגילוי, וכנודע דמקיף דסוכה הוא מענן הקטרת דיוהכ\"פ דכתיב בו כי בענן אראה, אראה בעצמותי כו', שזהו שממשיכים"],[3601330601,"ע\"י התשו' מעומקא דלבא שמעורר וממשיך בחי' עצמו' א\"ס בחי' העלם העצמי שז\"ע הענן כו', ועז\"א כי בענן אראה בעצמותי כו', דהגילוי הוא בסוכות כו'. וז\"ש תקעו בחדש שופר בכסה ליום חגינו דע\"י תקיעת שופר ממשיכים בחי' עצמות א\"ס, וז\"ע בנין המל' בר\"ה שממשיכים מבחי' העצמות להיות רצון למלוכה, והו\"ע המלך הקדוש שקדוש מצ\"ע והוא בחי' העלם העצמי שסתום בעצם כו', וממשיכים משם הרצון למלוכה ע\"י תקיעת שופר שהו\"ע קבעומ\"ש ותשו' כו', וכן ע\"י תשו' דיוכ\"פ שז\"ע בכסה מה שמכוסה ונעלם בעצם כו', והגילוי הוא ליום חגינו בסוכות כו' (דבסכך הסוכה הוא בבחי' מקיף, וע\"י הד' מינים שבלולב נמשך בבחי' פנימי' וכמ\"ש ולקחתם לכם כו'). וע\"כ העושה סוכתו תחת האילן כו', דאילן הוא ג\"כ מקיף אבל זהו בחי' מקיף דאו\"י וא\"ז ההמשכה האמיתי' דמקיף דסוכה כו', ורק למלאכים הי' מספיק סוכה כזו להיות דמלאכים הן בעולם הבריאה וע\"כ בחי' המקיף דאו\"י הוא בבחי' סוכה להם כו', אבל גבי נשמות ענין הסוכה הוא המשכת המקיף דאו\"ח כו', ועם היות דמצות סוכה היא בזכות והשענו\nכו', מ\"מ ה\"ז למע' הרבה כו', וע\"כ העושה סוכתו תחת האילן כאלו עשאה בתוך הבית להיות שזהו מקיף דאו\"י השייך לגילוי ובא לידי גילוי כו', ועיקר ענין הסוכה היא שהמקיף דאו\"ח שסתום בעצם ה\"ז בא בבחי' גילוי כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ומקיף דאו\"ח הוא שאדרבא מתעלם בעצמו מפני שהוא העלם בעצם, וכמו הקץ שנראה אדרבא ההיפך, דמב\"ד יבוא בהיסח הדעת, וכמו משלי שלמה, דכמו שטבע הגילוי להתגלות כך טבע ההעלם להתעלם, ולמעלה ישת חשך סתרו, ומתגלה הארה, מגלה עמוקות מני חשך, גילוי הקו ויש בו מאור הא\"ס, ומקיף דאו\"ח בחי' העלם עצמי, וכשנמשך הוא שהעצם נמשך, מתן בסתר. וזהו העושה סוכתו תחת האילן פסולה, כי אילן מקיף דאו\"י, וסוכה מקיף דאו\"ח הנמשך לנש\"י ע\"י התשובה.</span>"],[3601330602,"<h3>בס\"ד. שחהמ\"ס, תרד\"ע</h3>\n<b>הללו</b> את ה' כל גוים כו' כי גבר עלינו חסדו, וצ\"ל מהו הנתינת טעם דכי גבר עלינו חסדו דמשו\"ז הללו ה' כל גוים דלכאו' א\"ז טעם מספיק ע\"ז כו', ומהו\"ע ההילול והשבח שלהם כו'. גם צ\"ל מה שבחה\"ס הקריבו ע' פרים נגד ע\"ש מהו\"ע הקרבה הזאת, ומפני מה בחה\"ס דוקא. ולהבין זה צלה\"ק משנת\"ל שיש ב' מדרי' בח\"ס חיצוני' ופנימי' והו\"ע מקיף דאו\"י ומקיף דאו\"ח, דמקיף דאו\"י הוא שסתום רק לגבי המקבלים אך הוא בבחי' שייכות להם כו', ומקיף דאו\"ח הוא שסתום בעצם ואינו בבחי' שייכות אל המקבלים כלל כו'.\n<b>רח)</b> וע\"פ הנ\"ל יובן משנת\"ל פר\"ד דהתהוות החכ' מבחי' ח\"ס הוא מבחי' שערות לבד והו\"ע דאבא יונק ממזלא מזל ונוצר כו', ונת' הקושי' ע\"ז"],[3601330603,"שהרי במזל ונוצר מאיר בחי' עצמו' ח\"ס בחי' השמן הטוב דעתיקא ולכן היגת\"ד הן מקור הסליחה כו', ואיך הוא בבחי' מקור לחכ' כו'. והענין הוא דהנה הרמ\"ז פ' בא ד\"מ ע\"ב כ' דבמזל ונוצר יש בו פנימי' וחיצוני' ובתוך פנימיותו הוא פנימי' עתיק כו', ולפי הנ\"ל י\"ל דבכללות מזל ונוצר (וכן כל היגת\"ד) הן מבחי' ח\"ס רק שיש בזה פנימי' וחיצוני' הנמשך מב' המדרי' שבח\"ס שנת\"ל, דהחיצוני' דמזל ונוצר הוא מבחי' חיצוני' ח\"ס שבבחי' מקור לחכ' כו', ובחי' הפנימי' דמזל ונוצר הוא שנמשך מבחי' פנימי' דח\"ס שסתום בעצם כמו עצמי' עתיק כו', ומשם נמשך ג\"כ מוחין אלא שהן מוחין גבוהים ונעלים ביותר כו'. והענין יובן עפמ\"ש במ\"א שיש בחי' המשכה שבס' השתל' ויש המשכה הבאה ממקום גבוה מאד למע' מס' ההשתל' כו' (והכל הוא בבחי' או\"פ כו'), והיינו שסדר והדרגת ההשתל' הוא מהחכ' דאצילות לבינה ומבינה לז\"א בדרך עו\"ע, והו\"ע השתל' הספי' בספי' עצמן שהן בבחי' עו\"ע כו', וגם מה שהחכ' מקבלת מהכתר ג\"כ נק' ס' השתל', הגם דקבלת החכ' מהכתר הוא רק מבחי' שערות דא\"א דאבא\nיונק ממזלא כו', שהשערות הוא רק מותרי מוחין ומזה לבד נמשך בחו\"ב ולא מהכתר עצמו ממש, וא\"כ אינו כמו מהחכ' לבינה ומהבינה למדות, שעצמי' החכ' נמשך ומתלבש בהבינה וכן מבינה למדות כו', שהרי בלא התבוננות השכל לא יהי' לידת המדות כ\"א ע\"י התבוננות דוקא שכ\"ה במדות דתיקון כו', א\"כ הרי במדות יש בהם מן השכל כו' (וע\"ה שזהו הארה לבד מ\"מ הרי ההארה הוא הארת המוחין ממש כו', וכמו נקודת ההשכלה ה\"ה שכל ממש שמתלבש בהשגה כו', וכן מבינה למדות נמשך הארת השכל כו', ולעיל מפ' קמ\"ה ואילך נת' שיש בזה חילוקי מדרי' כו', והיינו שבהשתל' הספי' שלצורך הברי' לא יש ממהות העילה בהעלול כו', אבל במדרי' אצי' גופא הרי יש מהות הארה מהעילה בהעלול כו'), ולפיכך נק' השתל' עו\"ע כו', משא\"כ מהכתר אל החכ' שההמשכה הוא בבחי' שערות לבד ה\"ז רק הארה דהארה כו'. אך אעפ\"כ גם התהוות החכ' מהכתר נק' המשכה שבס' השתל', אלא שכך הוא ההדרגה של ס' השתל' להיות החכ' נמשכת רק מבחי' שערות לבד דא\"א כו' (והיינו שכ\"ה שנמדד תחלה ברצונו ית' באופן ההתהוות דס' השתל'\nשהחכ' תהי' המשכתה והתהוותה מבחינת שערות כו', וא\"כ מה שנתהווה החכ' מבחי' שערות א\"ז מפני שהוא מהאור שלמע' מגדר השתל', מאחר שמתחלה עלה כן ברצה\"פ בהתהוות ההשתל' וידוע דכללות האור דעליית הרצון הוא מה ששייך להשתל' כו', וכך עלה ברצונו ית' באופן ההשתל' דהתהוות החכ' יהי' מבחי' שערות, הרי כ\"ז הוא הדרגת ההשתל' כו' היינו שאין מקור ההמשכה מבחי' שלמע' מהשתל', וכללו' ההמשכה היא ע\"פ רצונו ית' בענין ההשתל' כו'). אבל ההמשכה הבאה מלמע' מס' השתל' היינו מה שנמשך מבחי' עתיק וממו\"ס שהוא פנימי' הכתר כו' (והוא מה שנמשך בבחי' תוס' אור בבחי' התחדשות שלא הי' תחלה בעליית הרצון על ס' ההשתל' דע\"ס כו'), והוא הנמשך ע\"י העלאת מ\"ן בתשו' מעומקא דלבא שעי\"ז ממעמקים קראתיך מבחי' עומק לעומק כו', והיינו שעי\"ז ממשיכים ממקום גבוה מאד שלמע' מהדרגת ההשתל', אך מ\"מ גם המשכה זו מוכרח ג\"כ לירד דרך הצנורות והשערות דיגת\"ד, ואעפ\"כ נק' זה למע' מס' השתל' כיון ששרש המשכה זו הוא מרדל\"א וממו\"ס כו'."],[3601330604,"<span data-k=\"ks\"><b>קיצור.</b> וזהו דהתהוות החכ' הוא מבחי' שערות דמו\"ס, דהנה מזל ונוצר יש בו פנימיות וחיצוניות, ומשם נמשכים ב' בחי' מוחין, דהנה השתל' הספי' הוא בבחי' עו\"ע, גם מהכתר לחכ' שהוא בדרך שערות, שזהו רק הארה לא הארה עצמיות כמו מחכ' לבינה ומבינה למדות, מ\"מ ג\"ז הוא סדר השתל', מפני שכן נמדד בעליית הרצון בתחלה, ויש מוחין דלמעלה מהשתל', והיינו שלא נמדד בעליית הרצון, ונמשכים ג\"כ דרך השערות.</span>\n<b>רט)</b> והענין הוא דהמשכה שע\"פ ס' השתל' היא מבחי' א\"א שרש הנאצלים שזהו מה ששייך אל הנאצלים, וכנודע דא\"א הוא בחי' רצון והיינו רצונו ית' באופן ההשתל' (ובשרשו הוא בחי' הרצון פשוט דאוא\"ס ב\"ה שעלה ברצונו להאציל ולברוא כו'), ומ\"מ להיותו רק שרש הנאצלי' ע\"כ א\"א שיומשך ממנו בחכ' רק ע\"י בחי' שערות לבד ולא כמו מחכ' לבינה שהוא דרך עו\"ע כו', והגם דאו\"א ג\"כ מלבישים לזרועות דא\"א שזהו המשכה שלא ע\"י שערות כו', זהו מבחי' ז\"ת דא\"א אבל מג\"ר דאריך אין נמשך רק ע\"י בחי' שערות לבד כו', ומ\"מ נק' המשכה זו ס' השתל' ע\"ש דההמשכה היא מבחי' א\"א שהוא במנין ע\"ס והוא שרש הנאצלי' כו'. והנה המשכת השערות הן ממו\"ס אך זהו מבחי' חיצוני' דח\"ס היינו מה שהוא מקור לחכ' והיינו בחי' הסתום שלגבי מקבלים כו', וע\"כ המשכה זו הגם שהיא ע\"י שערות ה\"ז בחי' ס' השתל' כו'. אמנם ההמשכה שלמע' לגמרי מס' והדרגת ההשתל' הוא מה שנמשך מבחי' רדל\"א שאינו במנין הע\"ס דאנת הוא חד ולא בחושבן כו', וגם המשכה זו (הגם שזהו המשכה שלא ע\"י הדרגת ההשתל')\nמוכרח לירד ולימשך דרך הצנורות וחלל השערות, כי בחי' עתיק ומו\"ס עצמן דהיינו בחי' פנימי' מו\"ס שהוא מוחא דעתיקא שסתום מצ\"ע כו'. כנ\"ל א\"א שיבאו לידי גילוי רק ע\"י שעובר ונמשך דרך יגת\"ד שמתצמצם בחלל השערה כו'. והגם דהמשכה זו אינו שנמשך רק הארה לבד (כמו ההמשכה דמבחי' חיצוני' הכתר בחכ' דרך השערות כו') כ\"א שנמשך בחי' העצמות כו', וכנודע דכ\"ה ההמשכה דבחי' פנימי' שהעצמי' נמשך כו', דזה ההפרש בין ההמשכה דחיצוניות להמשכה פנימי', דבחי' חיצוני' האור להיות שהוא בבחי' שייכות להשתל' (והיינו דעצם האור הוא בחי' הארה לבד כו') ע\"כ ההמשכה משם הוא רק הארה לבד כו', ופנימי' האור (שהוא אור עצמי) שמובדל בערך מהשתל' ההמשכה הוא שעצם האור נמשך כו' (ויסוד ושרש הדבר הוא לפי שהוא למע' מבחי' העלם וגילוי כו', דהאור שהוא בחי' הארה לבד שייך בו העלם וגילוי כו', אבל אור עצמי אינו שייך בו העלם וגילוי ונמשך כמו שהוא בעצם כו'). ומ\"מ צ\"ל ההמשכה דרך מעבר השערות כו', וע\"ד מ\"ש באגה\"ק בקו\"א ד\"ה להבין מ\"ש בפע\"ח בענין ההמשכה דיו\"ט שזהו\nמחסד דאצי' בבחי' התלבשות חסד דברי' בדרך מעביר חסד דיצי' ועשי' שאל\"כ הי' פועל בעוה\"ז כו', הרי ההמשכה היא מבחי' חסד דאצי' וחסד דברי' (בבחי' נשמה כו'), ואין המעבר פועל בזה שום שינוי כו', ומ\"מ פועל המעבר שעי\"ז יוכל להתקבל האור למטה כו'. וכמו\"כ בהמשכה פנימי' הנ\"ל שבכדי שיוכל להתקבל בהנאצלים צ\"ל ההמשכה דרך צנורות השערות כו', אך ההמשכה היא מבחי' עתיק ממש כו'. וזהו מ\"ש ממעמקים קראתיך מעומק לעומק היינו מבחי' עתיק שהוא בחי' עומק לגבי אריך וכמו סדכ\"ס כו', וגם פי' מעומק לעומק היינו ממו\"ס ומרדל\"א שמשם"],[3601330605,"ממש הוא ההמשכה כו', וע\"כ נמשך משם סליחת עוונות, דהרי המצות הן מבחי' גולגלתא דאריך כו' וכאשר ממשיכים מבחי' מו\"ס ורדל\"א נמשך משם להיות נושא עון כו'. ונמצא שיש ביגת\"ד ב' מדרי' הא' נק' סדר השתל' והן שנמשכים מבחי' א\"א ומו\"ס שרש הנאצלים כו', והמשכתן מבחי' מו\"ס הוא מבחי' מותרי מוחין ונמשך רק הארה לבד כו', והב' בחי' הפנימי' דיגת\"ד שנמשכים מרדל\"א ומו\"ס מבחי' העצמות דמו\"ס לא רק בחי' מותרות לבד כו', רק שעובר ונמשך דרך חלל צנורות השערות כו', והמשכה זו גדולה ועצומה למלאות כל הפגמים לפי שהיא המשכה מבחי' אנת הוא שלימותא דכולהו ואנת הוא ממלא כל שמהן כו', דלהיותו בבחי' שלמות בעצם ע\"כ הוא ממלא כל שמהן כו', וז\"ע כשמן הטוב על הראש יורד על הזקן, דשמן הטוב הוא פנימי' עתיק ונמשך במו\"ס דעתיקא וממו\"ס נמשך בחי' העצמו' דרך חלל השערות כו', ובכדי להמשיך מבחי' יגת\"ד בשרש המשכתם מבחי' עצמו' מו\"ס זהו שממשיכים ע\"י התשו' כו'.\n<span data-k=\"ks\"><b>קיצור.</b> דהנה המשכה דס' השתל' הוא מא\"א שהוא הרצון על האצי', שההמשכה היא רק הארה (מפני שגם העצם הוא רק הארה), ולהיותו רק שרש לנאצלים, צ\"ל ע\"י שערות שנמשכים מחיצוניות מו\"ס, ולמעלה מהשתל' הוא ההמשכה מרדל\"א והוא שהעצם נמשך (מפני שזהו למעלה מהעלם וגילוי), וצ\"ל ג\"כ דרך מעביר השערות, שע\"י המעביר יוכל להתקבל למטה, והוא בחי' פנימיות יגת\"ד בכלל ומזל ונוצר בפרט שנמשך מעומק לעומק פנימיות עתיק ומו\"ס, והוא בחי' שמן הטוב.</span>\n<b>רי)</b> ולהבין ב' מיני המשכות הנ\"ל, ילה\"ק מ\"ש שמן וקטרת ישמח לב, ואי' בבחיי ר\"פ תצוה בשם המדרש שמן המנורה שהי' מתקרב בזמן הקטרת שנא' ובהעלות אהרן את הנרות בין הערבים יקטירנה משמח לבו של הקב\"ה כו', וא\"כ קאי על הקטרת הקטורת שבכ\"י על המזבח הפנימי שנמשך עי\"ז שמן המנורה, וידוע שהי' עוד עבודה בקטרת דיוהכ\"פ לפני ולפנים, וצ\"ל שעי\"ז ממשיכים ודאי בחי' השמן רק צ\"ל שזהו למע' מבחי' שמן המנורה כו', וא\"כ צ\"ל שיש ב' מדרי' בקטרת וב' מדרי' בשמן כו'. ולהבין זה צ\"ל תחלה ענין הקטרת, והנה אי' בפע\"ח די\"א סממני הקטרת הן עשר ניצוצי הקדושה של או\"פ המחי' את הקליפות ויש ניצוץ א' של אור מקיף כו', והו\"ע י\"א כתרין דמסאבותא כו' (ונר' דהיו\"ד ניצוצות הן בבחי' או\"פ בהם וכ\"ה בשער הכוונות, אך עיקר החיות שלהם הוא מהאו\"מ, וכשמסירים האו\"מ ה\"ה מתים ומתבטלים וכמ\"ש בפע\"ח שער העשי' רפ\"ד, וצ\"ל מפני שהאו\"פ הוא בבחי' בליעה בהם וע\"כ אינו בבחי' חיות להם כ\"א האו\"מ כו'). והנה הטעם מה שבקדושה הם ע\"ס דוקא ואי' בס\"י עשר ולא תשע ולא\nי\"א, ובסט\"א הן י\"א כתרין, הוא מפני שבקדושה הנה החיות שמחי' את הע\"ס הוא בתכלית היחוד עם הספי' כו', וכמא' וההוא נביעו איהו כנשמתא לגופא כו', דגופא הן הספי' שהן הכלים, וכמש\"א לפני זה וכמה גופין תקינת לון כו' חסד דרועא ימינא כו', ואור הקו המתלבש בתוכם הוא בחי' הנביעו שהוא כנשמתא לגופא כו'. ועד\"מ הנשמה המתלבשת בגוף הרי ע\"ה שהנשמה עם הגוף הם שני דברים שהם מרוחקים זמ\"ז תכלית הריחוק, מ\"מ הרי אור הנפש מתלבש בהדם ומתייחד עמו בהתאחדות"],[3601330606,"ממש עד שהדם נק' נפש וכמ\"ש כי הדם הוא הנפש, דהיינו מצד עוצם התאחדו' הנפש בהדם כו', ועי\"ז הוא התאחדות הנפש עם הגוף בכלל, ושניהם יחד נק' אדם דאדם הוא א' דם, דהא' הוא החיות ועם הדם יחד נק' אדם, וכן בד\"כ הנשמה עם הגוף נק' אדם, דהגוף בפ\"ע נק' גוף האדם וכן הנשמה בפ\"ע נק' נשמת האדם, ובהתכללות שניהם יחד נק' אדם כו'. ועד\"ז יובן למע' בבחי' אדה\"ע דאצי' דהגם שאין לו דמות הגוף ולא גוף מ\"מ דברה תורה כלשון בנ\"א וכמ\"ש ועל הכסא דמות כמראה אדם עליו מלמע' שזהו בחי' דמות ומראה לבד כו', דבחי' גופין הן הכלים דאצי' שנק' גרמוהי דפי' עצמות שזהו עיקר הגוף וכמשנת\"ל פקנ\"ג, ובפרט הן בחי' האברי' דז\"א דשם עיקר הכלים כנודע, וההוא נביעו איהו כנשמתא כו' הוא בחי' אור הקו בכלל המתלבש בהע\"ס כו', ובד\"פ הוא בחי' חו\"ב שזהו בחי' החיות דז\"א וכמ\"ש והחכ' תחי' וכן בינה נק' אלקים חיים כו'. וזהו בחי' א' דם דאהי' בריבוע גימט' דם שזהו מבחי' הבינה כו' וכמשנת\"ל פקפ\"א, ועיקר החיות הוא מבחי' החכ' שזהו הא' שבאדם כו' (ולעיל שם נת' שזהו המים\nשעושה התפשטות הדם כו', וכן גבי ההוא נביעו נא' כמיא דאשקי לאילנא כו'), וכללו' שניהם נק' אדם כו' (ובפרטו' הן ב' מיני חיות כו' דהחיות דבינה הוא להיות בחי' המציאות והחיות דחכ' הוא להיות ביטול המציאות כו' וכמ\"ש במ\"א, ועמ\"ש בלק\"ת בהבי' דבשעה שהקדימו ועמשית\"ל פ'), וזהו בחי' אדם פנימי שהוא בחי' האור והחיות כו', ובהתלבשות האור והחיות בכלים ואברים דז\"א נק' בחי' אדה\"ע ע\"ש התכללות דאורות וכלים דשניהם יחד דוקא נק' בש' אדם כו', והיינו מפני שהאור והחיות מתייחד עמהם ביחוד גמור עד שהם דבר א' ממש, וכמא' איהו וגרמוהי חד שהן בבחי' חד ממש כו'. והגם שאינו דומה להיחוד דאיהו וחיוהי וגם בחי' האיהו שמתייחד עם גרמוהי א\"ז בחי' ומדרי' זו עצמו דבחי' איהו שמתייחד עם חיוהי כו', וכמשנת\"ל פקנ\"ה שזהו בחי' האור המתלבש כו', והיחוד הוא רק לענין ההתהוות כו', שא\"ז יחוד עצמי כ\"א לצורך איזה פעולה היינו לפעול פעולת ההתהוות כו' (וי\"ל דבכלים גופא היחוד בבחי' פנימי' הכלים זהו בחי' אדם א' דם כו', והוא בחי' אדם פנימי כו' והוא מהן\nבעצם כלים לקבל כו', והיחוד הנ\"ל הוא בבחי' חיצוני' הכלים ואברי' דז\"א והוא לצורך ההתהוות כו', ולפ\"ז הוא בחי' הארת איהו לבד כו' וכמ\"ש במ\"א). ומ\"מ הרי האור מתייחד ממש עם הכלים כו', עד שגם הכלים הן בבחי' קיום עצמי מצד יחוד האור שבהם כו' וכמ\"ש במ\"א שז\"ע הוא קיים ושמו קיים וכסאו נכון, דגם הכסא שהן הכלים שהם בבחי' מכון לשבתו ית' ה\"ה בבחי' קיום בעצם כו' (וכמו בנשמו' דכתי' ואתם הדבקים כו' חיים כולכם כו' שהם בבחי' חיות עצמי לפי שהן דבקים בה' כו', וכ\"ה בבחי' הכלים כו' וכמ\"ש בד\"ה וביום שמחתכם, רנ\"ו). וכמו עד\"מ באדם למטה הרי הגוף הוא חי בעצמו לא רק מה שנמצא בו דבר חיוני כ\"א שהוא עצמו חי, ולא כמו הלבוש שבשעה שהאדם לבוש בו ה\"ה מתנענע שזהו רק מפני שהאדם החי מלובש בו, אבל בגוף הרי אינו באופן כזה כ\"א שהגוף עצמו חי ע\"י הנפש (ובגוף הרי מצ\"ע אינו מציאות חיוני כלל אדרבה הוא מציאו' מות מצ\"ע כנודע ומבו' במ\"א, ומ\"מ בהתלבשות הנפש בו ה\"ה בעצמו חי כו'), והיינו מצד התאחדו' הנפש בו כ\"כ בבחי' פנימי (היינו בבחי' התגלות\nובבחי' התאחדות כו') עד שהגוף עצמו חי כו'. והדוגמא מזה למע' שהכלים הן בבחי' קיום עצמי מצד התלבשות האור בהם שהוא בבחי' התאחדות ממש כו'. ובאמת יחוד האורות עם"],[3601330607,"הכלים הוא יותר מיחוד והתחברות הנשמה עם הגוף, שהרי לדעת המערכת והעה\"ק הע\"ס הן עצם אלקו' ממש, והיינו שגם הכלים הן בחי' אצי', וא\"כ ה\"ה מהות א' ממש עם האורות וא\"ז כלל כמו שני דברים המתייחדים כו', וי\"ל דלשטה זו ענין הכלים הוא רק התגלות האור כו', והרי הגילוי אינו מהות אחר מן העצם כו'. וענין ההתגלות י\"ל בב' אופנים, הא' שהוא ע\"ד בחי' המל' שהו\"ע הגילוי, וכנודע דהספי' שלמע' מבחי' המל' הן בבחי' דבקות במקורם והגילוי הוא בחי' המל' כו' וכמשית\"ל, ועד\"ז הו\"ע הכלים לשטת המערכת, רק דבחי' מל' ה\"ה בחי' נבדלת מטעם זה (וצ\"ל שיש בזה ג\"כ ההפרש בין המל' שהיא ספי' בפ\"ע ובין בחי' המל' שבכל ספי' כו'), אך לשטת המערכת צ\"ל שזהו ע\"ד כמו בחי' המל' בהיותה כלולה עדיין בבחי' הז\"א כו' (ועמ\"ש הפרד\"ס בענין יסוד העפר כו'). והאופן הב' הוא שענין ההתגלות היינו הגלמת האור להיות האור בבחי' מציאות כו', ולשני האופנים אין הכלים בבחי' מציאות דבר בפ\"ע וה\"ה חד עם האור כו'. ובאמת לדעת המערכת אינם בבחי' כלים כלל כ\"א הע\"ס הן בחי' עצמו' לבד\nוהיחוד הוא בעצמות המאציל כו', אך לפ\"ז ודאי היחוד אינו כמו שני דברים המתייחדים דע\"ה שרחוק ערך האור והגילוי לגבי בחי' עצמות המאציל מ\"מ ה\"ז הארת המאציל כו' (ובחי' המאציל זהו בחי' חיצוני' האור השייך אל הנאצלי' כו'). וגם לדעת הפרד\"ס שהע\"ס הן בבחי' עצמות וכלים, מ\"מ אין הכלים לגבי האורות כערך הגוף לגבי הנפש שהוא מהות אחר לגמרי (והוא מהות הפכי באמת כנ\"ל), משא\"כ הכלים ה\"ה אלקות ממש רק שזהו בחי' כח הגבול שבא\"ס כו', וגם לדעת רבינו באגה\"ק שהן בחי' גבול כו' וכמ\"ש במ\"א, מ\"מ ה\"ה בבחי' אחדות ממש עם האור כו', וע\"כ הן במספר עשר דוקא להורות שהן בבחי' אחדות כו', וז\"ש עשר ולא י\"א שלא להפריד ח\"ו בין הכלים והאורות דבאמת הן מיוחדים כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ובה\"ע יקדים מ\"ש שמן וקטרת שיש ב' מדרי' בשמן וב' מדרי' בקטרת, דהנה י\"א סממני הקטרת הן נגד י\"א כתרין דמסאבותא ובקדושה דוקא ע\"ס, כי האורות מתאחדים עם הכלים, וכמו גוף ונפש שהנפש מתאחד עם הדם והגוף ושניהם נק' אדם, והגוף חי בעצם מהנפש, וכמו\"כ למעלה כלים גופא ואורות נשמתא, והוא בחי' אדה\"ע, א' דם, דם בינה, א' חכ' שהוא עיקר האור, ומתייחדים עם הכלים, איהו וגרמוהי חד, שהכלים הן ג\"כ בבחי' קיום עצמי, וביותר מגוף ונפש שהרי הכלים הן אלקות, ולדעת המערכת י\"ל שהן רק גילוי האור, כמו בחי' מל' הכלולה בז\"א, או רק הגלמת האור, וי\"ל לשיטתו הע\"ס הן עצמות לבד, וגם לדעת הפרדס הן אלקות, ולהאגה\"ק אלקות וגבול, ולכן הן ע\"ס האורות והכלים יחד.</span>\n<b>ריא)</b> אך בסט\"א אין החיות שלהם בבחי' התאחדות עמהם, דהרי סט\"א אינם כלים לאור אלקי כלל וכלל, דהנה ידוע דהכלי לאלקות הוא הביטול דוקא דמה שבטל לאלקות ה\"ז כלי לאלקות כו', וזהו הכלל בסט' דקדושה שהן בבחי' ביטול וע\"כ הן בבחי' כלים לאור אלקי כו', ולא מיבעי הכלים דאצי' שהן אלקו' ממש (והביטול שבהם הוא בבחי' ביטול דיחו\"ע כו' וכמ\"ש במ\"א וכמשי\"ת), אלא גם בכללות סט' דקדושה דהכל הוא בבחי' ביטול, ע\"כ הם כלי לאלקו' שהאלקו' מתלבש בהם בבחי' פנימי' ומתייחד עמהם כו', משא\"כ הסט\"א שנק' סט\"א מפני"],[3601330608,"שהן צד אחר שאינו צד הקדושה, והיינו שאין בהם ביטול ואדרבה הן בתכלית הישות והגסות ודבר נפרד לגמרי שהפרידן מאחדותו ית' כו', וכמו פרעה שא' אני ואפסי עוד, לי יאורי ואני עשיתיני כו', שזהו תכלית ההסתר שעי\"ז הוא הגסות שבהם עד שא' מי הוי', לא ידעתי את הוי'. והנה גם בחי' זו בהכרח שיומשך להם חיות מאוא\"ס ב\"ה, דאל\"כ לא הי' שום מציאות כלל (וי\"ל דהחיות שלהם הוא רק לקיום מציאותן דגם מה שהן חיים א\"ז בבחי' חיות דהיינו בבחי' אור וגילוי כו', וגם כמשי\"ת בסמוך שאינם בבחי' חיות עצמי כו' רק מה שנמצאים במציאות כו'), וכמ\"ש ואתה מחי' את כולם גם הקלי' וסט\"א כו', רק שאם הי' חיותם נמשך להם בקירוב הי' נבלע בהם וכמ\"ש נבלע ישראל כו', ולא הי' בהם בבחי' חיות כלל, וכמו ותבלענה ז' פרות כו' ולא נודע כי באו אל קרבנה כו' שלא נעשה להם מזה שום חיות כו'. ובע\"ח כ' הטעם מפני שאין הקדש מתערב בחול כו', והיינו ג\"כ כנ\"ל דמפני שאין בהם ביטול ע\"כ אין החיות בהם בבחי' התערבות כו', דענין ההתערבות הוא שמתחברים ומתאחדים זע\"ז, דהיינו בבחינת\nהתלבשות פנימי שמאיר בהתגלות ומתאחד כו', משא\"כ בסט\"א אינו בבחי' התערבות כ\"א או שעומד עליהם מובדל מהם או שהוא בבחי' בליעה בהם שהו\"ע הגלות כו' וכמ\"ש במ\"א, ולכן בכדי שלא יובלע בהם החיות דקדושה עומד החיות המחי' אותם בבחי' מקיף על ראשם ומאיר להם מרחוק ואינו מתאחד עמהם כו', וכמ\"ש בע\"ח שער יו\"ד הוא שער המלכים פי\"א. ולכן באמת גם בעת חיותם אינם בבחי' חיים באמת אדרבה הן בעצם בבחי' מות ובבחי' העדר כו', וכמ\"ש במ\"א בענין הנסיונות שאינם דבר אמיתי מצ\"ע כ\"א מה שהועמד דבר להעלים ולהסתיר ולהיות מונע כו', וכשעומדים נגד זה ה\"ה מתבטל לגמרי כו', וכמ\"ש בד\"ה וביום שמחתכם הנ\"ל. ומשו\"ז יש צד מעלה בנסיונות שכאשר עומדים נגד זה ה\"ה מתבטל לגמרי והי' כלא הי' כו', דעם היות שהנסיון הוא לכאורה דבר חזק וכבד לעמוד נגדו וצריכים לזה כח חזק כו', מ\"מ כאשר מתגבר בכחו ועומד נגד הדבר נסיון ה\"ה מתבטל לגמרי ולא נשאר מזה מאומה כו', משא\"כ בדבר חומרי שאינו דבר נסיון צריכים לזה ריבוי עבודה לבטל כו', וע\"ה שא\"ז דבר חזק כ\"כ מ\"מ אינו מתבטל\nג\"כ, שגם אם כופה א\"ע וגם ע\"י עבודה שפועל חלישות כו', מ\"מ אינו מתבטל לגמרי כו', אבל הנסיון כשעומדים כנגד מתבטל לגמרי כו', והיינו מפני שהוא מציאות העדר שאין בו חיות פנימי כלל רק בבחי' מקיף לבד כו', וע\"כ הם במספר י\"א מפני שהחיות נחשב לדבר בפ\"ע ע\"כ הם במספר י\"א, והיינו היו\"ד כתרין שהן הע\"ס דנוגה (ובזה יש ג\"כ עשר ניצוצות דקדושה כנ\"ל, אך אינם בבחי' חיות להם כו'), ובחי' הי\"א שהוא המקיף דלבונה זכה שזהו עיקר החיות שלהם שעומד בבחי' מקיף עליהם כו', וע\"ז הו\"ע י\"א סממני הקטורת להעלות ולברר הי\"א כתרין כו'. והנה בנה\"א ונה\"ב הרי הנה\"א מתלבש בהנה\"ב שמק\"נ ואינו עומדת על ראשו בבחי' מקיף לבד כ\"א מלובש בו בבחי' או\"פ ממש, שהרי הנה\"ב פועל בהכחות דנה\"א שבאים בהגשמה ע\"י התלבשות זאת להשכיל השכלות גשמי', ובכלל ההשגה היא בהגשמה שא\"ז כלל כמו השגת הנה\"א בעצם כו', ולהיפך הנפה\"א פועל בהנה\"ב שגם הוא יבין ענין אלקי ויתברר עי\"ז כו', שכ\"ז הוא מפני שבא בהתלבשות כו', הרי הגם שהנה\"ב הוא מנוגה ונה\"א הוא בתכלית הקדושה, ה\"ה\nבבחי' התלבשות ואינה נבלעת בו ח\"ו אדרבה יש בכחה למשול עליו ולהכניעו תחת ממשלתו כו'. וצ\"ל שזהו בעוה\"ז דוקא שמצד מדרי' הסוכ\"ע שנמצא דוקא בעוה\"ז יכול להיות"],[3601330609,"התלבשות כזאת דהיינו התחברות טו\"ר כו', אבל למע' אין הקדש מתערב בחול ועומד רק בבחי' מקיף כו', רק למטה יכול להיות התחברות הנה\"א והנה\"ב ע\"י אוא\"ס הסובב כו', אך זהו בהעלם כו'. אמנם יש ג\"כ גילוי הסובב למטה שממשיכים ע\"י המצות וכנודע שהמצות הן רצה\"ע ונמשך ע\"י גילוי בחי' אוא\"ס הסובב כו', והמצות יש בהם סגולה פרטי' להעלות ולקשר הנה\"ב לאלקות כו', וכמו\"כ המשכת גילוי הסובב שע\"י רעו\"ד כמשי\"ת שעי\"ז הוא עיקר בירור הנה\"ב בבחי' אתהפכא חשוכא לנהורא כו' וכמשי\"ת, וכ\"ז הוא ע\"י הנה\"א דוקא שאם הי' הגילוי להנה\"ב הי' מתבטל לגמרי לא בדרך בירור כו' (וכנודע בענין הברכות דיצחק כו'), מפני שאינו כלי לאלקות כו', רק ע\"י הנה\"א דוקא הוא הבירור דהנה\"ב כו'.\n<b>וע\"פ</b> הנ\"ל יובן ענין הקרבת הע' פרים בחה\"ס שזהו בירור הע\"ש דנוגה כו'. דהנה ידוע דמקיפים דסוכות הן מהענן הקטרת דיוהכ\"פ שזהו בירור הי\"א כתרין כו', וית' לקמן דקטרת דיוהכ\"פ הוא עוד בירור עליון יותר כו', וכת' כי בענן אראה אראה בעצמותי כו', ונמשך בבחי' מקיף בסכך הסוכה כו' (וע\"י הד\"מ שבלולב נמשך בפנימי' וכמ\"ש ולקחתם לכם כו'), ובכח המשכת המקיף מבררים את הע\"ש למטה כו'. וזהו הללו את ה' כל גוים כו', וקאי על הנה\"ב שגם הנה\"ב יתברר ויהי' בבחי' אה' לאלקות כו', וזהו ע\"י כי גבר עלינו חסדו בבחי' גילוי המקיף כו', שהגילוי הוא לנה\"א, וזהו כי גבר עלינו דוקא, והנה\"א הוא שמברר את הנה\"ב כו', וזהו הללו את ה' כל גוים להיות כי גבר עלינו חסדו בחי' גילוי המקיף עי\"ז גם הנה\"ב יהלל וישבח כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והכלי לאלקות הוא ביטול, שכן הוא בכל סט' דקדושה, אך הסט\"א הן בתכלית הישות, ומ\"מ נמשך להם חיות לקיום מציאותם, אך לא בבחי' פנימי דאין קדש מתערב ומתאחד בחול, והי' נבלע בהם, כ\"א בבחי' מקיף, ולכן הגם שיש בהם חוזק ה\"ה בבחי' העדר בעצם, וכמו הנסיון כשעומדים כנגדו מתבטל לגמרי, והחומריות צריך עבודה תמידית, ונה\"א בהתלבשות בנה\"ב ופועל בו ביטול זהו בעוה\"ז בכח אור הסוכ\"ע, וע\"י מצות וע\"י רעו\"ד גילוי הסובב ומהפכי' הנה\"ב לטוב. וז\"ע הע' פרים בירור הע\"ש ע\"י ענן הקטרת דבסוכות, וזהו הללו ה' כל גוים.</span>"],[3601330610,"<h3>בס\"ד. שמע\"צ, תרד\"ע</h3>\n<b>ביום</b> השמיני עצרת תהי' לכם, ואי' במד\"ר משל למלך שעשה משתה ז' ימים והזמין את כל בני המדינה ביום השמיני אמר לאוהבו כבר יצאנו י\"ח לבני המדינה בא ונגלגל אני ואתה במה שנמצא, כך אמר הקב\"ה לישראל באו ונגלגל אני ואתם במה שתמצאו פר א' איל אחד. וצ\"ל מהו\"ע דבז' ימי החג הקריבו ע' פרים נגד ע\"ש, ובשמע\"צ רק פר א' איל א' והוא רק לישראל כו'. גם צ\"ל מהו\"ע"],[3601330611,"שמע\"צ מש\"א שמע\"צ החג הזה מפני מה נק' שמע\"צ. גם למה אז דוקא נקבע זמן שמחת תורה על הלוחות שנתנו ביוהכ\"פ כו'. ולהבין כ\"ז ילה\"ק משנת\"ל די\"א סממני הקטרת הן בירור הי\"א כתרין דמסאבותא כו', דבקדושה המספר הוא עשר דוקא ולא תשע ולא י\"א מפני שבקדושה האור דע\"ס מתייחד ביחוד גמור עם הכלים כו', משא\"כ בסט\"א אין הקדש מתערב עם החול רק עומד בבחי' מקיף ונחשב בפ\"ע ע\"כ הן מספר י\"א כו'.\n<b>ריב)</b> והנה בע\"ח שער ק\"נ פ\"ג אי' די\"א סממני הקטרת הן בירור הטוב של נוגה, וצ\"ל והלא הקרבנות הן ג\"כ בירורי הנוגה דהבהמה הגשמי היא מק\"נ ומקריבין אותה על מזבח ונכללת באש שלמע' שזהו בירור הטוב שבה ונשאר רק האפר שהוא העצם כו', ועיקר הקרבן הוא זריקת הדם שזהו החיות פנימי שנזרק ונכלל בקדושה כו', וא\"כ מהו ההפרש בין קטרת וקרבנות מאחר דשניהם הם בירורי הנוגה כו'. וידוע דקטרת גבוה יותר מהקרבנות וכדאי' בזהר ס\"פ ויקהל דרי\"ט ע\"א דכתי' קטרת תמיד לפני ה' איהו קיימא לפני ה' יתר מכל פולחנין אחרנין, חביבא איהו עובדא דקטרת כו', ואע\"ג דצלותא איהו מעלי' מכולהו עובדא דקטרת הוא יקיר וחביב קמי' קוב\"ה כו', צלותא אתקינו לה באתר דקורבנין דהוו עבדי ישראל וכל אינון קורבנין כו' לאו אינון חשובין כקטרת כו', הרי שקטרת היא למע' מהקרבנות כו'. והגם דקטרת היא ג\"כ ענין התפלה וכמ\"ש תכון תפלתי קטרת לפניך כו', הנה זהו נגד תפלת מנחה וכמ\"ש אח\"כ משאת כפי מנחת ערב, וידוע דתפלת מנחה הוא למע' מתפלת שחרית וכמארז\"ל לעולם יהא אדם\nזהיר בתפלת המנחה שכן אליהו לא נענה אלא בתפלת המנחה דאז הוא זמן עת רצון ביותר כו' כנודע, וא\"כ צ\"ל מהו ההפרש בין הקטרת לקרבנות כו'. אך הענין הוא דהנה הקרבת הקרבנות הי' על מזבח החיצון והקטרת הקטרת על מזבח הפנימי, וידוע דב' המזבחות בנפש הן בחי' חיצוני' הלב ופנימי' הלב, דחיצוני' הלב היא האה' שע\"פ טו\"ד והיינו מה שבא ע\"י השגה והתבוננות אלקי, דכללות ענין ההשגה הוא בהאור האלקי שבא בבחי' התלבשות בעולמות דמה הנשמה ממלא את הגוף כך הקב\"ה ממלא את העולם כו', וע\"כ מבשרי אחזה אלק' וכמו שהאדם משיג ומרגיש בעצמו אור וחיות הנפש שלו בהכחות פרטי' שבה, וכמו בכח השכל שבמוח וכח המדות שבלב, והחיות חיצוני שבאברים החיצונים כמו כח התנועה שביד וכח ההילוך שברגל כו', שיודע ומשיג היטב כל כח וכח בערכו ומעלתו בעצם כו', כמו מהו שכל ומה המה מדות שיודע ומשיג היטב בעצם מהותם מה הם כו', והגם שזהו רק ידיעת המציאות שהרי אינו רואה מהות הכחות כו', מ\"מ הרי מציאותם הוא יודע ממש איך ומה הם כו', ומשיג ג\"כ העילוי שיש בכל כח עליון לגבי\nהכח שלמע' ממנו מן כח ההילוך שברגל עד כח החכ' שבמוח כו', וגם משיג ומרגיש איך שכל כח תחתון נמצא וכלול בהכח העליון ואיך הוא שם בעילוי הרבה יותר כו', וכמו בהתכללות המדות בשכל כו' שמרגיש המדות שבשכל ואיך שהם שם בדקות ורוחני' כו', וכ\"ה בכח העשי' או כח הדבור שנמצאים כלולים במדות ובשכל והן האותי' שבמדות ושכל, וכן העשי' שבשכל ששם הוא במע' גבוה הרבה יותר כו', ובכללות הרי מושג ומורגש אצלו היטב איך שהעיקר הוא החיות המחי' אותו כו'. וכמו\"כ יבין וישיג בהאור והחיות האלקי בפרטי המדרי' בבחי' חב\"ד חג\"ת נה\"י איך ומה"],[3601330612,"הוא כל מדרי' ומדרי' בפ\"ע ומעלתם זה על זה כו', ואיך שפרטי מדרי' הנ\"ל הן המאירים והמחיים את העולמות אבי\"ע חכ' באצי' בינה בברי' וז\"א ביצי' כו', שעי\"ז יבין מעלת וערך כל עולם ועולם בפ\"ע ואופן העבודה בכל עולם והביטול דשם כו' (דלפי אופן ההשגה וההתבוננות שלו בכל מדרי' ומדרי' דהיינו בכל עולם ועולם במעלת ומדרי' העולם בהאור האלקי איך שמושג בהם ובהעבודה ובהביטול שלהם כו', הרי עבודתו וביטולו הוא ג\"כ באופן הזה ממש כו'). וגם יבין וישיג איך שכל מדרי' תחתונה נמצא כלול בהמדרי' העליונה ואיך שהוא שם בעילוי יותר כו', וכמו איך שכל הנמצאים דעולם העשי' נמצאים כלולים ביצי' ושם המה גבוהים במעלתם כו' והיינו שהן במדרי' עשי' כו' (דאין זה מה שיצי' הוא מקור לעשי' כו'), רק דכמו שנמצאים כלולים ביצי' הם במע' גבוה יותר כו', וידוע ומבו' במ\"א דהשגת הנברא שמשיג ומתבונן בזה איך שהוא נמצא במדרי' הגבוה ממנו דהיינו בשרשו ומקורו ואופן מציאותו שם כו', ה\"ז פועל בו ביטול פנימי יותר מהביטול במדרי' עצמו במדרי' שהוא כו', ועי\"ז הוא\nמתעלה למעלת ומדרי' העליונה כו' (ועמ\"ש בקונטרס העבודה בענין התכללות נפש ברוח ורוח בנשמה כו'). ובכללות ההשגה וההתבוננות איך שהאור והחיות האלקי מחי' כל העולמות והנבראים ושהעיקר הוא האלק' כו', וע\"י כ\"ז מתעורר האה' בבחי' קירוב ודביקות באלקות שכל חפצו ורצונו הוא רק באלקו' ושיהי' גילוי אלקות כו', ובד\"כ הוא משאה\"כ לאה' את ה' אלקיך כי הוא חייך, והיינו כמו שהאדם אוהב חיי נפשו כן כאשר יתבונן שהאוא\"ס הוא חיי החיים העליונים והתחתונים ומכלכל חיים בחסד, ופי' מכלכל חיים הוא שנמשך מבחי' חסד עליון בחי' חיים לכל חי ע\"י שהוא ית' מכלכל אותן בכלי תוך כלי עד שנמשך חיות לכל פרטי הנבראים דבי\"ע כו', וכאשר יתבונן בכ\"ז הדק היטב בהעמקת הדעת ובפרט כאשר מתבונן באופן החיות כנ\"ל תגדל אצלו האה' לדבקה בו ית' כו', וכ\"ז הוא בחי' חיצוני' הלב שהוא כענין הקרבת הקרבנות ע\"ג מזבח החיצון כו'. אבל ענין בחי' פנימי' הלב ז\"ע הקטרת דפי' קטרת הוא ל' התקשרות והו\"ע התקשרות עצמי כו', והיינו שהאה' אינה רק מצד ההתבוננות כ\"א מצד עצמי' הנשמה\nשמקושרת באוא\"ס ב\"ה, וכמ\"ש רשב\"י בחד קטירא אתקטרנא בי' אחידא בי' להיטא שהוא ההתקשרות שלמע' מן השכל כו', והתעוררות אה' זו היא ג\"כ ע\"י התבוננות והוא כשמתבונן שכל בחי' האור והחיות שבעולמות וכן כללות ההשתל' איך שכ\"ז הוא רק הארה לבד שבאין ערוך לגבי עצמות דעצמות אוא\"ס מופלא ומובדל מהעולמות כו', ואפס קצהו יוכל להיות ג\"כ ההשגה באופן ההפלאה דאוא\"ס ע\"י ידיעת והשגת השלילה כו', שעי\"ז נעשה הרצוא להכלל בעצמות אוא\"ס וכמ\"ש מי לי בשמים ועמך לא חפצתי בארץ, דשו\"א הן געה\"ע וגעה\"ת כו', וכאשר יתבונן איך שהגילוי' דג\"ע הן ג\"כ רק הארה לבד דביו\"ד נברא העוה\"ב כו', וזהו ועמך לא חפצתי גם בחי' כי עמך מקו\"ח הוא בחי' מקור החיים ומקור התענוגי' המושגים בבחי' השגת והבנת החכ' בגעה\"ת וגעה\"ע שכ\"ז הוא עמך וטפל לך כו', כ\"ז לא חפצתי רק להכלל בבחי' עצמות אוא\"ס כו'. וז\"ע הקטרת שהוא ההתקשרות שלמע' משכל המושג שזהו בבחי' יציאה מכלי המגביל וה\"ז היפך האה' מהתבוננות דהוא חייך שזהו התיישבות אור בכלי, אבל התקשרות דקטרת הוא בחי' הקטירא היינו קשר של קיימא שלמע' מהשכל דאה' זו אינה חולפת ועוברת כו' וכמ\"ש במ\"א. ונמצא ההפרש בין קרבנות"],[3601330613,"לקטרת דקרבנות הוא העבודה דבחי' או\"פ פנימי דנפש, וקטרת הוא העבודה בבחי' או\"מ דנפש כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ובע\"ח דקטרת בירור הטוב דנוגה, וצ\"ל והלא קרבנות ג\"כ בירור דנוגה, ומהו מעלת הקטרת, והענין הוא דקרבנות הן על מזבח החיצון, וקטרת על מזה\"פ, מזה\"ח חיצוניות הלב, האהבה הבאה ע\"י התבוננות, והוא באלקות שבעולמות ומבשרי אחזה דכחות הנפש יודע מהות מציאותם, וכל כח איך שהוא כלול בכח עליון, ובכללות שהעיקר הוא חיות הנפש, וכמו\"כ יבין פרטי המדרי' דע\"ס שבכל עולם, ואיך כל עולם תחתון בעולם העליון שזה עושה ביטול גדול, ובכללות שהעיקר הוא האלקות וזאת יחפוץ, ומזה\"פ בחי' פנימיות הלב האהבה עצמיות דנשמה, וההתעוררות היא ע\"י ההתבוננות איך שהכל רק הארה ובענין ההפלאה דאוא\"ס, ועי\"ז הוא היציאה מכלים היפך האהבה דטו\"ד שהיא בהתיישבות בכלים.</span>\n<b>ריג)</b> וזהו שהקרבנות נק' בשם לחם וקטרת הוא בחי' ריח, דגבי קרבנות כתי' את קרבני לחמי לאשי שנק' לחם לאשי שהן השרפים שהן בבחי' יסוד האש, וכידוע שנק' שרפים ע\"ש שנשרפו בבחי' הרצוא והתשוקה שלהם בבחי' צמאון ביותר כו', והקרבנות הם בבחי' לחם להם, וכמו\"כ הוא בבחי' לחם לגבי אדה\"ע שעז\"א רעייתי פרנסתי הן שירעו אותי בשני תמידין כו', דפעולת הלחם הוא שממשיך אור וחיות הנפש ומחברו ומקשרו עם הגוף כו', דלהיות שהנפש עם הגוף הן מרוחקים מאד זמ\"ז שהגוף הוא חומרי וגשמי והנפש הוא רוחני, ואין ערוך חומרי' הגוף גם לגבי כחות הנפש ומכ\"ש לגבי הארת הנפש הכללי' שמחי' את הגוף כו', ומ\"מ הרי אור הנפש בא בבחי' התלבשו' ממש בגוף, לא מיבעי הכחות שהן בבחי' התלבשו' פנימי אלא שגם ההארה כללי' מהנפש ה\"ה באה בבחי' התלבשו' פנימי בהגוף כו' וכמ\"ש במ\"א. ובכדי שתהי' המשכה והתחברות הזאת זהו ע\"י הלחם, וכנראה בחוש דבהעדר האכילה נחלש כחו וע\"י האכילה מתחזק כחו, וכמו עד דלא אכילנא כו', וחמרא וריחא פקחין כו'. ומ\"מ ע\"י האכילה אינו\nמתחדש החיות להיות נמשך חיות חדש מהנפש, שהרי כאשר ח\"ו מסתלק החיות פנימי אינו מועיל אכילה, וכמו בקלקול איזה אבר הגורם הסתלקות החיות או בהתעלפות שהחיות פנימי מסתלק הרי לא יומשך ע\"י אכילה כו', מובן מזה דמה שנמשך ע\"י האכילה הוא חיות הנפש השייך אל הפנימי כו'. והדוגמא מזה יובן למע' בבחי' ציור אדה\"ע דבכדי להמשיך האור מאוא\"ס המאציל ושיהי' בבחי' התלבשות והתאחדות בכלים צ\"ל ע\"י ממוצע כו', שהרי אוא\"ס הוא לאו מכא\"מ כלל והוא בחי' כי לא אדם הוא שאינו בגדר חכ' וחסד כו'. וכמו\"כ האור והגילוי ה\"ה כמו העצם שהוא בבחי' פשיטות עדיין כו', והכלים ה\"ה בבחי' מציאות חכ' וחסד כו', וע\"ז הו\"ע הקרבנות דאת קרבני לחמי כו', דרזא דקורבנא עולה עד רזא דא\"ס ה\"ז ממשיך מבחי' דלא אדם הוא שיתצמצם בבחי' מראה אדם ויהי' התחברות האורות והכלים כו'. וכמו שהלחם למטה ממשיך את חיות הנפש השייך אל הגוף כו', כמו\"כ ענין הלחם למע' הוא שממשיך מבחי' אוא\"ס השייך אל העולמו' כו', וע\"ה שזהו המשכה מבחי' כי לא אדם, מ\"מ אינו נמשך בזה גילוי בחי' כי לא אדם הוא ממש,"],[3601330614,"כ\"א רק הארה לבד ומתצמצם בבחי' ציור אדם כו'. אמנם ענין הריח הוא שמשיב את הנפש והיינו שממשיך אור הנפש מעצם הנפש שלמע' מבחי' שייכות אל הגוף, כ\"א מעצם חבור הנשמה עם הגוף, שהוא למע' עדיין מבחי' התפשטות וגילוי כו', וע\"כ גם בהסתלק אור וחיות הנפש כמו בהתעלפות וכה\"ג מועיל הריח להשיב אור הנפש מפני שממשיכו משרשו ומקורו העצמי כו', והחיות הוא בבחי' התחדשות שא\"ז רק אור המתפשט כ\"א אור עצמי כו'. והדוגמא מזה למע' הוא שממשיכים מבחי' עצמות אוא\"ס שלמע' מבחי' שייכות אל העולמות, והוא שנמשך גילוי עצמו' אוא\"ס ממש לא רק בחי' ההארה שבאה בבחי' צמצום דכמראה אדם, כ\"א להיות גילוי אוא\"ס ממש בבחי' אדה\"ע להיות בחי' אדם בבחי' אדמה לעליון בחי' כי לא אדם הוא כו', והוא דבחי' ז\"א יהי' כמו א\"א ממש כו', דע\"פ ס' השתל' שנמשך מבחי' א\"א לז\"א הרי האור דז\"א הוא בבחי' צמצום ובבחי' מיעוט הרבה לגבי בחי' א\"א כו', וענין הריח הוא ההמשכה דבחי' ז\"א יהי' כמו א\"א ממש כו', וזהו שממשיכים ע\"י העבודה דקטרת בחי' רעו\"ד כנ\"ל שזהו בחי' כי לא אדם הוא\nשבאדם ועי\"ז ממשיכים למע' ג\"כ גילוי בחי' כי לא אדם בבחי' אדה\"ע כו', ובד\"כ הוא שע\"י העבודה דקרבנות ממשיכים בחי' או\"פ וע\"י העבודה דקטרת ממשיכים גילוי בחי' או\"מ כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וזהו שהקרבנות נק' לחם וקטרת ריח, פעולת הלחם שמחבר הנפש עם הגוף להיות בבחי' חיות פנימי, ומחזק כחו, ומ\"מ אינו התחדשות החיות, וכמו\"כ רעייתי פרנסתי ע\"י קרבנות התחברות האורות בכלים, דבחי' כי לא אדם יתצמצם בבחי' מראה אדם, וריח משיב את הנפש, התחדשות החיות, ולמעלה הוא ההמשכה מעצמות אוא\"ס להיות אדם אדמה לעליון בחי' כי לא אדם, ז\"א כמו א\"א.</span>\n<b>ריד)</b> והנה כשם דבעבודה ההפרש בין קרבנות לקטרת דקרבנות הוא העבודה דאו\"פ וקטרת הו\"ע או\"מ כו', כמו\"כ הוא ההפרש בבירור ותקון הק\"נ הנעשה עי\"ז דבקרבנות מתתקן האו\"פ לבד דק\"נ כו', דלהיות שהעבודה בזה הוא רק בכחות פנימי' דנפש דהיינו העבודה שע\"פ טו\"ד כו', ע\"כ ה\"ז פועל הבירור דנוגה בבחי' אתכפי' לבד והיינו רק בהתפשטות דנה\"ב כו', אבל ע\"י הקטרת נתברר האו\"מ והוא המקיף דלבונה זכה שזהו עיקר ענין הקטרת שמתברר עי\"ז האו\"מ המחי' אותם כו', ולכן עיקר ביטול הק\"נ הוא ע\"י הקטרת דוקא, דהרי נת\"ל פרי\"א דעיקר החיות שלהם הוא מהאו\"מ, וכאשר סר צלם מעליהם ה\"ה מתבטלים לגמרי כו'. והנה המקיף דלבונה הוא בחי' עתיק דקלי' דכן מובן מפע\"ח שחשיב בפרטי המדרי' דהי\"א סממנים כ' דהצרי שבקטרת הוא כתר (ועמ\"ש בסידור האריז\"ל מהרש\"ב ז\"ל), ולבונה הוא המקיף שלמע' מזה, וא\"כ הוא בחי' עתיק דקלי' שזהו קלי' קשה ביותר והיא בתחתית העשי' כו', ומה שנק' לבונה זכה הוא מפני שיש בה מהקדושה היינו מדרי' תחתונה מבחי' מל' דעשי' כו', וכמ\"ש בזהר\nהרקיע על מאה\"ז ויקהל דרי\"ט סע\"א דמל' דעשי' היא בעמקי הקליפות כו', וזהו בחי' זכה המתלבשת בלבונה כו'. והענין הוא דהנה את זלעו\"ז עשה אלקי' וכשם שיש ד' עולמו' אבי\"ע וע\"ס כח\"ב חג\"ת כו' בקדושה, כמו\"כ יש בלעו\"ז רק שבלעו\"ז הוא ההיפך מהקדושה כו', דהנה בקדושה הרי כל עולם שהוא עליון ה\"ה בבחי' תוקף"],[3601330615,"וריבוי האור יותר וכל מה שיורר למטה הרי מתמעט האור כו', ובלעו\"ז היא להיפך דכל מה שיורד למטה הוא בבחי' תוקף יותר כו'. דהרי בקדושה הנה באצי' הוא תוקף התגלות האור דאוא\"ס ב\"ה, והיינו בחי' גילוי הקו דעם היות שזהו רק הארת הקו, מ\"מ ה\"ז הארת אוא\"ס בבחי' גילוי ממש דאיהו וחיוהי חד ואיהו וגרמוהי חד כו', ובברי' מתמעט האור הרבה ע\"י המסך ופרסא המפסקת כו', וביצי' מתמעט יותר כו'. וכמו\"כ הוא במספר האורות הנק' ע\"ס שבאצי' מאירים בגילוי כל הע\"ס דכחב\"ד כו' עד המל' (ובפנימי' האצי' מאיר גם בחי' פנימי' הכתר בחי' עתיק שזהו\"ע פנימי' אבא שהיא פנימי' עתיק כו'), ובברי' אינו מאיר בגילוי רק מבחי' אור אימא ולמטה דאימא מקננא בכורסיא כו', וביצי' רק בחי' ז\"א כו', וכן בס' דש' הוי' י' באצי' ה' בברי' כו' וכמ\"ש בע\"ח (והנה מה שבאצי' מאירים כל הע\"ס ובברי' רק בינה וביצי' רק ז\"א כו', הכוונה היא על המדרי' דאצי', שהרי בכל עולם יש ע\"ס רק שבאצי' מאירים כל הע\"ס דאצי' גם בחי' הכתר ועתיק, ע\"כ הע\"ס הן במדרי' גבוה ונעלה דכללו' הע\"ס דאצי'\nהם במדרי' בחי' החכ' והכתר כו' וכמ\"ש במ\"א, ובעולם הברי' שמאיר רק בחי' בינה הגם שיש שם ע\"ס אך כללות הע\"ס הן למטה במדרי' וכן ביצי' ועשי' כו'). אך בסט\"א שהן לעו\"ז דקדושה ה\"ה להיפך דאצי' דקלי' היא בבחי' חלישות, וכנודע דקלי' דאצי' הו\"ע הרגשת הביטול שנק' ראומה שהביטול הוא במורגש דאמיתי' הביטול הוא שאינו מרגיש כלל שהוא בטל, וכמו בביטול לפני מלך גדול עיקר אמיתי' הביטול הוא כשאינו מרגיש כלל בשעת ביטולו איך שהוא בטל, וכשישאלנו אדם מה נשתנה כ\"כ מהותך ישיבנו לא ידעתי מאומה כו', וכ\"ה בקדושה ביטול עצמי ופנימי הוא שאינו מרגיש כלל שהוא בטל כו', והיינו דהביטול הוא בעצם מהותו כ\"כ שאינו מרגיש א\"ע כלל וכלל למציאו' עד שאינו מרגיש כלל שהוא בטל לאיזה דבר כו', ומשו\"ז יכול להיות על מעמדו ומצבו מפני שאינו שום מציאות לעצמו שאינו מרגיש א\"ע כלל לדבר מה כו'. אבל כשמרגיש את הביטול שלו ואינו יכול לעמוד על מעמדו ומצבו מפני הביטול דהיינו שאין לו מקום לעצמו כו' (ער האט פאר זיך קיין ארט מפני עוצם ביטולו כו'), הגם שזהו\nביטול אמיתי מ\"מ יש בזה עדיין בחי' מציאות דבר כו', וזהו בתכלית הדקות, ולמטה מזה הוא שמרגיש את הביטול שטוב לו מה שהוא בטל והוא במעלה ומדרי' בעצמו כו', ולא שעושה בו איזה הגבהה ח\"ו רק שהביטול אצלו בבחי' תפיסת מקום כו'. וז\"ע ראומה שהביטול הוא במורגש ובתפיסת מקום בעצמו כו', ובגסות ענין ראומה הוא שרוצה שיהי' נראה ביטולו, ועם היותו בטל לאלקות רק שהוא רוצה שיהי' נראה וניכר הביטול שלו, ויש בזה דקות הרע והוא שבזה גופא מה שרוצה שיהי' נראה הביטול כוונתו הוא לש\"ש כו', וע\"ה שיש בזה כוונה רוחניות סכ\"ס הוא בבחי' מורגש ואינו בטל כו', והגסות הוא שרוצה כן מצ\"ע מצד הישות שבו כו', וכ\"ז הו\"ע ראומה שהוא קלי' דאצי' כו', ובברי' הקלי' הוא בבחי' ישות ממש שאינו בטל לאלקו', וביצי' הוא בבחי' ישות יותר עד קלי' דעשי' שהיא בתוקף ביותר כו', וכערך תוקף האור דאצי' דקדושה על האור דעשי' דקדושה כך ערך תוקף אור הקלי' דעשי' על אור הקלי' דאצי' כו'. וכמו\"כ במספר האורות הנה בקלי' דאצי' המספר הוא במיעוט והן רק ז\"ת דקלי', ובברי'\nדקלי' שם גם חו\"ב דקלי' והן סיחון עמון ומואב שזהו ג\"ר דקלי' וכמ\"ש במ\"א, וביצי' גם בחי' כתר דקלי' וכמו נבוכדנצר שנא' בו אנת רישא דדהבא כו', ובעשי' דקלי' שם גם עתיק דקלי' שהיא קלי' קשה ביותר כו'."],[3601330616,"<span data-k=\"ks\"><b>קיצור.</b> וכמו בעבודה כ\"ה בהבירורים, דבאהבה שבטו\"ד שהו\"ע הקרבנות מתברר האו\"פ דנוגה, ובבחי' אתכפי', וע\"י עבודת הקטרת מתבטל האו\"מ עתיק דקלי' שזהו לבונה זכה, דהנה כמו שיש אבי\"ע בקדושה כמו\"כ בסט\"א, ובקדושה באצי' תוקף האור ובגילוי והולך ומתמעט, ובאצי' ע\"ס, ובברי' רק מבינה דאצי', וביצי' רק ז\"א ובעשי' מל', ובסט\"א אצי' דקלי' בבחי' חלישות, הרגש הביטול, ובדקות הוא שמרגיש את הביטול ואין לו מקום לעצמו (דאמיתית הביטול הוא שאינו יודע שבטל), ולמטה מזה שטוב לו מהביטול, ולמטה מזה שרוצה שיהי' נראה הביטול בכוונה לש\"ש, ובגסות שזה מצד הישות, וברי' הוא ישות ממש, ובאורות באצי' רק ז\"ת ובברי' חו\"ב, וביצי' כתר, ובעשי' עתיק דקלי'.</span>\n<b>רטו)</b> וטעם וסיבת הדבר הוא מפני שבסט' דקדושה הוא בחי' אין וביטול דוקא ובמדרי' העליונות ששם הביטול יותר מאיר שם האור והגילוי ביותר כו', וזהו דבאצי' הוא בחי' תוקף האור והגילוי לפי שהכלים דאצי' הן בבחי' תכלית הביטול באוא\"ס כו', להיות דכללות ענין האצי' הוא מה שכלול עדיין באוא\"ס ב\"ה וכמ\"ש במ\"א בענין אתה הוא הוי' לבדך כו', וע\"כ גם הכלים דאצי' הם בבחי' ביטול כמו בהתכללות במקורם כו', ולכן באצי' מאיר גילוי אור רב מאוא\"ס ב\"ה כו', ובברי' שאין הביטול כמו באצי' האור והגילוי שם בבחי' מיעוט כו' וכן מתמעט ממדרי' למדרי' כו'. וכן האורות הרי כל הקרוב יותר לגבי שרשו ומקורו דהיינו בבחי' עליונו של קו יותר ה\"ה במדרי' עליונה יותר ובבחי' אין ביותר כו', וע\"כ באצי' מאיר בחי' הכתר בכלל ובחי' עתיק בפרט (בפנימי' האצי' כו'), והיינו דכללות האורות דע\"ס דאצי' הן כמו מצד מדרי' כתר וחכ' כו', ובברי' במדרי' הבינה כו', וכ\"ז בסט' דקדושה שהו\"ע האין והביטול ע\"כ כל מה שלמע' יותר הביטול יותר והאור ביותר וכל מה שיורד\nממדרי' למדרי' מתמעט כו'. משא\"כ בקלי' דעיקרה הוא בחי' ישות וגסות שמורגש מאד וכמו ראיתי איש חכם בעיניו שמחזיק עצמו לחכם גדול כו', וכמו\"כ במדת החסד שמרגיש בעצמו החסד שעושה עד שמתפאר לעיני כל כו', ומכ\"ש למקבל חסדו לאמר לו ראה כמה טובה גמלתיך כו', וכמו כל טיבו דעבדין לגרמייהו עבדין כו', וע\"כ כל מה שלמע' יותר הקלי' הוא בבחי' חלישות לפי שמאיר שם אור הקדושה יותר, וכמו באצי' דאור הקדושה הוא בתוקף אין מקום לישות וגסות הקלי' כ\"כ, וכל שיורד במדרי' שאין שם האור דקדושה כ\"כ מתגבר הישות דקלי' כו', עד שבעשי' ששם האור דקדושה במיעוט ביותר שם התגברות הקלי' יותר בחי' עתיק דקלי' כו'. וכמו בנפש הרי תוקפא דנשמתא חולשא דגופא, וסבת תוקפא דגופא הוא מחולשא דנשמתא כו', דכאשר הכחות דנה\"א הן בהתגלות מתבטלים הכחות דנה\"ב שנעשים בבחי' חלישות וגם מתבררים ומתתקנים ע\"י העבודה כו', וסבת תוקף הנה\"ב הוא מפני התעלמו' הכחות דנה\"א כו', שיש בזה כמה חילוקי מדרי' כו' וכמ\"ש במ\"א. וענין עתיק דקלי' י\"ל שזהו התאוה שהיא בקרירות שזהו קשה\nיותר מחמימות התאוה שהיא בהתפעלות בנפש שנוחה יותר להתתקן ולהתהפך, אבל התאוה שבקרירות שז\"ע התענוג ה\"ז קשה יותר להתתקן כו' (וכמ\"ש במ\"א בענין שור כשב ועז דעז הוא התוקף שבלי התפעלות זהו קשה יותר משור נגח כו', דע\"ה שהוא בועט אך מצד ההתפעלות שבו בנקל לפעול בו שיתפעל ג\"כ מענין אלקי כו', והעז שאינו בועט"],[3601330617,"אבל הוא בתוקף מאד על מקומו וקשה לפעול בו כו'), גם י\"ל דעתיק דקלי' הוא הטוב טעם (דער גישמאק) בעניני העולם שזה מקור כל תוקף התאוות מפני שיש לו טוב טעם בעצם בענינים החומרי' והתענוגים גשמי' כו'. וזהו\"ע הקטרת שהוא לברר את המקיף דלבונה דהיינו בחי' עתיק דקלי', והוא ליקח את הטוב טעם שבענינים החומרי' ולבטל הקרירות הנ\"ל ועי\"ז מתבטלים ממילא התאוות שאינם בתוקף וגם מתבטלים כו', וזהו ע\"י העבודה בבחי' מקיפים שבנפש שזה פועל בעצם המהות דכח המתאווה כו', דהנה העבודה באו\"פ שהוא במוח ולב פועל בהנה\"ב רק בהתפשטו' שלו לבד, אבל בכדי ליקח הטוב טעם מעניני עוה\"ז שזהו ביטול בעצם מהות כח המתאווה זהו דוקא ע\"י העבודה בכחות מקיפים ובכחות עצמי' דנפש כו'. וז\"ע הקטרת שמבררים הי\"א כתרין דנוגה דהיינו להסיר בחי' המקיף ועיקר חיותם כו', ועי\"ז ממשיכים בקדושה בחי' אור עצמי שז\"ע השמן כו', וכנודע דשמן צף על כל המשקין והוא בחי' החכ' בכלל שנק' שמן כנודע, ובד\"פ הוא בחי' מקור החכ' וכמ\"ש שמן משחת קדש, דקדש הוא בחי' קדש וכמ\"ש ושמרתם את\nהשבת כי קדש הוא כו', ושמן משחת הוא שמושח את הקדש והוא בחי' ח\"ס כו', והיינו גילוי בחי' אור עצמי שמובדל בערך מן ההשתל' כו', ונמשך דוקא ע\"י ביטול מהות נה\"ב כו'. וזהו שמן וקטרת ישמח לב שע\"י העבודה דקטרת ממשיכים בחי' שמן גילוי עצמו' אוא\"ס שעי\"ז ישמח לב אדה\"ע כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש ביום השמיני עצרת תהי' לכם, דהנה בז' ימי החג שמקריבין ע' פרים ה\"ז בירור הי\"א כתרין דמסאבותא, והיינו שמבררים ג\"כ המקיף דלבונה זכה כו', והוא ע\"י הקטרת דיוהכ\"פ כו' כמשנת\"ל, וההמשכה עי\"ז הוא שנמשך בשמע\"צ והוא המשכת בחי' שמן משחת קדש בחי' החכ' שלמע' מבחי' מקור להשתל', וכידוע דעיקר מקור ההשתל' הוא מבינה, אבל בחי' חכ' וכ\"ש בחי' ח\"ס היא למע' מבחי' מקור כו'. וזהו מה שנק' שמיני עצרת דאי' בשם הה\"מ ז\"ל שהוא ל' שמן, והיינו המשכת בחי' שמן משחת קדש כו', ובאמת הוא עוד המשכה גבוה מזו, והיינו בחי' שמן הטוב שנמשך ע\"י הקטרת דיוהכ\"פ שהוא במדרי' גבוה ונעלית יותר כו' וכמשי\"ת. וע\"כ המשכה זו היא לנש\"י דוקא להיות שזהו המשכה מבחי' פנימי' אוא\"ס ב\"ה, ע\"כ המשכה זו היא לישראל דוקא וכמ\"ש יהיו לך לבדך ואין לזרים אתך כו', וזהו בא ונגלגל אני ואתם דוקא כו'. וזהו ג\"כ ענין שמחת תורה שנקבע בשמע\"צ, דאורייתא מחכ' נפקת וכאשר נמשך מבחי' שמן משחת קדש ובחי' כשמן הטוב ה\"ז שמחה גדולה להתו' בבחי' תוס'\nאור רב מאד כו'. וזהו ביום השמיני עצרת דמה שנק' שמע\"צ החג א\"ז מצד המספר, וכמו ששביעי של פסח אינו נק' ע\"ש המספר ע\"ה שנק' ג\"כ עצרת בפסוק, רק זהו ע\"ש בחי' השמן שנמשך בחי' השמן הטוב וע\"כ אז הוא שמחת התו' כו', וההמשכה היא לנש\"י לבד יהיו לך לבדך ואין לזרים אתך כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וסבת הדבר מפני דסט' דקדושה הוא בחי' ביטול, וע\"כ כל הקרוב יותר הביטול יותר, וממילא האור והגילוי ביותר, וכל שמתרחק מתמעט הביטול והגילוי, וסט\"א הוא ישות ראיתי איש חכם בעיניו, וכל טיבו הוא לגרמייהו, וכל שבקירוב אל הקדושה הישות במיעוט וכל שמתרחק הישות ביותר, וענין עתיק</span>"],[3601330618,"<b>דקלי'</b> הוא התאוה בקרירות שגרוע יותר, גם הטוב טעם בעניני העולם, והעבודה באו\"מ מבטל הקרירות ולוקח הטוב טעם, והוא הביטול בעצם מהות הקלי' וממילא מתבטל ההתפשטות, ועי\"ז נמשך בחי' שמן אור עצמי מקור החכ'. וזהו וביום השמיני עצרת בחי' שמן שנמשך מהבירור דע\"ש שע\"י ענן הקטרת, וההמשכה היא לנש\"י דוקא."],[3601330619,"<h3>בס\"ד. ש\"פ נח, תרד\"ע</h3>\n<b>וירח</b> ה' את ריח הניחוח ויאמר לא אוסיף עוד לקלל כו', ואי' במד\"ר הריח ריח של אברהם אבינו עולה מכבשן האש, הריח ריח של חנני' מישאל ועזרי' עולה מכבשן האש כו'. וצ\"ל מהו\"ע שהריח ריח של אברהם אבינו וחמו\"ע ועי\"ז דוקא א' לא אוסיף עוד כו', והלא ע\"פ פשוט ריח הניחוח הוא ריח הקרבנות שהקריב נח שזה ג\"כ ענין גבוה ונעלה דרזא דקורבנא עולה עד רזא דא\"ס כו', מה מוסיף ומחדש זה שהריח ריח של א\"א ע\"ה כו'. ולהבין זה ילה\"ק משנת\"ל ההפרש בין הקרבנות לקטרת דקרבנות הן בחי' לחם וכמ\"ש את קרבני לחמי לאשי וכמו הלחם שממשיך חיות הנפש ומחברו עם הגוף שמתחזקים כחותיו עי\"ז וכמא' עד דלא אכילנא כו' לא צלינא כו', ומ\"מ אין בזה התחדשות החיות כו', כמו\"כ הקרבנות ממשיכים מבחי' אוא\"ס דכי לא אדם הוא להתלבש בבחי' ציור אדה\"ע כו', מ\"מ ההמשכה היא רק הארה לבד שבאה בבחי' צמצום באדה\"ע כו', והיא המשכת הארה השייכה להשתל' כו', אבל הקטרת הוא בחי' ריח שמשיב את הנפש שממשיך מעצם חבור הנשמה עם הגוף ונמשך אור וחיות חדש כו', וכמו\"כ ענן הקטרת הוא שממשיך בחי' אוא\"ס דכי לא אדם הוא שיאיר בגילוי ממש בבחי' אדה\"ע כו'.\n<b>רטז)</b> והנה עדיין צ\"ל משנת\"ל פרי\"ג דקרבנות נק' לחם שזהו המשכת או\"פ לבד וקטרת הוא בחי' ריח שממשיך האו\"מ כו', והלא בקרבנות כתיב ריח ניחוח לה' הרי הקרבנות הן ג\"כ בחי' ריח, וא\"כ מהו ההפרש בין הקרבנות והקטרת כו', דמאחר דשניהם הם בחי' ריח וא\"כ מהו ההפרש ביניהם כו'. ולהבין זה ילה\"ק תחלה דכללות ענין הריח הוא מה שבא ע\"י בירורי הניצוצות דתהו כו', להיות ידוע דריח שרשו מבחי' הגבו' דוקא דהרי כל ריח הוא מדבר החזק דוקא, דדבר הבלתי חזק לא יהי' ממנו ריח כ\"א מדבר החזק וחריף, וכמו התבלין שמתבלין בהם המאכלים שכולם המה דברים חריפים ומהם בא הריח כו'. דכמו\"כ הוא בנמשל דענין הריח הוא מבירורי הניצוצו' דתהו שהן בבחי' הגבו' בחי' אורות תקיפים וחזקים כו', וכמארז\"ל לעולם יהא אדם רך כקנה ואל יהא קשה כארז, רך כקנה הן בחי' מדות דתקון שהן בבחי' חלישות ובבחי' מיעוט האור כו', וקשה כארז הן מדות דתהו שהן בבחי' תוקף ובבחי' ריבוי האור כו', וזהו הן בהאורות והן בהכלים"],[3601330620,"שהאורות היו בבחי' תוקף האור ביותר (שלא הי' בהם התחלקות בעצם כו') מפני ריבוי האור כו' (שהי' בבחי' אור עצמי כו'), וגם הכלים היו בבחי' תוקף מצד המיעוט שלהם דמשו\"ז היו בתוקף דאנא אמלוך דוקא כו', והגם דהתרחבות הכלים הוא ג\"כ בבחי' תוקף שז\"ע ההתיישבות שיהי' דוקא באופן כזה ולא באו\"א כו', אך זהו התוקף שמצד הטעם לא בבחי' תוקף בעצם וממילא אפשר להשתנות כו', משא\"כ התוקף שמצד מיעוט הכלים הוא התוקף בעצם כו', וזהו דמדות דתהו הן בחי' גבו' כו', ובפרט ע\"י השבירה ונפילה שנעשו בחי' ק\"נ ה\"ה כמו דבר הקיוהא וחריף שנעשה מזה ריח חזק כו'. וזהו שארז\"ל בגמ' דפסחים בענין בשכמל\"ו משל לבת מלך שהריחה ציקי קדרה תאמר יש לה גנאי כו', דבת מלך היא בחי' מל' דאצי' שנק' ברתא דמלכא בחי' מלך עילאה דאבא דאצי' דאבא יסד ברתא כו', דבחי' מל' הוא מקור השפע והחיות דבי\"ע כו', ועז\"א שהריחה ציקי קדרה היינו הריח מהבירורים דבי\"ע כו'. דהנה יש ב' מיני עונג, הא' העונג העצמי שיש בטבע בעצם הדבר שהוא טוב וערב לנפש ונק' עונג עצמי היינו שבא בסדר\nוהדרגה מהעונג שבנפש כו' (וכמו החיות שבאברים שזהו שנמשך מהות החיות הגם שזהו רק הארה לבד, מ\"מ הוא מהות הארת חיות הנפש שבא בסדר והדרגה משא\"כ בשערות כו'), וכמו העונג בטעם ערב וטוב לנפש בחיך הטועם במתיקות ועריבות בטעם המאכל שמבשלים בקדרה וטועמי' בזה כל מיני טעם וחיות לנפש כו', ובכחות נפשי' הוא כמו העונג במושכלות עמוקות ונעלות דמי שהוא חכם גדול ה\"ה מתענג מאד ממושכלות כו', וכן האיש הטוב והחסד שמתענג בפעולת הטוב והחסד שלו כו' שזהו עונג עצמי, והיינו שהדבר בעצם הוא דבר טוב ודבר עונג בעצם וע\"כ מתענג בו כו', ובגשמי' זהו כמו התענוג במאכל ערב וטוב בעצם כו' כנ\"ל. והב' הוא העונג שמורכב בהיפוכו דוקא, וכמו התענוג בניצוח על המנגד שמנגד אליו בפועל דכאשר מתגבר עליו ומנצחו יש בזה עונג גדול בנפש, אבל א\"ז עונג עצמי והיינו לא שהדבר טוב בעצם שהרי הי' יותר טוב שלא הי' מנגד, רק כשיש מנגד הנה כאשר מנצחו יש בזה עונג גדול כו', וכן הענג בהסרת ההעלמות בסתירות הקושיות באיזה מושכל שיש בזה עונג גדול וא\"ז עונג עצמי כו',\nהגם שהעונג בזה הוא פנימי ועצמי יותר בנפש, מ\"מ אין זה עונג עצמי לפי שא\"ז מהדבר הטוב בעצם כ\"א מהיפוכו כו', ובגשמי' הוא כמו העונג במה שנשרף באש ונשאר בקדרה מפסולת המאכל המבושל אחר שיצא ממנו כל הטעם הטוב ונדבק בכותלי הקדרה ובשולי' שזהו הנק' ציקי קדרה. ואמנם יש בזה טעם קיוהא וחריפות שמשיב הנפש ומחזק הלב מצד חריפותו ומריח ריח חזק ביותר שלזה הריח יתאווה כל חלש הלב ונפש רקניות שתמלא חסרונה להשיב נפשה, ויכול להיות עונג הנפש בריח זה יותר ממעדני מלך כו'. וזהו פי' המשל לבת מלך שרגילה בטעמים ערבים בדקות העונג והטעם בעצם כל הדברים הטובים כו', הנה לפעמים כאשר נחלש כח הנפש ולא תקבל עונג ממאכלים הטובים העולים על שלחן מלכים יוכל להיות שתתאווה הנפש בהריחה ריח חזק וקשה דציקי קדרה דוקא שזה משיב הנפש כו'. והדוגמא מזה למע' בבת מלך עילאה בחי' מל' דאצי' בחי' דבור העליון בצירופי האותי' בה' מוצאות כו', והוא בחי' התגלות דרצון וחכ' ומדות דאצי' שמאירים ומתגלים בבחי' מל' וכמא' ביתא דאתפריעו בי' כל נהורין עילאין כו',\nדכל האורות מאירים ומתגלים בבחי' המל' כו', והן אורות וגילוים שיש בהם עונג בעצם שהן בחי' אורות דתיקון בחי' ש' מ\"ה"],[3601330621,"דאיהו אורח האצי' כו', וכמארז\"ל דין הניין לי' כו', דבחי' התיקון זהו בחי' טוב בעצם והוא בחי' עונג עצמי כו'. וע\"ה דאצי' הוא ג\"כ מה שנתברר מבחי' התהו כו', הנה העיקר מה שנתברר מבחי' התהו הן בחי' הכלים דאצי' כו', אמנם משמעות הע\"ח הוא דגם בהאורות יש מה שנתברר מבחי' התהו כו', הרי ידוע שזהו מה שנתברר מלמעלמ\"ט ובא באצי' בחי' אור מבורר כבר וזהו בחי' ש' מ\"ה כו' (דגם ש' מ\"ה דאצי' זהו מה שנתברר רק להיות שהבירור בזה הוא מלמע' ע\"כ נתברר בתכלית הבירור ביותר שאין בזה שום תערובות פסולת כלל כו', ונעשה בחי' אור עצמי כמו שלא הי' בזה שבירה ונפילה כלל כו', וי\"ל כמו בהבירור שני דש' מ\"ה הרי ידוע שעי\"ז נכללים הניצוצו' דבי\"ע בקדושת האצי' ונעשי' אלקות ממש כו'. דזהו ההפרש בין הבירור ראשון דמלמטלמ\"ע להבירור שני דמלמעלמ\"ט, דהבירור דמלמטלמ\"ע הוא להפריד הטוב מן הרע ולהעלותו למע' אבל אינו נכלל עדיין באלקו' כו', והבירור השני דשם מ\"ה מלמעלמ\"ט הוא שנכלל בקדושת האלקות דאצי' ונעשה אלקות ממש כו', ומכ\"ש שהוא כן בתחלת הבירור\nמלמעלמ\"ט במדרי' העליונות שנכללים ממש במדרי' אוא\"ס דתיקון בחי' מלך שמיני הדר בחי' יסוד דא\"ק כו', וכנודע דזמ\"ל דתהו הן מבחי' מל' דא\"ק שזהו בחי' חיצוני' א\"ק כו', ומלך שמיני הדר שרש התיקון הוא בחי' יסוד דא\"ק שזהו בחי' פנימי' א\"ק כו', וכמ\"ש בלק\"ת ד\"ה למנצח על השמינית, ובשרשו הוא בחי' הוא ושמו שם אחד שלמע' מהז' שמות הכלולים בעצמו' כו', וכמ\"ש בהבי' דואני נתתי בהוספות תו\"א ובמ\"א, ומשם הוא הבירור דאצי' בבחי' מלמעלמ\"ט ונכלל ממש במדרי' זו ונעשה בחי' אור דתיקון בעצם כו', ועמ\"ש בלק\"ת בהבי' דמי מנה). וגם הכלים דאצי' הן אלקות ממש ונכללו ג\"כ בש' מ\"ה רק שהן בחי' ב\"ן דמ\"ה והיינו שמביאים ומגלים בחי' דש' מ\"ה כו' וכמ\"ש במ\"א, וכמו התו' שהיא חכ' ברורה דהיינו מה שכבר נתבררה מלמע' והיא בבחי' התיקון בעצם כו', וכנודע שגם האותי' דתושב\"כ הן אותי' דמ\"ה כו', וע\"כ העונג בזה הוא בחי' עונג עצמי וכמו העונג בכל דבר הטוב בעצם כו'. ועז\"נ אכלו רעים שהן חו\"ב שיש בחי' עונג מורגש באוכל דחכ' דחיך אוכל יטעם בבחי' גילוי אוא\"ס\nשמאיר בחכ' כו', ונמשך גם בבחי' מל' וכמ\"ש באתי לגני כו' אכלתי יערי כו', וכמו הטעמים דסודות ורזין דאורייתא שמתוקים מדבש כו', ונק' דבשי ייני וחלבי כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ועדיין צ\"ל והלא בקרבנות נא' ג\"כ ריח נחוח. הענין הוא דריח הוא מדבר חריף וקיוהא, והן בירורי הנצוצות דתהו, בחי' אורות תקיפים, וגם הכלים בתוקף מפני המיעוט, דבהתרחבות התוקף הוא ע\"פ הטעם, משא\"כ במיעוט, וכשנשברו ונפלו נעשה דבר קיוהא, וז\"ע הריחה ציקי קדרה, כי יש ענג עצמי שמדבר הערב בעצם, וכמו הענג במושכלות ובמדת הטוב, ויש ענג הבא מההפכי, וכמו בניצוח המנגד, ובהסרת העלמות, וכן הענג מהפסולת הנשאר בשולי הקדרה, שהחלוש יתאוה לריח חזק זה, וכך בת מלך בחי' מל' שבה מתגלים האורות דע\"ס שהן תיקון בעצם, הגם דהאורות ג\"כ נתבררו מאור דתהו, אך נכללו בבחי' התיקון וכמו בירור שני שנכלל באלקות, כן האורות נכללו ביסוד דא\"ק ונעשו עצם התיקון, וזהו ש' מ\"ה, והכלים ב\"ן דמ\"ה, וכמו אותיות דתושב\"כ, ובזה הוא עונג עצמי אכלו רעים, ונמשך גם במל' באתי לגני אכלתי.</span>"],[3601330622,"<b>ריז)</b> אך בחי' פסולת השפע דאצי' הוא שנשאר למטה בבי\"ע, וכמ\"ש בע\"ח דמה שהי' אפשר להתברר וליכלל באצי' נכלל בבחי' קדושת אלקות דאצי' (והיינו שנעשה בבחי' ש' מ\"ה כו' כנ\"ל), והשאר נפל לברי' ומברי' ליצי' ומיצי' לעשי' כו', וע\"ה שגם בזה הי' הבירור מלמע' כנודע, מ\"מ הרי נשאר מה שלא נתברר והוא בחי' נוגה דבי\"ע כו', וגם מה שנתברר לא נתברר בבחי' בירור בשלמות דהרי כללות בי\"ע הו\"ע ש' ב\"ן כו', דאצי' בכלל הוא ש' מ\"ה ובי\"ע בכללות בחי' ש' ב\"ן כו'. דהנה ש' ב\"ן בעבודה הוא האה' שע\"פ טו\"ד, והיינו האה' שע\"י השגה והתבוננו' כו', ועילוי המדרי' בזה הוא דהאה' היא מצד הדעת כשמכיר את בוראו כי הוא חייך ועי\"ז מתעורר באה' כו', והיא הבחירה בטוב, וכנגד זה יש בלעו\"ז הבחירה ברע ר\"ל והו\"ע זה וזה שופטן כו' וכמ\"ש במ\"א (דד\"ע הוא שמכיר את הא\"ס שלא נדע שלמע' מבחי' ידיעה והשגה והוא בחי' הטוב בעצם דנגד בחי' זו לא יש לעו\"ז כו', אבל ד\"ת שהיא ההכרה בהאלקות שבא בבחי' השגה יש כנגד זה לעו\"ז כו', והעיקר הוא משום דבבחי' ד\"ת הגם שמכיר\nכי הוא חייך מ\"מ הרי יש בזה תערובות עצמו כו', דא\"ז ההכרה בעצם אוא\"ס שהוא חיי החיים כ\"א מה שהוא חייו כו', ומפני התערובות עצמו שבזה יש מקום כו'), וגם שהאה' היא במורגש וע\"כ יכול להיות בזה אחיזה כו', והרי ידוע דכללות עבודת המלאכים הוא בבחי' ד\"ת דע\"כ נק' בש' בהמות וחיות כו', ובבחי' אהוי\"ר מורגשת כו', וע\"כ הן בחי' ש' ב\"ן כו'. ובפרט מה שיורד בעולם העשי' ובעולם התחתון שזהו פסולת בחי' השפע העליונה, וכמו שמפסולת השפע דג\"ע דעשי' נמשך שרש התענוגים הגשמי' דעוה\"ז כו', ופסולת השפע זהו כמשל ציקי קדרה שנשאר בשולי הקדרה כו', ואע\"פ דעונג זה דציקי קדרה הוא באין ערוך כלל לגבי העונג העצמי דבמטעמים העליונים דאור ש' מ\"ה כו', מ\"מ בזה דוקא הריחה ריח שמשיב הנפש כו', והיינו מה שעולה ומתברר מרפ\"ח ניצוצות דתהו ששרשן בבחי' גבו' עליונות דאורות דתהו שיש בהם חיות רב בתגבורת אור חזק ביותר, שמפני זה לא יוכלו הכלים לסבול את האור ונפלו למטה כו', ובנפילתן למטה נעשו בבחי' רשפי אש החום הקשה ברצון חזק ותוקף גדול, שהן בחי' גבו'\nקשות דב\"ן דנוגה למטה כו'. אך ע\"י הבירור נעשה בהם הרצוא ג\"כ בבחי' תוקף וכמו ורב תבואות בכח שור דוקא שעי\"ז נעשה מהם ריח חזק להשיב את הנפש בבחי' תוס' אור וחיות חדש מבחי' אורות דתהו שלמע' מתיקון כו', וכמו הדבר החריף וקשה כשנהפך לטעם טוב וערב לנפש להחיותה ולחזקה מחלישותה ביותר כו', כמו\"כ הפך הגבו' הקשות דנוגה ואף בגבורות עליונות דב\"ן דמרכבה העליונה דפני ארי' ופני שור דקדושה בביטול היש לאין כו', שזהו בחי' הגבו' דתהו שקדום לתיקון כו', שיש בזה יתרון מע' מגוף האור וה\"ז מחזק כבי' לב אדה\"ע בבחי' תוס' אור רב ביותר כו'. וזהו שא' שהריחה ציקי קדרה דבת מלך עילאה בחי' מל' דאצי' כשיורדת למטה בבי\"ע שהיא בבחי' חלישות ומיעוט האור וכמא' לכי ומעטי א\"ע כו', וגם יכול להיות בבחי' חולי מצד ריבוי ההעלמות וההסתרים דבמדרי' התחתונות אינם יכולים לקבל בחי' העונג העליון כו', אך בירידתה ה\"ה מבררת בירורים בנוגה דבי\"ע כו', וזהו שהריחה ציקי קדרה שהוא מה שעלה ריח החזק מבחי' בירורי דרפ\"ח כו' שנפל למטה שזהו מבחי' הפסולת דאצי'\nכו' והוא שעולה בבחי' או\"ח כו', נעשה מזה ריח חזק להשיב הנפש ביותר כו', וכמו וירח ריח בגדיו כו', דבגדי עשו החמודות היו משיורי הז\"מ דתהו שלא"],[3601330623,"נתבררו עדיין והוא ג\"כ בחי' חשמל העליון שנפל למטה בחטא עה\"ד כו', והו\"ע כתנות עור דאדה\"ר כו', שע\"י הבירור עולה למע' מע' בגבו' עליונות דאו\"ח שלמע' מבחי' או\"י כו', וכן בירידת המל' בהיכלות דב\"ן דנוגה לברר בירורים דנוגה כו' הריחה ציקי קדרה שיש בזה עונג נפלא יותר מבחי' עונג העליון שבחכ' ומדות דאצי' כו'. וזהו הטעם והסבה מה שבחי' המל' מתצמצמת להיות בבחי' מלך על עם שזהו ירידה וצמצום גדול להיות כתר וראש לבי\"ע בק\"כ צרופי' דש' אלקי' כו', שזהו ירידה דבחי' חכ' שבדבור להיות מקור להוות ולהחיות נבראים בע\"ג כו', דכ\"ז הוא רק בשביל בירור נוגה דבי\"ע שנפלו שם הרפ\"ח ניצוצות כו'. וז\"ש ותקם בעוד לילה ותתן טרף לביתה, טרף בגימט' רפ\"ח ע\"ה שזהו ירידת המל' בבי\"ע לברר בירורים כו', וכמ\"ש בזהר בלילא אזלת לטורי חשוכא ומתמן ארחית מזונא כו', והו\"ע הריחה ציקי קדרה בחי' ריח החזק מבירורי הניצוצות כו'. ונמצא דענין הריח הוא שנעשה מניצוצות דתהו כו'. ועוד שהריח הוא בחי' מקיף וכמא' שהריח הוא דבר שהנשמה נהנה ממנו ולא הגוף והיינו\nשאינו נכנס בגוף בבחי' פנימי כמו המאכל שנעשה דם ובשר כבשרו כו', משא\"כ הריח שאינו נכנס בגוף ומגיע בבחי' המקיפים דנפש דוקא כו', וידוע דאורות דתהו הן אורות מקיפים שלמע' מהתלבשות בכלים כו', דמה שהי' להם קצת התלבשות בכלים הי' זה בבחי' כללי' לבד שז\"ע עגולים כו' וכמ\"ש במ\"א, ומזה מובן ג\"כ דריח הוא מצד בירורי הניצוצות שנמשך עי\"ז בחי' או\"מ כו' (ויש ג\"כ בחי' ריח במדרי' דתיקון וכמו חמינא בריח דלבושייכו דהן הלבושים דמצות כו', וכמו והריחו ביראת ה' כו', וכ\"ז הוא בבחי' מקיף כו', ועיקר הריח הוא שבא מדבר חריף והיינו הניצוצות כו', ובאמת גם בחי' הריח דתיקון הנ\"ל הוא מבחי' הבירורים רק שזהו מה שכבר נכלל בבחי' התיקון כו', אבל ביסודו ועיקרו הוא מבחי' הבירורים דתהו כו', דכללות ענין הריח הוא מבחי' בירורי הגבורות דוקא כו').\n<span data-k=\"ks\"><b>קיצור.</b> והנה הפסולת הנשאר מאצי' נפל לבי\"ע ונתברר שם, ונשאר נוגה דבי\"ע, וגם הבירור אינו בשלימות והוא בחי' ב\"ן, ובעבודה ד\"ת, דהגם שזהו הבחירה בדעת, מ\"מ יש בזה תערובות עצמו והרגש, ויכול להיות ח\"ו הבחירה להיפך, משא\"כ ד\"ע שהוא ההכרה בעצם אוא\"ס, וכן המלאכים עבודתם בבחי' ד\"ת, אמנם הניצוצות דתהו שרשם בבחי' תגבורת החיות, ובנפילתן נעשו גבו' קשות, הנה בהבירור נעשה ריח חזק תוקף הרצוא, ובחי' מל' בבי\"ע שהיא בבחי' מיעוט וחלישות הריחה ציקי קדרה, שהענג גדול ביותר מכל הגילוים, וזהו ריח בגדיו בגדי חמודות כתנות עור כשמתברר, ובשביל זה מתצמצמת ויורדת לבי\"ע, וזהו שריח הוא בחי' מקיף או\"מ דתהו, וגם בתיקון יש ריח והוא מה שנכלל בעצם התיקון.</span>\n<b>ריח)</b> ועפ\"ז יובן מה שבקרבנות נא' ריח ניחוח לה' שהן בבחי' ריח כו', להיות דהקרבנות הן בירורי הניצוצות שבנוגה, דהבהמה הגשמי' היא תחת ממשלת ק\"נ וע\"י שנשרפת באש שלמע' מתבררים הניצוצו' ונכללים באלקות כו', דבעבודה הו\"ע בירור הנה\"ב וכמ\"ש אדם כי יקריב מכם קרבן כו', והוא לברר ולהפך מדות טבעי' דנה\"ב לאלקות כו', וזהו מה שעיקר הקרבן הוא הקרבת חלב"],[3601330624,"ודם והיינו דרתיחת הדמים דנה\"ב בחמימות אש התאוה יתהפך להיות בבחינת רשפי אש האה' כו', והחלב הו\"ע התענוג דתענוגים הגשמי' יתהפכו להיות תענוג אלקי בהשגה וידיעה אלקי' ולהתענג על ה' כו' (ועיקר ענין הקרבנות הוא בבחי' אתכפי' לבד להיות דעבודת הקרבנות בד\"כ היא עבודה שע\"פ טו\"ד כו', וזהו משארז\"ל אע\"פ כו' מצוה להביא מן ההדיוט דהיינו בחי' האה' הבאה ע\"י התבוננות כו', וגם האש שלמע' א\"ז בחי' אש ה' וכמ\"ש לא באש כו', וכמ\"ש במ\"א שהיא ההתבוננות בשרש ומקור הנה\"ב וכמו בעבודת המלאכים וכה\"ג שזה מסייע בהביטול דנה\"ב כו', דכ\"ז הוא בבחי' אתכפי' לבד כו', רק בעבודת הצדיקים דעיקר עבודתם הוא מצד הנשמה ובחי' האש שלהם הוא אש ה' וכמ\"ש בת\"ז אית אש ואית אש כו', ה\"ז בבחי' אתהפכא ממש שנהפך מהות הנה\"ב ונכלל באלקות כו' וכמ\"ש במ\"א). וזהו שהקרבנות הן בחי' ריח בבחי' הבירור דנוגה דנה\"ב ומגיע בבחי' המקיף כו', אמנם עיקר ענין הריח שבא מדבר חריף וחזק ומשיב את הנפש הוא ריח הקטרת דוקא כו'. דהנה ההפרש בין ריח הקרבנות לריח הקטרת הוא כמו\nההפרש בין ריח שבמאכל לריח הבשמים שאינו דבר הנאכל כו', דהרי הקרבנות הן בחי' לחם וכמ\"ש את קרבני לחמי כו', דפעולת הלחם הוא רק לחזק החיות פנימי לבד לא בבחי' התחדשות חיות כו' רק שבזה יש ג\"כ תוס' חיות שמתחזק בזה כחו בבחי' תוס' אור והיינו מפני שנמשך החיות ממקורו מהאו\"מ שעי\"ז מתוסף כחו, וזהו ע\"י הריח שבמאכל שמגיע בהאו\"מ כו', וזהו חמרא וריחא פקחין שמתוסף התחכמות עי\"ז והוא ע\"י הריח כו', אך מה שמגיע בהמקיף שבנפש הוא בהאו\"מ השייך אל הפנימי לבד ומה שנמשך בזה א\"ז שהמקיף מאיר כ\"א מה שמוסיף אור וחיות בהפנימי כו' (ועמשנת\"ל פקע\"א). וכמו\"כ הוא הדוגמא למע' דריח הקרבנות מגיע בבחי' מקיף עליון היינו בחי' כי לא אדם הוא, והיינו ע\"י הריח דבירורי הניצוצות שעי\"ז מתוסף אור וחיות בבחי' אדה\"ע כו', ומ\"מ אין האו\"מ מאיר בגילוי כ\"א מה שמתוסף בהאו\"פ כו', אבל ריח הקטרת הוא כמו הריח שמשיב את הנפש היינו שמגיע בעצם הנפש שלמע' מהגילוים וממשיך להיות גילוי הנפש כו', וזהו יתרון המע' בריח הבושם על הריח שבמאכל, דריח שבמאכל מגיע רק\nבהגילוים שבנפש דהיינו בהגילוי או\"מ ולכן אינו משיב את הנפש רק מחזיק כחו כו', אבל ריח הבושם מגיע בעצם הנפש שלמע' מהגילוי ומשיב את הנפש היינו להיות הגילוי מהעצם כו', וכמו\"כ הו\"ע הקטרת שמגיע בבחי' עצמות א\"ס שלמע' מבחי' הגילוי להיות בחי' הגילוי והיינו דבחי' אוא\"ס דכי לא אדם הוא מאיר בגילוי כו'. וביאור הענין הוא כמשנת\"ל פרי\"ג דהריח מגיע בעצם חבור הנשמה בהגוף שאינו עדיין בבחינת התפשטות וגילוי (גם לא בבחי' או\"מ כו'), ויובן זה למע' ע\"פ משנת\"ל פר\"ד בשם האדר\"ז דבהאי מזלא פשיט פשיטותא דקוטרא עילאה דעתיק הוא בחי' קשר עליון שעי\"ז מתקשר א\"ס עם העולמות כו', וזהו כמו עד\"מ חבור עצם הנשמה עם הגוף כו'. וז\"ע הקטרת שמגיע בבחי' פנימי' הכתר כו', דקרבנות עם היות דרזא דקורבנא עולה עד רזא דא\"ס כ\"ז הוא בבחי' חיצוני' הכתר כו', וזהו ג\"כ ע\"י הבירורים דקרבנות כו', דהנה נת\"ל פרי\"ב דעבודת קרבנות בד\"כ הוא העבודה שע\"פ טו\"ד, וידוע דעבודה שע\"פ טו\"ד היא בבחי' או\"פ בחי' ממכ\"ע כו', ומה שהקרבנות מגיעים בבחי' כתר זהו ע\"י ריח\nהבירורים כו', אך זהו רק בבחי' חיצוני' הכתר וההמשכה היא רק מה שנמשך תוס' אור בפנימי כו'. אבל הקטרת מגיע בבחי'"],[3601330625,"פנימי' הכתר ונמשך עי\"ז דבחי' אוא\"ס יאיר בגילוי כו', ומ\"מ ההמשכה בגילוי רק מבחי' חיצוני' הכתר כו', דכשם שהקרבנות ע\"ה שמגיע בבחי' או\"מ מ\"מ הרי ההמשכה היא רק גילוי האו\"פ כו', כמו\"כ קטרת הגם שמגיע בבחי' פנימי' הכתר מ\"מ ההמשכה היא בחינת החיצוני' לבד כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וזהו דקרבנות שזהו בירור דנוגה, דם הוא רתיחת הדמים, וחלב תענוג, ה\"ז בחי' ריח שמגיע בבחי' האו\"מ, אך הוא כמו ריח המאכל, שגם בהריח לא יש התחדשות החיות רק מה שמתוסף חיות בהאו\"פ, וכ\"ה בעבודה ולמעלה שאין האו\"מ מאיר בגילוי רק שמתוסף בהאו\"פ, והוא מפני שמגיע בבחי' חיצוניות הכתר, וריח הקטרח הוא כמו ריח הבשמים שמשיב את הנפש מפני שמגיע בעצם הנפש, ולמעלה הוא בחי' קוטרא עילאה דעתיקא, והגילוי הוא בחי' האו\"מ אך רק בחי' חיצוניות הכתר.</span>\n<b>ריט)</b> ויובן זה ע\"פ משנת\"ל פ' ר\"ד בענין קשר דעתיק שיש ב' ענינים בחי' ההתקשרות דאוא\"ס בעולמות וההתקשרות בנש\"י, שיש הפרש גדול ביניהם, דהנה כ\"ע הוא בחי' ממוצע בין אוא\"ס לעולמות ונש\"י בב' מדרי' שבו בחי' עתיק ואריך כו', וידוע שיש ב' מדרי' בממוצע הא' ממוצע המפסיק וכמו עד\"מ שני בנ\"א שנאחזים בחבל זה בראשו הא' וזה בראשו השני שעי\"ז הם מתחברים הרי החבל מפסיק ביניהם כו', ויש ממוצע שאינו מפסיק כו'. וידוע המשל בזה כמו המתורגמן שבין המשפיע להמקבל וכמו בימיהם שהיו מעמידין מתורגמן מפני שהחכם הדורש הי' מובדל בערך שהעם לא היו יכולים לקבל ממנו, ע\"כ הי' צ\"ל מתורגמן שקיבל ההשפעה מהחכם ובאה ההשפעה בכליו וחושיו שהן בערך המקבלים שממנו היו יכולים לקבל כו', הרי המקבלים קבלו את האור שכל כמו שהוא לפי חושי המתורגמן אבל עצם שכל הרב הוא בהעלם לגמרי בהם כו', וגם אצל המתורגמן שכל הרב עומד בבחי' הבדלה ומה שבא בכליו וחושיו א\"ז שההשפעה שקבל מהחכם בא בחושיו, דמאחר שהחושים שלו אינם כמו חושי החכם (דהחושים שלו יש להם\nערך אל המקבלים יותר מלהמשפיע כו'), ע\"כ אין ההשפעה יכולה לבא בחושים שלו רק מה שמקבל ההשפעה אבל לא שתשתנה לפ\"ע חושיו כו', כ\"א זהו מה שמשכל המשפיע שמקבל נמצא אצלו שכלי שזהו הוא שמשפיע כו', וכמו שמענין א' בא עוד ענין כו', הרי שגם אצל המתורגמן עומד השפעת הרב בהבדלה, ומה שמשפיע אל העם הוא רק מה שנמצא משכל הרב שכל אצל המתורגמן כו', ומ\"מ א\"ז שכל המתורגמן מצ\"ע כ\"א מה שבא משכל המשפיע כו' (ועמ\"ש מזה בדרוש יו\"ט של ר\"ה, רס\"ו). והדוגמא בבחי' הממוצע דכ\"ע דבחי' עתיק הוא נעתק ונבדל לגמרי רק שממנו נמצא בחינת אורות דאריך וכמ\"ש בע\"ח שמ\"א פ\"ג, וזהו מה שמאיר בנאצלים כו', ומ\"מ זהו ע\"י שבחי' הא\"ס נעשה בבחי' עתיק לעולמות כו', דהרי הא\"ס מצ\"ע מובדל לגמרי ואינו בערך דהעתקה כלל כו' וכמשנת\"ל פקצ\"ו, וע\"י שנעשה בבחי' עתיק הנה האורות הנמצאים ממנו שזהו בחי' אריך הוא שמאיר בנאצלים כו'. וכמו\"כ הוא בענין הקטרת דלהיות שמגיע בבחי' עתיק בחי' פנימי' הכתר עי\"ז הוא ממשיך בחי' אריך והוא גילוי בחי' ומדרי' זו כו', אבל מ\"מ הוא גילוי בחי' חיצוני' הכתר לבד כו'. וזהו בההתקשרות"],[3601330626,"שבעולמות שהממוצע מפסיק כו', משא\"כ ההתקשרות עם נש\"י הוא בחי' התקשרות עצם בעצם כו' שאין הממוצע מפסיק כו' וכמ\"ש במ\"א. וזהו ההפרש בין הקרבנות לקטרת, דקרבנות ע\"ה שזהו ג\"כ ענין הבירורים מ\"מ להיות שזהו בחי' אתכפי' והוא בבחי' התפשטות דנה\"ב לבד ע\"כ מגיע למע' רק בבחי' האו\"מ השייך אל הפנימי כו', אבל קטרת שהו\"ע רעו\"ד שפועל בעצם המהות דנה\"ב בבחי' אתהפכא כו', וזהו שהדבר החריף נהפך לדבר ערב כו', ה\"ז מגיע בבחי' עצמות א\"ס וההמשכה היא דבחי' האו\"מ דהיינו בחי' האוא\"ס שלמע' מהשתל' נמשך ומאיר בבחינת גילוי ממש כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש במד\"ר ע\"פ וירח ה' את ריח כו' הריח ריח של אאע\"ה כו', והיינו בחי' הריח דמס\"נ בפו\"מ בבחי' ביטול עצם המהות כו', שעי\"ז דוקא נמשך מבחי' עצמות אוא\"ס כו', וה\"ז למע' הרבה מההמשכה דקרבנות, הגם דרזא דקורבנא עולה עד רזא דא\"ס שמעורר וממשיך מבחי' האו\"מ כו', מ\"מ ההמשכה היא בחי' האו\"פ רק שהוא בבחי' תוס' אור שהו\"ע חיזוק החיות אבל לא חיות חדש כו'. ובכדי להמשיך המשכה חדשה מבחי' עצמיות אוא\"ס זהו דוקא ע\"י ריח הקטרת שהוא הביטול בעצם המהות כו', וזהו ג\"כ שאו' כאן שהריח ריח של אברהם אע\"ה שהוא בבחי' ביטול בעצם המהות ועי\"ז דוקא לא אוסיף עוד לקלל כו'. דהנה גבי המבול הי' צ\"ל ההמשכה ע\"ד להשיב את הנפש כו', שהרי בשעת המבול הי' בבחי' סילוק האור וכמ\"ש ה' למבול ישב ישב בלחודוהי כו', ואותה שנה לא שמשו המזלות כו', שנשתנה כל ס' ההנהגה כו', וע\"כ הי' צ\"ל המשכה חדשה ממש כו'. ועז\"א שהריח ריח של אברהם אבינו וחנני' מישאל ועזרי' שע\"י מס\"נ בפו\"מ בבחי' ביטול כל המהות עי\"ז ממשיכים גילוי אור חדש ממש כו',\nוז\"ש שם ג\"כ במד\"ר שהריח ריח דורו של שמד כו', והיינו המניעות ועכובים על קיום המצות בפו\"מ ועומדים חזק במס\"נ כו', שממשיכים עי\"ז גילוי אור חדש כו'. וזהו וירח ה' את ריח הניחוח דע\"פ פשוט הוא ריח הקרבנות, וי\"ל שזהו ההמשכה דבחי' יחוד חיצוני דאו\"א שהמשיך נח כו', ובמד\"ר מבאר שהריח ריח של אברהם אבינו ע\"ה כו', היינו בבחי' ביטול המהות שעי\"ז ממשיכים גילוי אור חדש ממש כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והענין דהנה קוטרא דעתיקא הוא שמחבר אוא\"ס עם עולמות ונש\"י, ויש הפרש גדול ביניהם, כי יש ממוצע המפסיק וכמו המתורגמן דשכל הרב אצלו בהבדלה, רק שממנו נמצא אצלו שכל, וזה הוא שמשפיע להעם, וכמו\"כ עתיק האצילה אריך וזהו שמאיר בנאצלים, ובנש\"י הוא התקשרות עצם בעצם, וזהו ריח הקרבנות שמגיע בהאו\"מ והגילוי תוס' חיות בהפנימי, וריח הקטורת מגיע בקוטרא דעתיקא והגילוי הוא בחי' אריך. וזהו וירח הריח ריחו של אאע\"ה והוא הריח דמס\"נ שז\"ע ריח הקטרת שנמשך אור חדש.</span>"],[3601330627,"<h3>בס\"ד. ש\"פ לך לך, תרד\"ע</h3>\n<b>ויאמר</b> ה' אל אברם לך לך מארצך וממולדתך כו', וצ\"ל מהו\"ע לך לך דהול\"ל לך מארצך מהו הכפל ל' לך לך. גם צ\"ל מהו האריכות דמארצך וממולדתך כו', והלא העיקר צריכים להודיע להיכן שילך, וזה מעצמו מובן שילך ממקומו שהוא בו, ומהו\"ע מארצך כו'. ובמד\"ר אי' למה הי' אברהם אבינו דומה לצלוחית של אפופלסימון מוקפת צמיד פתיל ומונחת בזווית ולא הי' ריחה נודף כיון שמטלטלים אותה ממקום למקום ריחה נודף, כך א\"ל הקב\"ה לאברהם טלטל עצמך ממקום למקום ועי\"ז שמך מתגדל. וצ\"ל מהו המשל מהריח שיהי' ריחו נודף וע\"י הטלטול דוקא, ומהו\"ע הגדלת השם כו', ולכאו' מהו המעלה דהגדלת השם גבי אברהם שהי' בתכלית הביטול והשפלות וכמ\"ש ואנכי עפר ואפר כו'. ולהבין כ\"ז ילה\"ק משנת\"ל ההפרש בין ריח הקרבנות לריח הקטרת, דריח הקרבנות הוא ריח שבמאכל דעיקר ענין הקרבנות הוא בחי' לחם כמ\"ש את קרבני לחמי כו', ובעבודה הו\"ע האה' שע\"פ טו\"ד הבאה מצד השגה והתבוננות שההמשכה שעי\"ז הוא בחי' או\"פ כו', ויש בזה ג\"כ בחי' ריח מצד הבירורים דקרבנות דכל בחי' ריח הוא\nמהבירורים דוקא כו', אך להיות שהוא העבודה שע\"פ טו\"ד ע\"כ הבירור שבזה הוא רק בההתפשטות דנה\"ב ובבחי' אתכפי' לבד כו'. וע\"כ אינו נמשך בזה גילוי האו\"מ ממש כו', אבל ריח הקטרת הוא ריח הבושם שמשיב את הנפש ובעבודה הו\"ע רעו\"ד שלמע' מטו\"ד ועי\"ז נעשה הבירור דעצם מהות הנה\"ב כו', שזה מגיע בבחי' עצמו' א\"ס כמו עד\"מ עצם חבור הנשמה עם הגוף כו', ונמשך גילוי אור חדש היינו גילוי האו\"מ כו', ומ\"מ ההמשכה היא מבחי' חיצוני' הכתר כו'.\n<b>רכ)</b> ולהבין בתוס' ביאור ההמשכה שע\"י ריח הקטרת שממשיכים גילוי האו\"מ דע\"ה שהעבודה היא בבחי' רעו\"ד ומ\"מ ההמשכה היא מבחי' חיצוני' הכתר לבד כו', הענין הוא דהנה הקטרת הקטורת הי' על המזבח הפנימי שבהיכל, וידוע דההיכל הוא בחי' אצי' כנודע בהג' דיורין שבמקדש כו', שהן נגד ג' עולמות הכללים דחצר אוה\"מ נגד עולמות בי\"ע והאוה\"מ שהוא ההיכל נגד עולם האצי', וקדה\"ק נגד עולמות הא\"ס שלפני האצי' כו', וע\"כ העבודה שבהיכל שזהו בבחי' אצי' ה\"ז מה ששייך להשתל' כו', ולכן גם בחי' הקטרת שזהו העבודה דבחי' רעו\"ד ה\"ה ג\"כ מה ששייך להשתל', ובנפש היינו העבודה שבס' והדרגה כו'. והענין דע\"ה דקטרת הו\"ע התקשרות שזהו האהבה והרצוא שמצד התקשרות עצמי' הנשמה באוא\"ס וכמא' בחד קטירא כו' וכמשנת\"ל פרי\"ב, מ\"מ התעוררות זאת היא ע\"י התבוננות בבחי' הפלאה והבדלה דאוא\"ס ב\"ה כו', והיינו דרעו\"ד זאת אינה באה מן המנגד כ\"א מהנשמה עצמה ע\"י ההרגשה דאוא\"ס המופלא ומובדל כו', וא\"כ ה\"ז עבודה שבס' והדרגה מאחר שזהו מצד הנשמה עצמה כו', דמה שבא מצד\nהמנגד ה\"ז בבחי' או\"ח כו', אבל מה שמצד הנשמה עצמה הגם שזהו למע' מטו\"ד מ\"מ ה\"ז בבחי' או\"י שהיא עבודה שבס' והדרגה כו', רק שזהו במקיפים דנפש דשם הוא הרגשת בחי' אוא\"ס המופלא כו', דמה שמורגש בכחות גלוים דנפש בד\"כ הוא בחי' הארה שבאה בבחי' התלבשות כו', והרגשת האוא\"ס שמופלא ומובדל מהעולמות הוא במקיפים דנפש וההתעוררות היא למע' מטו\"ד"],[3601330628,"בבחי' התקשרות עצמי' כו', ומ\"מ ה\"ז בבחי' או\"י כו', והוא בחי' מקיף דחי' כו', וע\"י האו\"מ דנשמה מתבטל הנה\"ב בעצם מהותו כו'. דהנה העבודה דאו\"פ הגם שפועל ג\"כ ביטול בכחות הטבעי' דנה\"ב, מ\"מ אינו משתנה בזה בעצם מהותו כו' (והיינו שלא יתבטל בעצם מהותו וכמו\"כ לא ישתנה מאכזרי לרחמני וכה\"ג דהכל א' הוא), וזהו מפני שהאה' היא מתיישבת אצלו וביכולת כלי הלב לסובלה עד שאדרבה נתמלאת האה' בתוך כלי הלב, וענין המילוי הוא שמתרווה צמאון הלב בה, וכמו השותה מים לצמאונו שיסוד האש שהי' תחלה בהתגברות בלבבו נתקרר ע\"י השתי' כי הגיע לדבר חפצו ותשוקתו, כן מי שמרווה צמאונו ותשוקתו לה' ע\"י האה' לאלקו' בתפלה (והיינו שמסתפק בקירוב ובדבקות נפשו בהאה' האלקי' כו', שהרי בההתבוננות כשמשיג הענין הרי הענין האלקי מאיר בנפשו ובהאה' מתקרב נפשו אל האור האלקי ובזה הוא מרווה צמאונו כו', ובאמת א\"ז עבודה אמיתי' כי אין בזה תכלית עדיין, דהגם שבהאה' ה\"ה מתקרב אל אלקות מ\"מ אין בזה עדיין גילוי ממש בנפשו רק מה שעי\"ז הוא עומד בדרגא עליונה יותר\n(וה\"ז בד\"כ כמו החקיקה מבחוץ כו', ומובן שאינו דומה ממש דשם הרי לא יש עדיין גילוי או\"פ כלל שהרי גם ההשגה והתבוננות בזה אינו בבחי' השגה פנימי' כו' וכמ\"ש במ\"א, וכאן הרי עכ\"פ יש בחי' הגילוי מרחוק כו'), אבל אין בו עדיין גילוי אור כו', ותכלית האה' היא העבודה מאה' כו' וכמ\"ש בסש\"ב, והיינו) שיעבוד משו\"ז כל היום במצות מעשי' בסו\"מ וע\"ט בפו\"מ וכן יעסוק בתו' כו' (ויש בזה חילוקי מדרי' אם שהעסק בתומ\"צ כל היום הוא בחיות פנימי שמאיר בו עי\"ז האור האלקי בגילוי בבחי' או\"פ ממש כו', ובזה הוא שמרווה צמאונו צמאון האה' שבתפלה והוא בחי' השוב שאחר הרצוא כו', והו\"ע והיו הדברים האלה שאחר ואהבת דבד\"ת הכתוב מדבר כו', דבאמיתי' העבודה בזה הוא שבהעסק התומ\"צ הוא בשוה ממש כמו בעת התפלה בבחי' האור והגילוי ובבחי' הקירוב והדביקות כו', ואדרבה שבזה מאיר בו האור בבחי' פנימי ממש ובבחי' דבקות ממש כו', וכמ\"ש בסש\"ב והמקיימן באמת הוא האוהב כו' וא\"א לדבקה כ\"א כו', הרי עיקר הדבקות והגילוי הוא בקיום המצות כו', כי באמת בעבודה אמיתי' האה'\nהיא רק מה שחפץ לדבקה בו כו', והדבקות והגילוי הוא דוקא בקיום התומ\"צ שאח\"כ כו' (ויותר גם מהגילוי שבההתבוננות (ר\"ל לא מיבעי שהוא יותר מהגילוי שבהאהבה אלא גם יותר מבההתבוננות) שג\"ז הוא לא בבחי' או\"פ בבחי' גילוי ממש כו', משא\"כ בעסק התומ\"צ הוא בבחי' או\"פ ממש כו', רק שאינו בבחי' התפעלות והתלהבות כמו בתפלה כו', וגם שבתומ\"צ שאחר הרצוא דתפלה מאיר גילוי אור עליון יותר מבההתבוננות כו', וכידוע שבהשוב מאיר גילוי אור עליון יותר מבהרצוא כו' וכמ\"ש במ\"א), ומ\"ש בכהאריז\"ל דאחר התפלה מסתלקים המוחין דגדלות, צ\"ל מפני שבכל היום יש זמנים שבהתעלמות כו', אבל בשעת עסק התו' והמצות י\"ל שהן בשוה כמו בתפלה ועוד למע' במדרי' כו', וזה בדר\"כ בנשמו' גבוהות אך בעבודת כל אדם הנה העבודה כל היום היא בבחי' רושם לבד מה שנשאר מהאה' שבעת התפלה כו', ומ\"מ בעסק התורה וקיום המצות שאחר התפלה מאיר לו האור והגילוי ובבחי' פנימיות בנפשו שמרווה צמאונו בזה כו'). והנה כ\"ז לא יעשה שינוי במזג טבעי' דמו ובשרו הטבעי' בעצם מהותו, כי מאחר שנכנסת אור האה' האלקי' בכלי הלב ונתרווה צמאונו כו', הרי כלי הלב שהם מקור הדם והבשר הטבעי' מלבישי' ומכסים"]]});
